# =====================================================================
$ErrorActionPreference = 'Stop'
$script:NoZapret = $false

# --- права администратора (нужны для WinDivert) ---
$principal = New-Object System.Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Start-Process powershell.exe -Verb RunAs -WindowStyle Hidden -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -STA -File `"$PSCommandPath`""
    exit
}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Windows.Forms, System.Drawing
Add-Type -AssemblyName System.Net.Http

$script:AppDir = Split-Path -Parent $PSCommandPath
# настройки живут в %APPDATA%\ZapretStudio: переживают обновление и распаковку новой версии в другую папку (сборка 5)
$script:LocalSettings = Join-Path $script:AppDir 'zapret-studio.json'
if (-not (Test-Path -LiteralPath $script:LocalSettings)) { try { $pp = Join-Path (Split-Path -Parent $script:AppDir) 'zapret-studio.json'; if (Test-Path -LiteralPath $pp) { $script:LocalSettings = $pp } } catch { } }
$script:SettingsPath = $script:LocalSettings
$script:CfgDir = $script:AppDir
function Test-CfgFile([string]$f) { try { $t = Get-Content -LiteralPath $f -Raw -Encoding UTF8; if (-not $t -or -not $t.Trim()) { return $false }; $null = $t | ConvertFrom-Json -ErrorAction Stop; $true } catch { $false } }
try {
    $cd = Join-Path ([Environment]::GetFolderPath('ApplicationData')) 'ZapretStudio'
    if (-not (Test-Path -LiteralPath $cd)) { [void](New-Item -ItemType Directory -Path $cd -Force -ErrorAction Stop) }
    $np = Join-Path $cd 'zapret-studio.json'
    if (-not (Test-Path -LiteralPath $np)) {
        if ((Test-Path -LiteralPath $script:LocalSettings) -and (Test-CfgFile $script:LocalSettings)) { Copy-Item -LiteralPath $script:LocalSettings -Destination $np -Force -ErrorAction Stop }
        elseif (Test-Path -LiteralPath ($np + '.bak')) { Copy-Item -LiteralPath ($np + '.bak') -Destination $np -Force -ErrorAction SilentlyContinue }
    }
    $script:CfgDir = $cd; $script:SettingsPath = $np
} catch { $script:SettingsPath = $script:LocalSettings; $script:CfgDir = $script:AppDir }

try {
    $created = $false
    $script:Mutex = New-Object System.Threading.Mutex($true, 'Global\ZapretStudioSingleton', [ref]$created)
    if (-not $created) { exit }

$script:IcoB64 = ''
$script:IcoActiveB64 = ''
$script:LogoB64 = ''
# ---------------------------------------------------------------- заставка при запуске
function Pump-Ui {
    $f = New-Object Windows.Threading.DispatcherFrame
    [void][Windows.Threading.Dispatcher]::CurrentDispatcher.BeginInvoke([Windows.Threading.DispatcherPriority]::Background, [Windows.Threading.DispatcherOperationCallback]{ param($o) $o.Continue = $false; $null }, $f)
    [Windows.Threading.Dispatcher]::PushFrame($f)
}
function Close-Splash {
    $sp = $script:Splash
    if (-not $sp) { return }
    $script:Splash = $null
    try { $sp.Close = $true } catch { }
}
