                    $bi.BeginInit(); $bi.StreamSource = New-Object IO.MemoryStream -ArgumentList (, [Convert]::FromBase64String([string]$sync.Logo)); $bi.CacheOption = 'OnLoad'; $bi.EndInit(); $bi.Freeze()
                    $w.FindName('SpLogo').Source = $bi
                } catch { }
                $w.FindName('SpSub').Text = [string]$sync.Slogan
                $sync.Ease = New-Object Windows.Media.Animation.CubicEase; $sync.Ease.EasingMode = 'EaseOut'
                $sync.Back = New-Object Windows.Media.Animation.BackEase; $sync.Back.EasingMode = 'EaseOut'; $sync.Back.Amplitude = 0.45
                $sync.Mk = {
                    param([double]$from, [double]$to, [int]$ms, [int]$delay, $ease)
                    $a = New-Object Windows.Media.Animation.DoubleAnimation
                    $a.From = $from; $a.To = $to
                    $a.Duration = New-Object Windows.Duration -ArgumentList ([TimeSpan]::FromMilliseconds($ms))
                    $a.BeginTime = [TimeSpan]::FromMilliseconds($delay)
                    if ($ease) { $a.EasingFunction = $ease }
                    $a
                }
                $mk = $sync.Mk; $e = $sync.Ease; $b = $sync.Back
                $total = [int]$sync.Ms
                $op = [Windows.UIElement]::OpacityProperty
                $sx = [Windows.Media.ScaleTransform]::ScaleXProperty; $sy = [Windows.Media.ScaleTransform]::ScaleYProperty
                $w.BeginAnimation($op, (& $mk 0 1 380 0 $e))
                $cs = $w.FindName('SpCardScale'); $cs.BeginAnimation($sx, (& $mk 0.94 1 650 0 $b)); $cs.BeginAnimation($sy, (& $mk 0.94 1 650 0 $b))
                $w.FindName('SpLogo').BeginAnimation($op, (& $mk 0 1 500 150 $e))
                $ls = $w.FindName('SpLogoScale'); $ls.BeginAnimation($sx, (& $mk 0.5 1 750 150 $b)); $ls.BeginAnimation($sy, (& $mk 0.5 1 750 150 $b))
                $r1 = & $mk 0 360 1400 0 $null; $r1.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
                $w.FindName('SpRot1').BeginAnimation([Windows.Media.RotateTransform]::AngleProperty, $r1)
