                $w.FindName('SpFillScale').BeginAnimation($sx, (& $mk 0 1 ($total - 250) 0 $sin))
                $sh = & $mk -60 320 1300 600 $null; $sh.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
                $w.FindName('SpShine').BeginAnimation([Windows.Media.TranslateTransform]::XProperty, $sh)
