                        $RA = [Windows.Media.RotateTransform]::AngleProperty
                        $qe = New-Object Windows.Media.Animation.QuadraticEase; $qe.EasingMode = 'EaseOut'
                        $qi = New-Object Windows.Media.Animation.QuadraticEase; $qi.EasingMode = 'EaseIn'
                        function Col([string]$h) { [Windows.Media.Color][Windows.Media.ColorConverter]::ConvertFromString($h) }
                        function Br([string]$h) { New-Object Windows.Media.SolidColorBrush (Col $h) }
                        function Tf($el) {
                            $g = New-Object Windows.Media.TransformGroup
                            $s = New-Object Windows.Media.ScaleTransform; $r = New-Object Windows.Media.RotateTransform; $t = New-Object Windows.Media.TranslateTransform
                            [void]$g.Children.Add($s); [void]$g.Children.Add($r); [void]$g.Children.Add($t)
                            $el.RenderTransform = $g; $el.RenderTransformOrigin = New-Object Windows.Point 0.5, 0.5
                            @{ S = $s; R = $r; T = $t }
                        }
                        function Put($parent, $el, [double]$x, [double]$y) { [Windows.Controls.Canvas]::SetLeft($el, $x); [Windows.Controls.Canvas]::SetTop($el, $y); [void]$parent.Children.Add($el) }
                        function Go($tr, $prop, [double]$a, [double]$z, [int]$ms, [int]$d, $ez) { $tr.BeginAnimation($prop, (& $mk $a $z $ms $d $ez)) }
                        function Keys($tr, $prop, $pts) {
                            $an = New-Object Windows.Media.Animation.DoubleAnimationUsingKeyFrames
                            foreach ($q in $pts) {
                                $kt = [Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds([double]$q[0]))
                                [void]$an.KeyFrames.Add((New-Object Windows.Media.Animation.LinearDoubleKeyFrame ([double]$q[1]), $kt))
                            }
                            $tr.BeginAnimation($prop, $an)
                        }
                        function ShakePts([int]$t0, [double]$amp, [int]$step, [int]$n) {
                            $o = New-Object Collections.ArrayList
                            [void]$o.Add(@($t0, 0))
                            for ($i = 1; $i -le $n; $i++) { $sg = 1; if ($i % 2) { $sg = -1 }; [void]$o.Add(@(($t0 + $i * $step), ($amp * $sg))) }
                            [void]$o.Add(@(($t0 + ($n + 1) * $step), 0))
                            , $o.ToArray()
                        }
                        function Shards([int]$n, [int]$d, [double]$r0) {
                            for ($i = 0; $i -lt $n; $i++) {
                                $p = New-Object Windows.Shapes.Rectangle
                                $p.Width = 3 + $rnd.Next(7); $p.Height = 3 + $rnd.Next(10)
                                if ($i % 3 -eq 0) { $p.Fill = Br '#FFFFFF' } elseif ($i % 3 -eq 1) { $p.Fill = Br $acc } else { $p.Fill = Br '#9CA3AF' }
                                $p.Opacity = 0
                                Put $fx $p -3 -3
                                $k = Tf $p
                                $an = $rnd.NextDouble() * 6.2832; $dist = $r0 + $rnd.Next(160)
                                Go $k.T $TX 0 ([Math]::Cos($an) * $dist) 900 $d $qe
                                Go $k.T $TY 0 ([Math]::Sin($an) * $dist + 30) 900 $d $qe
                                Go $k.R $RA 0 ($rnd.Next(-540, 540)) 900 $d $null
                                Go $p $op 1 0 900 $d $qi
                            }
                        }
                        function Flash([int]$d) {
                            $f = New-Object Windows.Shapes.Ellipse; $f.Width = 80; $f.Height = 80; $f.Opacity = 0
                            $c = Col $acc
                            $rg = New-Object Windows.Media.RadialGradientBrush
                            [void]$rg.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.Colors]::White), 0))
                            [void]$rg.GradientStops.Add((New-Object Windows.Media.GradientStop $c, 0.45))
                            [void]$rg.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(0, $c.R, $c.G, $c.B)), 1))
                            $f.Fill = $rg
                            Put $fx $f -40 -40
                            $k = Tf $f
                            Go $k.S $sx 0.2 4.5 650 $d $qe; Go $k.S $sy 0.2 4.5 650 $d $qe
                            Go $f $op 0.95 0 650 $d $qi
                        }
                        function Rays([int]$d) {
                            $rc = New-Object Windows.Controls.Canvas; Put $fx $rc 0 0
                            $c = Col $acc
                            for ($i = 0; $i -lt 18; $i++) {
                                $ry = New-Object Windows.Shapes.Rectangle; $ry.Width = 3; $ry.Height = 200
                                $lg = New-Object Windows.Media.LinearGradientBrush
                                $lg.StartPoint = New-Object Windows.Point 0.5, 0; $lg.EndPoint = New-Object Windows.Point 0.5, 1
                                [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(0, $c.R, $c.G, $c.B)), 0))
                                [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(170, $c.R, $c.G, $c.B)), 1))
                                $ry.Fill = $lg
                                $ry.RenderTransformOrigin = New-Object Windows.Point 0.5, 1
                                $ry.RenderTransform = New-Object Windows.Media.RotateTransform ($i * 20)
                                Put $rc $ry -1.5 -200
                            }
                            $rk = Tf $rc
                            Keys $rc $op @(@(0, 0), @($d, 0), @(($d + 260), 0.6), @(($d + 1800), 0.2))
                            $an = & $mk 0 360 18000 $d $null; $an.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
                            $rk.R.BeginAnimation($RA, $an)
                        }
                        function Wave([int]$d, [string]$col, [double]$to) {
                            $r = New-Object Windows.Shapes.Ellipse; $r.Width = 100; $r.Height = 100; $r.Stroke = Br $col; $r.StrokeThickness = 3; $r.Opacity = 0
                            Put $fx $r -50 -50; $k = Tf $r
                            Go $k.S $sx 0.3 $to 950 $d $qe; Go $k.S $sy 0.3 $to 950 $d $qe
                            Keys $r $op @(@(0, 0), @($d, 0), @(($d + 60), 0.9), @(($d + 950), 0))
                        }
                        function Glow($el, [string]$col, [double]$r) {
                            $el.Effect = New-Object Windows.Media.Effects.DropShadowEffect -Property @{ BlurRadius = $r; ShadowDepth = 0; Color = (Col $col); Opacity = 0.95 }
                        }
                        $bt = 3000; $gen = $false
                        $title = 'Доступ открыт!'
                        # ===== сборка 15: 12 авторских сюжетов (+ «Классика»). Все анимации конечные, мало эффектов тени — чтобы не лагало
                        $gen = $true
                        $RED = '#EF4444'
                        $sin2 = New-Object Windows.Media.Animation.SineEase; $sin2.EasingMode = 'EaseInOut'
                        $cbi = New-Object Windows.Media.Animation.CubicEase; $cbi.EasingMode = 'EaseIn'
                        $DashP = [Windows.Shapes.Shape]::StrokeDashOffsetProperty
                        function NCv($par) { $cv = New-Object Windows.Controls.Canvas; Put $par $cv 0 0; $cv }
                        function SetB($el, $v, [string]$what) { if ($null -eq $v) { return }; $bb = $v; if ($v -is [string]) { $bb = Br $v }; if ($what -eq 'f') { $el.Fill = $bb } else { $el.Stroke = $bb } }
                        function NRect($par, [double]$x, [double]$y, [double]$w0, [double]$h0, $fill, [double]$rad) {
