                            $r = New-Object Windows.Shapes.Ellipse; $r.Width = $d; $r.Height = $d; SetB $r $fill 'f'; Put $par $r ($cx - $d / 2) ($cy - $d / 2); $r
                        }
                        function NPath($par, [string]$data, $fill, $stroke, [double]$th) {
                            $p = New-Object Windows.Shapes.Path; $p.Data = [Windows.Media.Geometry]::Parse($data)
                            SetB $p $fill 'f'; SetB $p $stroke 's'; $p.StrokeThickness = $th
