                        }
                        function LGB([string]$a, [string]$z, [double]$ang) { New-Object Windows.Media.LinearGradientBrush (Col $a), (Col $z), $ang }
                        function ArgbC([string]$h, [double]$al) { $q0 = Col $h; [Windows.Media.Color]::FromArgb([byte][Math]::Round(255 * $al), $q0.R, $q0.G, $q0.B) }
