                            [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop (ArgbC $h 0), 0))
                            [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop (ArgbC $h $al), 0.5))
