                        function RotC($el, [double]$cx, [double]$cy) { $rt = New-Object Windows.Media.RotateTransform; $rt.CenterX = $cx; $rt.CenterY = $cy; $el.RenderTransform = $rt; $rt }
                        function Dash($sh, [double]$units) { $dc = New-Object Windows.Media.DoubleCollection; [void]$dc.Add($units); [void]$dc.Add($units); $sh.StrokeDashArray = $dc; $sh.StrokeDashOffset = $units }
                        function Spray($par, [double]$x, [double]$y, [int]$n, [int]$d, [string]$col, [double]$dist) {
                            for ($si = 0; $si -lt $n; $si++) {
                                $sp = New-Object Windows.Shapes.Rectangle; $sp.Width = 2 + $rnd.Next(4); $sp.Height = 2 + $rnd.Next(5)
                                if ($si % 3 -eq 0) { $sp.Fill = Br '#FFFFFF' } else { $sp.Fill = Br $col }
                                $sp.Opacity = 0; Put $par $sp $x $y; $sk0 = Tf $sp
                                $an = $rnd.NextDouble() * 6.2832; $ds = $dist * (0.35 + 0.65 * $rnd.NextDouble())
                                Go $sk0.T $TX 0 ([Math]::Cos($an) * $ds) 700 $d $qe; Go $sk0.T $TY 0 ([Math]::Sin($an) * $ds + 24) 700 $d $qe
                                Go $sk0.R $RA 0 ($rnd.Next(-360, 360)) 700 $d $qe
