                            $R = NCv $fx; FadeOut $R ($bt + 60)
                            $nodes = @(@(140, -64, '#FF0033', 'YT'), @(152, 0, '#5865F2', 'DC'), @(140, 64, '#2AABEE', 'TG'))
                            $wires = @()
                            foreach ($nd in $nodes) { [void](NLine $R -142 0 $nd[0] $nd[1] '#2A3142' 2); $lw = NLine $R -142 0 $nd[0] $nd[1] $acc 2; $lw.Opacity = 0; $wires += $lw }
                            $G = NCv $R; $gr = RotC $G 0 96
                            $gb = NRect $G -7 -96 14 192 (LGB '#F87171' '#991B1B' 0) 4; Glow $gb $RED 12
                            [void](NTxt $G 'РКН' 12 $RED 0 -110 60)
                            Keys $G $op @(@(0, 0), @(200, 1), @(1200, 1), @(1250, 0.3), @(1300, 1), @(1360, 0.3), @(1420, 1), @(2300, 1), @(2650, 0))
                            Keys $gr $RA @(@(0, 0), @(2250, 0), @(2600, 80))
                            $pcn = NCv $R; $pck = Tf $pcn; $pck.T.X = -160
                            $pcb = NRect $pcn -26 -20 52 38 (LGB '#374151' '#111827' 90) 6; $pcb.Stroke = Br '#6B7280'; $pcb.StrokeThickness = 1.5
                            [void](NRect $pcn -20 -14 40 24 (LGB $acc '#1E3A8A' 45) 3); [void](NRect $pcn -12 19 24 4 '#6B7280' 2)
                            [void](NTxt $pcn 'ВЫ' 11 '#FFFFFF' 0 -2 40)
                            $ndk = @()
                            for ($j = 0; $j -lt 3; $j++) {
                                $nd = $nodes[$j]; $nc = NCv $R; $nk = Tf $nc; $nk.T.X = $nd[0]; $nk.T.Y = $nd[1]
                                $hal = NEl $nc 0 0 64 (RadB $nd[2] 0.9); $hal.Opacity = 0
                                $nb = NEl $nc 0 0 40 '#1A1F2B'; $nb.Stroke = Br $nd[2]; $nb.StrokeThickness = 2
                                [void](NTxt $nc $nd[3] 12 $nd[2] 0 0 40)
                                $okm = NEl $nc 16 -16 14 '#22C55E'; $okm.Opacity = 0; [void](NPath $nc 'M 11,-16 L 15,-12 L 21,-20' $null '#FFFFFF' 2)
                                $ndk += @{ C = $nc; K = $nk; H = $hal; M = $okm }
                                $okm2 = $nc.Children[$nc.Children.Count - 1]; $okm2.Opacity = 0
                                $ndk[$j].M2 = $okm2
                            }
                            function Pkt([double]$x1, [double]$y1, [double]$x2, [double]$y2, [int]$t0, [int]$du, [string]$col) {
                                $dt0 = NEl $R 0 0 9 $col; $dt0.Opacity = 0; $dk1 = New-Object Windows.Media.TranslateTransform; $dt0.RenderTransform = $dk1
                                Keys $dk1 $TX @(@(0, $x1), @($t0, $x1), @(($t0 + $du), $x2)); Keys $dk1 $TY @(@(0, $y1), @($t0, $y1), @(($t0 + $du), $y2))
                                Keys $dt0 $op @(@(0, 0), @($t0, 0), @(($t0 + 40), 1), @(($t0 + $du), 1), @(($t0 + $du + 90), 0))
                            }
                            for ($j = 0; $j -lt 3; $j++) {
                                $nd = $nodes[$j]; $fr0 = 142.0 / ($nd[0] + 142); $gy = $nd[1] * $fr0
                                foreach ($t0 in @((150 + $j * 140), (650 + $j * 140))) { Pkt -142 0 0 $gy $t0 380 $RED; Spray $R 0 $gy 5 ($t0 + 380) $RED 34 }
                                $t1 = 1500 + $j * 260; Pkt -142 0 $nd[0] $nd[1] $t1 640 $acc; Pkt -142 0 $nd[0] $nd[1] ($t1 + 120) 640 '#FFFFFF'
                                $ta = $t1 + 640; $q0 = $ndk[$j]
                                Keys $q0.H $op @(@(0, 0), @($ta, 0), @(($ta + 120), 1), @(($ta + 600), 0.55))
                                Pop $q0.K $ta 1.25
                                Keys $q0.M $op @(@(0, 0), @(($ta + 100), 0), @(($ta + 200), 1)); Keys $q0.M2 $op @(@(0, 0), @(($ta + 100), 0), @(($ta + 200), 1))
                                Keys $wires[$j] $op @(@(0, 0), @($t1, 0), @($ta, 0.9))
                            }
                            Fin $bt '#FFFFFF'
                            $title = 'Все сервисы на связи!'
                            $sync.Stages = @('Ищем серверы…', 'РКН на пути…', 'Маскируем пакеты…', 'YouTube на связи…', 'Discord и Telegram тоже', 'Всё работает')
                        } else {
                            # ===== 12. РАССВЕТ (sunrise): ночь блокировок, тучи РКН расходятся, солнце поднимается и становится логотипом
                            $R = NCv $fx; FadeOut $R ($bt + 150)
                            $sky = NCv $R; $sky.Clip = [Windows.Media.RectangleGeometry]::new([Windows.Rect]::new(-320, -230, 640, 272))
                            $tint = NRect $sky -320 -230 640 272 (LGB '#00000000' '#00000000' 90) 0
                            $tg0 = New-Object Windows.Media.LinearGradientBrush; $tg0.StartPoint = New-Object Windows.Point 0.5, 0; $tg0.EndPoint = New-Object Windows.Point 0.5, 1
                            [void]$tg0.GradientStops.Add((New-Object Windows.Media.GradientStop (ArgbC $acc 0), 0.3)); [void]$tg0.GradientStops.Add((New-Object Windows.Media.GradientStop (ArgbC $acc 0.35), 1))
                            $tint.Fill = $tg0; $tint.Opacity = 0; Keys $tint $op @(@(0, 0), @(1000, 0), @(2800, 1))
                            for ($i = 0; $i -lt 26; $i++) {
                                $st = NEl $sky ($rnd.Next(-280, 280)) ($rnd.Next(-170, 20)) (1.5 + 2 * $rnd.NextDouble()) '#FFFFFF'; $t0 = $rnd.Next(800)
                                Keys $st $op @(@(0, 0), @($t0, 0.9), @(($t0 + 300), 0.3), @(($t0 + 600), 0.9), @((1400 + $rnd.Next(600)), 0.6), @((2300 + $rnd.Next(300)), 0))
                            }
                            $sun = NCv $sky; $suk = Tf $sun
                            [void](NEl $sun 0 0 230 (RadB $acc 0.75))
                            $sg = New-Object Windows.Media.RadialGradientBrush
                            [void]$sg.GradientStops.Add((New-Object Windows.Media.GradientStop (ArgbC '#FFFFFF' 1), 0)); [void]$sg.GradientStops.Add((New-Object Windows.Media.GradientStop (ArgbC '#FFE9A8' 1), 0.45)); [void]$sg.GradientStops.Add((New-Object Windows.Media.GradientStop (ArgbC $acc 1), 1))
                            [void](NEl $sun 0 0 84 $sg)
                            Go $suk.T $TY 150 0 2300 400 $sin2
                            function Cloud([double]$cx, [double]$cy) {
                                $cl = NCv $sky; $clk = Tf $cl; $clk.T.X = $cx; $clk.T.Y = $cy
                                foreach ($pp in @(@(-38, 6, 44), @(-12, -8, 56), @(18, -2, 50), @(42, 8, 38), @(0, 12, 70))) { [void](NEl $cl $pp[0] $pp[1] $pp[2] (LGB '#3A3F4F' '#1E2230' 90)) }
                                @{ C = $cl; K = $clk }
                            }
                            $c1 = Cloud -36 -18; $c2 = Cloud 40 6; $c3 = Cloud -10 30
                            [void](NTxt $c1.C 'РКН' 14 '#B91C1C' -12 -2 60)
                            Go $c1.K.T $TX -36 -260 1100 1700 $sin2; Go $c2.K.T $TX 40 270 1100 1650 $sin2; Go $c3.K.T $TX -10 -240 1100 1900 $sin2
                            foreach ($cc in @($c1, $c2, $c3)) { Keys $cc.C $op @(@(0, 1), @(2200, 1), @(2700, 0)) }
                            $hz = NRect $R -300 41 600 2 (HGB $acc 1) 1; Glow $hz $acc 10
                            for ($i = 0; $i -lt 6; $i++) {
                                $wl = NRect $R (-(90 - $i * 12)) (50 + $i * 7) ((90 - $i * 12) * 2) 2 (HGB $acc 0.8) 1; $wl.Opacity = 0; $wlk = Tf $wl
                                Keys $wl $op @(@(0, 0), @((1700 + $i * 80), 0), @((2500 + $i * 80), (0.85 - $i * 0.1)))
                                Keys $wlk.T $TX @(@(0, 0), @(2000, 0), @(2300, 4), @(2600, -4), @(2900, 3), @(($bt + 100), 0))
                            }
                            Fin $bt '#FFE9A8'; Rays ($bt + 60)
                            $title = 'Новый день без блокировок!'
                            $sync.Stages = @('Ночь блокировок…', 'Небо светлеет…', 'Тучи РКН расходятся…', 'Рассвет…', 'Новый день!', 'Доброе утро, интернет')
                        }
                        if (-not $gen) {
                            Rays ($bt + 60)
                            Shards 30 $bt 80
                            Flash $bt
                        }
                        $lg0 = $w.FindName('SpLogo'); $lg0.BeginAnimation($op, $null); $lg0.Opacity = 0
                        $lg0.BeginAnimation($op, (& $mk 0 1 500 ($bt + 140) $e))
                        $ls.BeginAnimation($sx, (& $mk 0.15 1 900 ($bt + 140) $b)); $ls.BeginAnimation($sy, (& $mk 0.15 1 900 ($bt + 140) $b))
                        $rgs = $w.FindName('SpRings'); $rgs.BeginAnimation($op, $null); $rgs.Opacity = 0; $rgs.BeginAnimation($op, (& $mk 0 1 700 ($bt + 260) $e))
                        $ttl = $w.FindName('SpTitle'); $ttl.Text = $title; $ttl.BeginAnimation($op, $null); $ttl.Opacity = 0
                        $ttl.BeginAnimation($op, (& $mk 0 1 650 ($bt + 380) $e))
                        $w.FindName('SpTitleMove').BeginAnimation([Windows.Media.TranslateTransform]::YProperty, (& $mk 16 0 700 ($bt + 380) $e))
                        $sb0 = $w.FindName('SpSub'); $sb0.BeginAnimation($op, $null); $sb0.Opacity = 0
                        $sb0.BeginAnimation($op, (& $mk 0 1 650 ($bt + 750) $e))
                    }
                } catch {
                    try {
                        $w.FindName('SpFx').Children.Clear()
                        $rgs = $w.FindName('SpRings'); $rgs.BeginAnimation($op, $null); $rgs.Opacity = 1
                        $w.FindName('SpLogo').BeginAnimation($op, (& $mk 0 1 500 150 $e))
                        $ls.BeginAnimation($sx, (& $mk 0.5 1 750 150 $b)); $ls.BeginAnimation($sy, (& $mk 0.5 1 750 150 $b))
                        $w.FindName('SpTitle').Text = 'Нет блокировкам в интернете!'
                        $w.FindName('SpTitle').BeginAnimation($op, (& $mk 0 1 600 450 $e))
                        $w.FindName('SpSub').BeginAnimation($op, (& $mk 0 1 600 900 $e))
                    } catch { }
                }
                $sync.SW = [Diagnostics.Stopwatch]::StartNew()
                $sync.Total = $total
                $tm = New-Object Windows.Threading.DispatcherTimer
                $tm.Interval = [TimeSpan]::FromMilliseconds(40)
                $sync.Tm = $tm
                $tm.Add_Tick({
                    try {
                        $ms = $sync.SW.ElapsedMilliseconds
                        $p = [Math]::Min(100, [int]($ms * 100 / [Math]::Max(1, $sync.Total - 250)))
                        $sync.W.FindName('SpPct').Text = ('{0}%' -f $p)
                        $i = [Math]::Min($sync.Stages.Count - 1, [int][Math]::Floor($p / 20))
                        $st = $sync.W.FindName('SpStage'); if ($st.Text -ne $sync.Stages[$i]) { $st.Text = $sync.Stages[$i] }
                        if ($sync.Auto -and $ms -gt ($sync.Total + 400)) { $sync.Close = $true }
                        if (($sync.Close -or $ms -gt 45000) -and -not $sync.Closing) {
                            $sync.Closing = $true
                            $f = & $sync.Mk 1 0 380 0 $sync.Ease
                            $f.Add_Completed({ try { $sync.Tm.Stop(); $sync.W.Close() } catch { }; [Windows.Threading.Dispatcher]::CurrentDispatcher.InvokeShutdown() })
                            $cs2 = $sync.W.FindName('SpCardScale')
                            $cs2.BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, (& $sync.Mk 1 1.04 380 0 $sync.Ease))
                            $cs2.BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, (& $sync.Mk 1 1.04 380 0 $sync.Ease))
                            $sync.W.BeginAnimation([Windows.UIElement]::OpacityProperty, $f)
                        }
                    } catch { }
                })
                $tm.Start()
                $w.Add_MouseLeftButtonDown({ $sync.Skip = $true; $sync.Close = $true })
                $w.Show(); $sync.Shown = $true
                [Windows.Threading.Dispatcher]::Run()
            } catch { $sync.Failed = $true; $sync.Err = $_.Exception.Message }
}
# ---------------------------------------------------------------- заставка 2.0: одна анимация — ZS разъезжаются
# Всё движение делает WPF-сториборд: PowerShell в кадрах не участвует, поэтому плавно и почти без нагрузки.
# ---------------------------------------------------------------- заставка 2.0 (главный поток)
# Раньше она жила в отдельном runspace — и из-за этого терялись клики. Теперь всё на одном потоке.
$script:Sp = @{
    Win = $null; Timer = $null; T0 = (Get-Date); Close = $false; Done = $false
    Choice = ''; Stage = ''; Progress = 0.0; Ok = $false; Fail = $false; Err = ''
    AskShown = $false; InstShown = $false; FailShown = $false; DoneShown = $false; DoneAt = $null
    NeedZapret = $false
}

function Splash-Show($el) {
    if (-not $el) { return }
    $el.Visibility = 'Visible'
    $a = New-Object Windows.Media.Animation.DoubleAnimation 0, 1, ([TimeSpan]::FromMilliseconds(240))
    $e = New-Object Windows.Media.Animation.CubicEase; $e.EasingMode = 'EaseOut'
    $a.EasingFunction = $e
    $el.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
}
function Splash-Hide($el) {
    if (-not $el) { return }
    $el.Visibility = 'Collapsed'
    $el.Opacity = 0
}

function Test-ZapretPresent {
    try {
        $bin = Test-Path -LiteralPath (Join-Path $script:AppDir 'bin\winws.exe')
        $bats = @(Get-ChildItem -LiteralPath $script:AppDir -Filter 'general*.bat' -File -ErrorAction SilentlyContinue)
        return ($bin -and $bats.Count -gt 0)
    } catch { return $false }
}

function Show-NoZapretState {
    # ни одной стратегии и нет движка: показываем это честно, кнопки запуска гасим
    try {
        if ($script:Running) {
            $StatusText.Text = 'Обход запущен другой копией'; $StatusText.Foreground = $Win.Resources['WarnBrush']
            $StrategyText.Text = 'winws.exe работает не из этой папки — управлять им отсюда нельзя'
        } else {
            $StatusText.Text = 'Нет zapret'; $StatusText.Foreground = $Win.Resources['WarnBrush']
            $StrategyText.Text = 'Добавьте движок: перезапустите программу и нажмите «Найти zapret»'
        }
        $BtnToggle.Content = 'Запустить'
        $BtnToggle.SetResourceReference([Windows.Controls.Button]::BackgroundProperty, 'AccentBrush')
        $OrbCore.Fill = $script:OrbOff; $OrbGlyph.Foreground = $Win.Resources['SubBrush']; Set-Pulse $false; $OrbCore.Effect = $null
        $BtnToggle.IsEnabled = $false; $BtnToggle.Opacity = 0.35
        $tip = 'Сначала добавьте zapret: перезапустите программу и нажмите «Найти zapret»'
        $BtnToggle.ToolTip = $tip
        foreach ($b in @($BtnRestart, $BtnAuto, $BtnPing, $BtnBoost, $BtnCheckNow, $BtnRescan, $BtnSetPing)) {
            if ($b) { $b.IsEnabled = $false; $b.Opacity = 0.35; $b.ToolTip = $tip }
        }
        try { $CountText.Text = '0 стратегий — нужен zapret' } catch { }
    } catch { }
}

function Set-NoZapretMode {
    $script:NoZapret = $true
    try { Log 'zapret не найден: стратегии недоступны, пока не добавите движок' 'warn' } catch { }
    Show-NoZapretState
}

function Complete-Splash {
    $s = $script:Sp
    if ($s.Done) { return }
    $s.Done = $true
    try { if ($s.Timer) { $s.Timer.Stop() } } catch { }
    try { if ($s.Win) { $s.Win.Close() } } catch { }
    $script:Splash = $null
    if (-not (Test-ZapretPresent)) { try { Set-NoZapretMode } catch { } }
    try {
        if ($Cfg.Perf) { $Win.Opacity = 1 }
        else {
            $fa = New-Object Windows.Media.Animation.DoubleAnimation 0, 1, ([TimeSpan]::FromMilliseconds(240))
            $fe = New-Object Windows.Media.Animation.CubicEase; $fe.EasingMode = 'EaseOut'
            $fa.EasingFunction = $fe
            $Win.BeginAnimation([Windows.UIElement]::OpacityProperty, $fa)
        }
    } catch { try { $Win.Opacity = 1 } catch { } }
    if ($Cfg.Onboarded -and $Cfg.LicenseAccepted) {
        if ([int]$Cfg.WhatSeen -lt 17) { try { Show-WhatNew } catch { } }
    }
}

function Splash-Tick {
    $s = $script:Sp; $w = $s.Win
    if (-not $w) { return }
    if ($s.Close) { Complete-Splash; return }
    $el = ((Get-Date) - $s.T0).TotalMilliseconds
    if (-not $s.AskShown -and $el -ge 3500) {
        $s.AskShown = $true
        Splash-Hide $w.FindName('Intro'); Splash-Hide $w.FindName('Track'); Splash-Hide $w.FindName('Prog')
        if ($s.NeedZapret) { Splash-Show $w.FindName('Ask') } else { $s.Close = $true }
        return
    }
    if ($s.InstShown) {
        if ($s.Stage) { try { $w.FindName('InstStage').Text = [string]$s.Stage } catch { } }
        $p = [double]$s.Progress
        if ($p -lt 0) { $p = 0 }; if ($p -gt 1) { $p = 1 }
        try { $w.FindName('InstFillScale').ScaleX = $p; $w.FindName('InstPct').Text = ('{0}%' -f [int]($p * 100)) } catch { }
        if ($s.Fail -and -not $s.FailShown) {
            $s.FailShown = $true
            try {
                $et = $w.FindName('InstErr')
                $et.Text = 'Не удалось: ' + [string]$s.Err
                $et.Visibility = 'Visible'
                $w.FindName('FailRow').Visibility = 'Visible'
            } catch { }
        }
    }
    if ($s.Ok -and -not $s.DoneShown) {
        $s.DoneShown = $true
        $s.DoneAt = Get-Date
        Splash-Hide $w.FindName('Ask'); Splash-Hide $w.FindName('Inst')
        Splash-Show $w.FindName('Done')
        try {
            $sc = $w.FindName('DoneScale'); $sc.ScaleX = 0.4; $sc.ScaleY = 0.4
            $pop = New-Object Windows.Media.Animation.DoubleAnimation 0.4, 1, ([TimeSpan]::FromMilliseconds(520))
            $be = New-Object Windows.Media.Animation.BackEase; $be.EasingMode = 'EaseOut'; $be.Amplitude = 0.55
            $pop.EasingFunction = $be
            $sc.BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, $pop)
            $sc.BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, $pop)
            $dash = New-Object Windows.Media.Animation.DoubleAnimation 1, 0, ([TimeSpan]::FromMilliseconds(420))
            $dash.BeginTime = [TimeSpan]::FromMilliseconds(180)
            $w.FindName('DoneCheck').BeginAnimation([Windows.Shapes.Shape]::StrokeDashOffsetProperty, $dash)
            $ra = New-Object Windows.Media.Animation.DoubleAnimation 0.0, 0.55, ([TimeSpan]::FromMilliseconds(700))
            $ra.AutoReverse = $true
            $ra.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
            $w.FindName('DoneRing').BeginAnimation([Windows.UIElement]::OpacityProperty, $ra)
        } catch { }
    }
    if ($s.DoneShown -and $s.DoneAt -and ((Get-Date) - $s.DoneAt).TotalMilliseconds -ge 2000) { $s.Close = $true }
}

