        $x = $x.Replace('__ACC__', $acc).Replace('__FG__', $fg)
        $w = [Windows.Markup.XamlReader]::Parse($x)
        try {
            $wc = New-Object System.Windows.Shell.WindowChrome
            $wc.CornerRadius = New-Object System.Windows.CornerRadius 30
            $wc.GlassFrameThickness = New-Object System.Windows.Thickness 0
            $wc.CaptionHeight = 0
            $wc.ResizeBorderThickness = New-Object System.Windows.Thickness 0
            $wc.UseAeroCaptionButtons = $false
            [System.Windows.Shell.WindowChrome]::SetWindowChrome($w, $wc)
        } catch { }

        $s = $script:Sp
        $s.Win = $w; $s.T0 = (Get-Date); $s.NeedZapret = (-not (Test-ZapretPresent))

        $w.FindName('BtnNo').Add_Click({ $script:Sp.Choice = 'no'; $script:Sp.Close = $true })
        $w.FindName('BtnSkip').Add_Click({ $script:Sp.Close = $true })
        $w.FindName('BtnX').Add_Click({ $script:Sp.Close = $true })
        $w.FindName('BtnMin').Add_Click({ try { $script:Sp.Win.WindowState = 'Minimized' } catch { } })
        $w.FindName('LnkDl').Add_MouseLeftButtonUp({ try { Start-Process 'https://github.com/Flowseal/zapret-discord-youtube/releases/latest' } catch { } })

        $pick = {
            $sp = $script:Sp
            $sp.Fail = $false; $sp.FailShown = $false
            Splash-Hide $sp.Win.FindName('Ask')
            Splash-Show $sp.Win.FindName('Inst')
            $sp.InstShown = $true
            $sp.Stage = 'Выберите папку с zapret…'; $sp.Progress = 0.1
            $picked = ''
            try {
                $w2 = $script:Sp.Win
                $w2.Topmost = $false
                $shell = New-Object -ComObject Shell.Application
                $fd = $shell.BrowseForFolder(0, 'Выберите папку с zapret (где лежат bin и general*.bat)', 0)
                if ($fd) { $picked = [string]$fd.Self.Path }
                $w2.Topmost = $true
                try { [void]$w2.Activate() } catch { }
            } catch { }
            if ($picked) { Install-ZapretFromFolder $picked $sp }
            else { $sp.Fail = $true; $sp.Err = 'папка не выбрана'; $sp.FailShown = $false; $sp.Stage = 'Не удалось установить' }
        }
        $w.FindName('BtnYes').Add_Click($pick)
        $w.FindName('BtnPick').Add_Click($pick)

        $tm = New-Object Windows.Threading.DispatcherTimer
        $tm.Interval = [TimeSpan]::FromMilliseconds(50)
        $tm.Add_Tick({ Splash-Tick })
        $s.Timer = $tm
        $w.Show()
        $tm.Start()
        $w
    } catch { return $null }
}

function Start-SplashWin([string]$acc, [string]$fnt, [string]$variant, [int]$ms, [switch]$Auto) {
    if ($acc -notmatch '^#[0-9A-Fa-f]{6}$') { $acc = '#7C5CFF' }
    # сборка 15: 12 сюжетов + классика. Выбран конкретный — показываем его, «Случайно» — случайный без повтора подряд
    $lastV = ''; $lastF = $null
    try { $lastF = Join-Path $env:LOCALAPPDATA 'ZapretStudio\last.intro'; if (Test-Path -LiteralPath $lastF) { $lastV = ([string](Get-Content -LiteralPath $lastF -Raw -ErrorAction Stop)).Trim() } } catch { }
    if (-not (@($script:IntroList) -contains $variant)) { $variant = @($script:IntroList | Where-Object { $_ -ne $lastV }) | Get-Random }
    try { if ($lastF) { $null = New-Item -ItemType Directory -Force -Path (Split-Path $lastF) -ErrorAction Stop; Set-Content -LiteralPath $lastF -Value $variant -Encoding ASCII -ErrorAction Stop } } catch { }
    $sync = [hashtable]::Synchronized(@{ Close = $false; Closing = $false; Failed = $false; Shown = $false; Acc = $acc; Font = $fnt; Logo = $script:LogoB64; Slogan = (Get-Slogan); Ms = $ms; Err = ''; Variant = $variant; Skip = $false; Auto = [bool]$Auto })
    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = 'STA'; $rs.ThreadOptions = 'ReuseThread'; $rs.Open()
    $rs.SessionStateProxy.SetVariable('sync', $sync)
    $ps = [powershell]::Create(); $ps.Runspace = $rs
    [void]$ps.AddScript($script:SpCode.ToString())
    $sync.Handle = $ps.BeginInvoke(); $sync.PS = $ps
    $sync
}
$script:Splash = $null
$script:SplashT0 = Get-Date
$script:SplashMs = 6500
try {
    $acc = '#7C5CFF'; $fnt = ''; $spOn = $true; $intro = 'random'
    try {
        $sp0 = $script:SettingsPath
        if (-not (Test-CfgFile $sp0)) { $sp0 = $script:SettingsPath + '.bak' }
        if (Test-Path -LiteralPath $sp0) {
            $j = Get-Content -LiteralPath $sp0 -Raw -Encoding UTF8 | ConvertFrom-Json
            if ([string]$j.Accent -match '^#[0-9A-Fa-f]{6}$') { $acc = [string]$j.Accent }
            if ($j.Font) { $fnt = [string]$j.Font }
            if ($j.Intro) { $intro = [string]$j.Intro }
            if ($j.PSObject.Properties['Splash'] -and $j.Splash -eq $false) { $spOn = $false }
        }
    } catch { }
    if ($spOn) { $script:SplashAcc = $acc }
} catch { $script:Splash = $null }

Add-Type -ReferencedAssemblies System.Net.Http -TypeDefinition @'
using System;
using System.IO;
using System.Diagnostics;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
public static class ZProbe {
    // время до ответа сервера (заголовки), мс; ошибки и таймаут пробрасываются как у обычного GetAsync
    public static async Task<long> Timed(HttpClient c, string url) {
        Stopwatch sw = Stopwatch.StartNew();
        using (HttpResponseMessage r = await c.GetAsync(url, HttpCompletionOption.ResponseHeadersRead).ConfigureAwait(false)) { }
        sw.Stop();
        return sw.ElapsedMilliseconds;
    }
    // честный пинг: первый HEAD открывает соединение (DNS+TCP+TLS), дальше лучший из трёх на уже открытом; {открытие, пинг}
    public static async Task<long[]> Warm(HttpClient c, string url) {
        Stopwatch sw = Stopwatch.StartNew();
        using (HttpRequestMessage q = new HttpRequestMessage(HttpMethod.Head, url))
        using (HttpResponseMessage r = await c.SendAsync(q).ConfigureAwait(false)) { }
        long first = sw.ElapsedMilliseconds;
        long best = long.MaxValue;
        for (int i = 0; i < 3; i++) {
            sw.Restart();
            try {
                using (HttpRequestMessage q2 = new HttpRequestMessage(HttpMethod.Head, url))
                using (HttpResponseMessage r2 = await c.SendAsync(q2).ConfigureAwait(false)) { }
                long x = sw.ElapsedMilliseconds; if (x < best) best = x;
            } catch (Exception) { }
        }
        if (best == long.MaxValue) best = first;
        return new long[] { first, best };
    }
    // скачивает до maxBytes байт, но не дольше maxMs; возвращает {байт, мс на скачивание, мс до первого ответа}
    // живой пинг: HEAD на уже открытом соединении, без тела ответа; twice - сначала прогревочный HEAD; {прогрев, пинг}
    public static async Task<double[]> Live(HttpClient c, string url, bool twice) {
        Stopwatch sw = Stopwatch.StartNew();
        if (twice) {
            using (HttpRequestMessage q0 = new HttpRequestMessage(HttpMethod.Head, url))
            using (HttpResponseMessage r0 = await c.SendAsync(q0).ConfigureAwait(false)) { }
        }
        long first = sw.ElapsedMilliseconds;
        sw.Restart();
        using (HttpRequestMessage q = new HttpRequestMessage(HttpMethod.Head, url))
        using (HttpResponseMessage r = await c.SendAsync(q).ConfigureAwait(false)) { }
        return new double[] { first, sw.ElapsedMilliseconds };
    }
    // сборка 13: настоящий пинг (ICMP, лучший из 3); если сервер не отвечает на ICMP - HEAD на открытом соединении; {1 = ICMP / 0 = HTTP, мс}
    public static async Task<double[]> RealPing(HttpClient c, string url, bool twice) {
        string hostName = new Uri(url).Host;
        long best = long.MaxValue;
        using (System.Net.NetworkInformation.Ping pg = new System.Net.NetworkInformation.Ping()) {
            for (int i = 0; i < 3; i++) {
                try {
                    System.Net.NetworkInformation.PingReply pr = await pg.SendPingAsync(hostName, 1200).ConfigureAwait(false);
                    if (pr.Status == System.Net.NetworkInformation.IPStatus.Success && pr.RoundtripTime < best) best = pr.RoundtripTime;
                } catch (Exception) { }
            }
        }
        if (best != long.MaxValue) return new double[] { 1, Math.Max(1, best) };
        double[] h = await Live(c, url, twice).ConfigureAwait(false);
        return new double[] { 0, h[1] };
    }
    // анти-душилка: читает до maxBytes не дольше maxMs; {байт, мс всего, мс до заголовков (-1 нет), 1 = дочитал или набрал maxBytes}
    public static async Task<double[]> Stall(HttpClient c, string url, long maxBytes, int maxMs) {
        Stopwatch sw = Stopwatch.StartNew();
        long total = 0; long ttfb = -1; int ended = 0;
        using (CancellationTokenSource cts = new CancellationTokenSource(maxMs)) {
            HttpResponseMessage r = null;
            try {
                r = await c.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cts.Token).ConfigureAwait(false);
                ttfb = sw.ElapsedMilliseconds;
                HttpResponseMessage rr = r;
                using (cts.Token.Register(() => { try { rr.Dispose(); } catch (Exception) { } })) {
                    using (Stream st = await r.Content.ReadAsStreamAsync().ConfigureAwait(false)) {
                        byte[] buf = new byte[16384];
                        while (true) {
                            int n = await st.ReadAsync(buf, 0, buf.Length, cts.Token).ConfigureAwait(false);
                            if (n <= 0) { ended = 1; break; }
                            total += n;
                            if (total >= maxBytes) { ended = 1; break; }
                        }
                    }
                }
            } catch (Exception) { }
            finally { if (r != null) { try { r.Dispose(); } catch (Exception) { } } }
        }
        return new double[] { total, sw.ElapsedMilliseconds, ttfb, ended };
    }
    public static async Task<double[]> Speed(HttpClient c, string url, long maxBytes, int maxMs) {
        Stopwatch sw = Stopwatch.StartNew();
        long total = 0; long ttfb = 0; long dl = 0;
        using (CancellationTokenSource cts = new CancellationTokenSource(maxMs)) {
            try {
                using (HttpResponseMessage r = await c.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cts.Token).ConfigureAwait(false)) {
                    ttfb = sw.ElapsedMilliseconds;
                    Stopwatch d = Stopwatch.StartNew();
                    using (Stream st = await r.Content.ReadAsStreamAsync().ConfigureAwait(false)) {
                        byte[] buf = new byte[65536];
                        int n;
                        while (true) {
                            n = await st.ReadAsync(buf, 0, buf.Length, cts.Token).ConfigureAwait(false);
                            if (n <= 0) break;
                            total += n;
                            dl = d.ElapsedMilliseconds;
                            if (total >= maxBytes) break;
                        }
                    }
                }
            } catch (OperationCanceledException) { }
        }
        return new double[] { total, dl, ttfb };
    }
}
