          <Style.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter Property="Foreground" Value="{DynamicResource AccentBrush}"/></Trigger></Style.Triggers>
        </Style>
      </TextBlock.Resources>
      <TextBlock.Style>
        <Style TargetType="TextBlock">
          <Setter Property="Opacity" Value="0.45"/>
          <Style.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter Property="Opacity" Value="0.95"/></Trigger></Style.Triggers>
        </Style>
      </TextBlock.Style>
      <Run Text="Возникли проблемы? Сообщите разработчику: "/><Hyperlink x:Name="FootDc" ToolTip="Открыть профиль dadramus в Discord">Discord @_a1ta1r_</Hyperlink><Run Text="  ·  "/><Hyperlink x:Name="FootGh" ToolTip="Сообщить об ошибке на GitHub (Issues)">GitHub</Hyperlink>
    </TextBlock>

    <Grid x:Name="TitleBar" Background="Transparent">
      <StackPanel Orientation="Horizontal" Margin="20,0,0,0" VerticalAlignment="Center">
        <Border x:Name="TitleLogoHost" Width="28" Height="28" CornerRadius="9" Background="{DynamicResource AccentBrush}">
          <TextBlock Text="Z" FontWeight="Black" FontSize="16" Foreground="{DynamicResource OnAccentBrush}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
        </Border>
        <TextBlock Text="Zapret Studio" FontWeight="Bold" FontSize="15" Margin="12,0,0,0" VerticalAlignment="Center"/>
        <Button x:Name="BtnAbout" Style="{StaticResource LinkBtn}" FontSize="12" Content="О создателях" Margin="10,1,0,0" VerticalAlignment="Center" ToolTip="Автор, авторские права и лицензия"/>
        <Button x:Name="BtnGit" Style="{StaticResource LinkBtn}" FontSize="12" Content="Мы на GitHub ↗" Margin="10,1,0,0" VerticalAlignment="Center" ToolTip="github.com/dadramus/ZapretStudio — исходники, обновления, идеи и баг-репорты"/>
        <Border x:Name="VerPill" CornerRadius="7" Background="#18FFFFFF" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" Padding="7,1" Margin="10,1,0,0" VerticalAlignment="Center" ToolTip="Zapret Studio 2.3"><TextBlock Text="v2.3" FontSize="11" FontWeight="SemiBold" Foreground="{DynamicResource SubBrush}"/></Border>
      </StackPanel>
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,0,12,0" VerticalAlignment="Center">
        <Button x:Name="BtnPin" Style="{StaticResource TitleBtn}" Content="&#xE718;" ToolTip="Поверх всех окон"/>
        <Button x:Name="BtnMin" Style="{StaticResource TitleBtn}" Content="&#xE921;" ToolTip="Свернуть"/>
        <Button x:Name="BtnClose" Style="{StaticResource TitleClose}" Content="&#xE8BB;" ToolTip="Закрыть"/>
      </StackPanel>
    </Grid>

    <Grid x:Name="MainArea" Grid.Row="1" Margin="20,0,20,20">
      <Grid.ColumnDefinitions><ColumnDefinition x:Name="ColLeft" Width="310"/><ColumnDefinition Width="18"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>

      <!-- LEFT: strategies -->
      <Grid>
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <DockPanel Margin="4,0,4,10">
          <TextBlock x:Name="CountText" DockPanel.Dock="Right" Foreground="{DynamicResource SubBrush}" VerticalAlignment="Center"/>
          <Button x:Name="BtnSort" DockPanel.Dock="Right" Style="{StaticResource Ghost}" Padding="9,3" FontSize="11" Margin="0,0,10,0" ToolTip="Порядок списка" Content="А–Я"/>
          <TextBlock Text="Стратегии" FontSize="17" FontWeight="Bold"/>
        </DockPanel>
        <Grid x:Name="SearchRow" Grid.Row="1" Margin="0,0,0,10">
          <TextBox x:Name="SearchBox" Style="{StaticResource Input}"/>
          <TextBlock x:Name="SearchHint" Text="Поиск стратегии…" Foreground="{DynamicResource SubBrush}" IsHitTestVisible="False" Margin="14,0,0,0" VerticalAlignment="Center"/>
        </Grid>
        <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
          <StackPanel x:Name="ListHost" Margin="0,0,6,0"/>
        </ScrollViewer>
        <StackPanel Grid.Row="3" Margin="0,10,0,0">
          <Button x:Name="BtnAuto" Style="{StaticResource Ghost}" Content="Подбор под мои задачи"/>
          <Grid x:Name="ProgTrack" Height="4" Margin="2,10,2,0" Visibility="Collapsed">
            <Border CornerRadius="2" Background="{DynamicResource TrackOffBrush}"/>
            <Border x:Name="ProgFill" CornerRadius="2" Background="{DynamicResource AccentBrush}" HorizontalAlignment="Left" Width="0"/>
          </Grid>
          <TextBlock x:Name="AutoText" FontSize="11" Foreground="{DynamicResource SubBrush}" Margin="4,6,4,0" TextWrapping="Wrap"/>
        </StackPanel>
      </Grid>

      <!-- RIGHT -->
      <Grid Grid.Column="2">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="16"/><RowDefinition Height="Auto"/><RowDefinition Height="10"/><RowDefinition Height="*"/></Grid.RowDefinitions>

        <Border Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="18" Padding="24">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition x:Name="ColOrb" Width="176"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Grid x:Name="OrbHost" Width="150" Height="150" HorizontalAlignment="Left">
              <Ellipse x:Name="RingPulse" Width="108" Height="108" Stroke="{DynamicResource AccentBrush}" StrokeThickness="2" Opacity="0" RenderTransformOrigin="0.5,0.5">
                <Ellipse.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Ellipse.RenderTransform>
              </Ellipse>
              <Ellipse x:Name="RingWave" Width="108" Height="108" Stroke="{DynamicResource AccentBrush}" StrokeThickness="3" Opacity="0" IsHitTestVisible="False" RenderTransformOrigin="0.5,0.5">
                <Ellipse.RenderTransform><ScaleTransform x:Name="WaveScale" ScaleX="1" ScaleY="1"/></Ellipse.RenderTransform>
              </Ellipse>
              <Ellipse x:Name="OrbCore" Width="108" Height="108" RenderTransformOrigin="0.5,0.5">
                <Ellipse.RenderTransform><ScaleTransform x:Name="OrbScale" ScaleX="1" ScaleY="1"/></Ellipse.RenderTransform>
              </Ellipse>
              <TextBlock x:Name="OrbGlyph" Text="&#xE7E8;" FontFamily="Segoe MDL2 Assets" FontSize="42" HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                <TextBlock.RenderTransform><ScaleTransform x:Name="GlyphScale" ScaleX="1" ScaleY="1"/></TextBlock.RenderTransform>
              </TextBlock>
            </Grid>
            <StackPanel Grid.Column="1" VerticalAlignment="Center">
              <TextBlock x:Name="StatusText" FontSize="27" FontWeight="Bold" Text="Обход выключен"/>
              <TextBlock x:Name="StrategyText" Margin="0,4,0,0" Foreground="{DynamicResource SubBrush}" TextTrimming="CharacterEllipsis">
                <TextBlock.RenderTransform><TranslateTransform x:Name="StratMove" X="0"/></TextBlock.RenderTransform>
              </TextBlock>
              <TextBlock x:Name="UptimeText" Margin="0,2,0,0" Foreground="{DynamicResource SubBrush}"/>
              <TextBlock x:Name="MonText" Margin="0,2,0,0" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap"/>
              <TextBlock x:Name="LiveText" Visibility="Collapsed" Margin="0,2,0,0" FontSize="11" FontWeight="SemiBold" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" ToolTip="Живой пинг: время ответа на уже открытом соединении, без скачивания. Интервал: Настройки → Связь и пинг"/>
              <TextBlock x:Name="SloganText" Margin="0,6,0,0" FontSize="12" FontStyle="Italic" Foreground="{DynamicResource AccentBrush}" Cursor="Hand" TextWrapping="Wrap" ToolTip="Нажмите, чтобы сменить девиз"/>
              <TextBlock x:Name="PingText" Visibility="Collapsed" Margin="0,8,0,0" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap"/>
              <Border x:Name="AlertBox" Visibility="Collapsed" Margin="0,10,0,0" Padding="12,8" CornerRadius="10" BorderThickness="1" BorderBrush="{DynamicResource DangerBrush}" Background="#26EF4444">
                <TextBlock x:Name="AlertText" FontSize="12" TextWrapping="Wrap"/>
              </Border>
              <WrapPanel Orientation="Horizontal" Margin="0,20,0,0">
                <Button x:Name="BtnToggle" Style="{StaticResource Primary}" Width="176" Height="48" FontSize="15" FontWeight="SemiBold" Content="Запустить"/>
                <Button x:Name="BtnRestart" Style="{StaticResource Ghost}" Margin="10,0,0,0" Width="48" Height="48" Padding="0" FontFamily="Segoe MDL2 Assets" FontSize="16" Content="&#xE72C;" ToolTip="Перезапустить"/>
                <Button x:Name="BtnPing" Style="{StaticResource Ghost}" Margin="10,0,0,0" Height="48" Padding="14,0" Content="Пинг" ToolTip="Пинг и скорость: покажет время ответа ваших главных сервисов и скорость скачивания"/>
                <Button x:Name="BtnWarp" Style="{StaticResource Ghost}" Margin="10,0,0,0" Height="48" Padding="13,0" ToolTip="Cloudflare WARP: резервный туннель, когда обход не справляется">
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Text="&#xE774;" FontFamily="Segoe MDL2 Assets" FontSize="15" VerticalAlignment="Center" Margin="0,0,7,0"/>
                    <TextBlock Text="WARP" VerticalAlignment="Center"/>
                    <Ellipse x:Name="WarpDot" Width="7" Height="7" Margin="8,1,0,0" VerticalAlignment="Center" Fill="#64748B"/>
                  </StackPanel>
                </Button>
              </WrapPanel>
            </StackPanel>
          </Grid>
        </Border>

        <Border Grid.Row="2" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="13" Padding="4">
          <Grid x:Name="TabGrid">
            <Border x:Name="TabPill" HorizontalAlignment="Left" Width="0" CornerRadius="9" Background="{DynamicResource AccentBrush}" IsHitTestVisible="False"><Border.RenderTransform><TranslateTransform/></Border.RenderTransform></Border>
          <UniformGrid x:Name="TabRow" Rows="1">
            <RadioButton x:Name="TabLog" Style="{StaticResource TabSeg}" Padding="10,8" Content="Журнал" IsChecked="True" GroupName="tabs"/>
            <RadioButton x:Name="TabLook" Style="{StaticResource TabSeg}" Padding="10,8" Content="Оформление" GroupName="tabs"/>
            <RadioButton x:Name="TabFont" Style="{StaticResource TabSeg}" Padding="10,8" Content="Шрифт" GroupName="tabs"/>
            <RadioButton x:Name="TabSet" Style="{StaticResource TabSeg}" Padding="10,8" Content="Настройки" GroupName="tabs"/>
            <RadioButton x:Name="TabHelp" Style="{StaticResource TabSeg}" Padding="10,8" Content="Инструкция" GroupName="tabs"/>
              <RadioButton x:Name="TabExp" Style="{StaticResource TabSeg}" Padding="10,8" GroupName="tabs" ToolTip="Экспериментальные функции: быстро, резко, рискованно"><StackPanel Orientation="Horizontal"><TextBlock Text="Экспериментальное"/><TextBlock Text="рискованно" FontSize="10" FontWeight="Bold" Foreground="{DynamicResource WarnBrush}" VerticalAlignment="Center" Margin="6,1,0,0"/></StackPanel></RadioButton>
          </UniformGrid>
          </Grid>
        </Border>

        <Grid Grid.Row="4">
          <Border x:Name="PageLog" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="14,12,8,10">
            <Grid>
              <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <DockPanel Margin="0,0,6,10">
                <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                  <Button x:Name="BtnLogCopy" Style="{StaticResource Ghost}" Padding="11,5" FontSize="12" Content="Копировать"/>
                  <Button x:Name="BtnLogClear" Style="{StaticResource Ghost}" Padding="11,5" FontSize="12" Margin="6,0,0,0" Content="Очистить"/>
                </StackPanel>
                <StackPanel Orientation="Horizontal">
                  <RadioButton x:Name="FltAll" Style="{StaticResource Seg}" Padding="12,5" FontSize="12" Content="Все" IsChecked="True" GroupName="logf"/>
                  <RadioButton x:Name="FltKey" Style="{StaticResource Seg}" Padding="12,5" FontSize="12" Content="Важное" GroupName="logf"/>
                  <RadioButton x:Name="FltBad" Style="{StaticResource Seg}" Padding="12,5" FontSize="12" Content="Проблемы" GroupName="logf"/>
                </StackPanel>
              </DockPanel>
              <ScrollViewer x:Name="LogScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                <Grid>
                  <StackPanel x:Name="LogHost" Margin="0,0,6,0"/>
                  <TextBlock x:Name="LogEmpty" Text="Здесь появятся события: запуск, проверки и сбои" Foreground="{DynamicResource SubBrush}" HorizontalAlignment="Center" Margin="0,40,0,0"/>
                </Grid>
              </ScrollViewer>
            </Grid>
          </Border>

          <Border x:Name="PageLook" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,12,0">
                <TextBlock Text="ЦВЕТ АКЦЕНТА" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,8"/>
                <WrapPanel x:Name="AccentDots"/>
                <SliderRow Name="SlR" Title="Красный" Min="0" Max="255"/>
                <SliderRow Name="SlG" Title="Зелёный" Min="0" Max="255"/>
                <SliderRow Name="SlB" Title="Синий" Min="0" Max="255"/>
                <Grid Margin="0,0,0,18">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="110"/></Grid.ColumnDefinitions>
                  <TextBlock Text="Свой цвет (HEX)" VerticalAlignment="Center"/>
                  <TextBox x:Name="HexAccent" Grid.Column="1" Style="{StaticResource Input}" Padding="10,6" MaxLength="7"/>
                </Grid>
                <TextBlock Text="ФОН" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,8"/>
                <WrapPanel x:Name="BgDots"/>
                <Grid Margin="0,0,0,18">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="110"/></Grid.ColumnDefinitions>
                  <TextBlock Text="Свой фон (HEX)" VerticalAlignment="Center"/>
                  <TextBox x:Name="HexBg" Grid.Column="1" Style="{StaticResource Input}" Padding="10,6" MaxLength="7"/>
                </Grid>
                <TextBlock Text="СТЕКЛО И ФОРМА" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,10"/>
                <SliderRow Name="SlOpacity" Title="Прозрачность окна" Min="30" Max="100"/>
                <SliderRow Name="SlPanel" Title="Прозрачность панелей" Min="2" Max="30"/>
                <SliderRow Name="SlGrad" Title="Градиент акцента" Min="0" Max="45"/>
                <SliderRow Name="SlRadius" Title="Скругление углов" Min="0" Max="32"/>
                <StackPanel Margin="0,0,0,12"><TextBlock Text="Фон окна"/><TextBlock Text="Живой фон под интерфейсом в цвет акцента. В режиме производительности он стоит на месте (без анимации)" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,6"/><WrapPanel x:Name="BgFxChips"/></StackPanel>
                <StackPanel Margin="0,0,0,12"><TextBlock Text="Живые фоны ✦"/><TextBlock Text="Фон, который двигается: звёздный полёт, метеоры, пульс сети и эквалайзер под музыку, что играет на компьютере. В трее, свёрнутом окне и в игре засыпает и ничего не ест" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,6"/><WrapPanel x:Name="LiveBgChips"/></StackPanel>
                <Toggle Name="ChkGlow" Title="Свечение" Sub="Мягкое свечение шара при активном обходе"/>
                <Toggle Name="ChkBlur" Title="Размытие фона (Acrylic)" Sub="Экспериментально: окно станет прямоугольным"/>
                <Button x:Name="BtnResetLook" Style="{StaticResource Ghost}" Content="Сбросить оформление" HorizontalAlignment="Left" Margin="0,4,0,6"/>
              </StackPanel>
            </ScrollViewer>
          </Border>

          <Border x:Name="PageFont" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,12,0">
                <TextBlock Text="ШРИФТ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,8"/>
                <WrapPanel x:Name="FontChips" Margin="0,0,0,4"/>
                <TextBlock Text="Нет блокировкам в интернете!" FontSize="15" Margin="0,4,0,12"/>
                <Grid Margin="0,0,0,18">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="200"/></Grid.ColumnDefinitions>
                  <TextBlock Text="Другой шрифт (название)" VerticalAlignment="Center"/>
                  <TextBox x:Name="FontBox" Grid.Column="1" Style="{StaticResource Input}" Padding="10,6"/>
                </Grid>
                <TextBlock Text="РАЗМЕР" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,10"/>
                <SliderRow Name="SlFont" Title="Размер текста" Min="80" Max="130"/>
                <TextBlock Text="ЦВЕТ ТЕКСТА" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,8,0,8"/>
                <WrapPanel x:Name="TextDots"/>
                <Grid Margin="0,0,0,18">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="110"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                  <TextBlock Text="Свой цвет (HEX)" VerticalAlignment="Center"/>
                  <TextBox x:Name="HexText" Grid.Column="1" Style="{StaticResource Input}" Padding="10,6" MaxLength="7"/>
                  <Button x:Name="BtnTextAuto" Grid.Column="2" Style="{StaticResource Ghost}" Padding="12,6" Margin="8,0,0,0" Content="Авто"/>
                </Grid>
                <TextBlock Text="СПИСОК СТРАТЕГИЙ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,10"/>
                <Toggle Name="ChkCompact" Title="Компактный список" Sub="Карточки ниже и плотнее, без строки-описания под названием. Выключено — просторные карточки с описаниями"/>
                <Toggle Name="ChkDesc" Title="Описания под названиями" Sub="Короткая строка о том, для чего стратегия"/>
                <Button x:Name="BtnResetFont" Style="{StaticResource Ghost}" Content="Сбросить шрифт" HorizontalAlignment="Left" Margin="0,4,0,6"/>
              </StackPanel>
            </ScrollViewer>
          </Border>

          <Border x:Name="PageSet" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,12,0">
                <Border CornerRadius="12" Background="{DynamicResource StrokeBrush}" Padding="3" Margin="0,0,0,6" HorizontalAlignment="Left">
                  <WrapPanel>
                    <RadioButton x:Name="SgMain" GroupName="settabs" Style="{StaticResource Seg}" Padding="12,6" Content="Основное" IsChecked="True"/>
                    <RadioButton x:Name="SgNet" GroupName="settabs" Style="{StaticResource Seg}" Padding="12,6" Content="Связь и пинг"/>
                    <RadioButton x:Name="SgSys" GroupName="settabs" Style="{StaticResource Seg}" Padding="12,6" Content="Система"/>
                  </WrapPanel>
                </Border>
                <StackPanel x:Name="SetGrpMain">
                <StackPanel Margin="0,4,0,12"><TextBlock Text="ГОТОВЫЕ НАБОРЫ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <WrapPanel x:Name="PresetHost" Margin="0,0,0,0"/>
                <TextBlock x:Name="PresetState" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,6"/>
                <StackPanel Margin="0,4,0,12"><TextBlock Text="ВИД" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Grid Margin="0,0,0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                  <StackPanel VerticalAlignment="Center" Margin="0,0,16,0"><TextBlock Text="Простой режим" FontSize="13" FontWeight="SemiBold" Foreground="{DynamicResource TextBrush}"/><TextBlock x:Name="SimpleText" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,2,0,0"/></StackPanel>
                  <Button x:Name="BtnSimple" Grid.Column="1" Style="{StaticResource Primary}" Padding="16,8" Content="Простой режим" VerticalAlignment="Center"/>
                </Grid>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ОКНО И ЗАПУСК" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkAutoLast" Title="Запускать последнюю стратегию при старте" Sub="Автоматически поднимать обход при запуске программы"/>
                <Toggle Name="ChkWinStart" Title="Запускать вместе с Windows" Sub="Через планировщик задач, с правами администратора"/>
                <Toggle Name="ChkTray" Title="Сворачивать в трей при закрытии" Sub="Крестик прячет окно, обход продолжает работать"/>
                <Toggle Name="ChkStopExit" Title="Останавливать обход при выходе" Sub="Полный выход через меню в трее"/>
                <Toggle Name="ChkTop" Title="Поверх всех окон" Sub=""/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="УДОБСТВО" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkSplash" Title="Заставка при запуске" Sub="12 сюжетов + классика. Выключите — окно откроется сразу"/>
                <StackPanel Margin="0,0,0,12"><TextBlock Text="Вариант заставки"/><TextBlock Text="«Случайно» — каждый запуск новый сюжет" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,6"/><WrapPanel x:Name="IntroChips"/><Button x:Name="BtnIntroPreview" Style="{StaticResource Ghost}" Content="Посмотреть заставку" HorizontalAlignment="Left" Margin="0,4,0,0"/></StackPanel>
                <Toggle Name="ChkSound" Title="Звук при сбое и восстановлении" Sub="Короткий системный звук. В игре (с геймрежимом) молчит"/>
                </StackPanel>
                <StackPanel x:Name="SetGrpNet" Visibility="Collapsed">
                <StackPanel Margin="0,4,0,12"><TextBlock Text="ЖИВОЙ ПИНГ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <SliderRow Name="SlLive" Title="Живой пинг: интервал" Min="0" Max="300"/>
                <TextBlock Text="Только пинг, без скачивания: один короткий запрос к каждому сервису на уже открытом соединении (меньше 1 КБ). От 5 секунд до 5 минут, 0 — выключено. Показывается под статусом обхода и обновляется само" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,12"/>
                <Toggle Name="ChkPingSpeed" Title="Кнопка «Пинг» меряет и скорость" Sub="Выключите, чтобы не тратить трафик: кнопка будет мерить только пинг. Скорость — это до 8 МБ за раз"/>
                <Toggle Name="ChkAutoPing" Title="Мерить пинг после запуска стратегии" Sub="Через 6 секунд после запуска покажет пинг, без скачивания. Не нужен, если включён живой пинг"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="СЛЕЖЕНИЕ ЗА СВЯЗЬЮ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkMon" Title="Следить за связью" Sub="Раз в несколько минут проверяет ваши сервисы из подбора. При сбое значок краснеет и пишет причину"/>
                <SliderRow Name="SlMonInt" Title="Интервал проверки" Min="1" Max="5"/>
                <Toggle Name="ChkAutoFix" Title="Автовосстановление" Sub="При сбое: перезапуск стратегии, затем следующая лучшая из подбора"/>
                <Button x:Name="BtnCheckNow" Style="{StaticResource Ghost}" Content="Проверить связь сейчас" HorizontalAlignment="Left" Margin="0,0,0,14"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ОБХОД (WINWS)" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkHide" Title="Прятать окно winws" Sub="Консоль zapret не будет висеть на панели задач"/>
                <Toggle Name="ChkKeep" Title="Не давать обходу обрываться" Sub="Перезапуск, если winws закрылся сам, после сна компьютера, смены сети или сбоя связи. Не сдаётся: повторяет попытки со сбросом WinDivert"/>
                </StackPanel>
                <StackPanel x:Name="SetGrpSys" Visibility="Collapsed">
                <StackPanel Margin="0,4,0,12"><TextBlock Text="ПРОИЗВОДИТЕЛЬНОСТЬ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkPerf" Title="Режим производительности" Sub="Без теней, свечения и анимаций. Включите, если интерфейс тормозит"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ПАПКА СО СТРАТЕГИЯМИ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <TextBlock x:Name="FolderText" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,10"/>
                <StackPanel Orientation="Horizontal" Margin="0,0,0,6">
                  <Button x:Name="BtnFolder" Style="{StaticResource Ghost}" Content="Выбрать папку…"/>
                  <Button x:Name="BtnRescan" Style="{StaticResource Ghost}" Content="Обновить список" Margin="8,0,0,0"/>
                  <Button x:Name="BtnOpen" Style="{StaticResource Ghost}" Content="Открыть" Margin="8,0,0,0"/>
                </StackPanel>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ЯРЛЫК" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <TextBlock Text="Ярлык со значком перечёркнутого РКН: запускайте программу с рабочего стола" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,10"/>
                <Button x:Name="BtnShortcut" Style="{StaticResource Ghost}" Content="Создать ярлык на рабочем столе" HorizontalAlignment="Left" Margin="0,0,0,6"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="РЕЗЕРВНАЯ КОПИЯ НАСТРОЕК" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <TextBlock Text="Настройки, избранное и результаты подбора — в один файл на рабочем столе. Пригодится при переустановке или переезде на другой компьютер" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,12"/>
                <WrapPanel>
                  <Button x:Name="BtnCfgExport" Style="{StaticResource Ghost}" Content="Сохранить копию" Margin="0,0,8,8"/>
                  <Button x:Name="BtnCfgImport" Style="{StaticResource Ghost}" Content="Загрузить из копии…" Margin="0,0,8,8"/>
                  <Button x:Name="BtnCfgFolder" Style="{StaticResource Ghost}" Content="Где лежат настройки" Margin="0,0,8,8"/>
                </WrapPanel>
                </StackPanel>
              </StackPanel>
            </ScrollViewer>
          </Border>

          <Border x:Name="PageExp" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,12,0">
                <Border Padding="12,10" CornerRadius="10" BorderThickness="1" BorderBrush="{DynamicResource WarnBrush}" Background="#1FF59E0B">
                  <StackPanel>
                    <TextBlock Text="РИСКОВАННО · ЭКСПЕРИМЕНТАЛЬНО" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource WarnBrush}"/>
                    <TextBlock Text="Эти функции дают максимум, но могут вести себя резко. Включайте по одной и смотрите на результат — если стало хуже, просто выключите тумблер." FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,4,0,0"/>
                  </StackPanel>
                </Border>
                <Border CornerRadius="12" Background="{DynamicResource StrokeBrush}" Padding="3" Margin="0,0,0,6" HorizontalAlignment="Left">
                  <WrapPanel>
                    <RadioButton x:Name="EgStab" GroupName="exptabs" Style="{StaticResource Seg}" Padding="12,6" Content="Стабильность" IsChecked="True"/>
                    <RadioButton x:Name="EgPick" GroupName="exptabs" Style="{StaticResource Seg}" Padding="12,6" Content="Подбор"/>
                    <RadioButton x:Name="EgSpeed" GroupName="exptabs" Style="{StaticResource Seg}" Padding="12,6" Content="Скорость"/>
                    <RadioButton x:Name="EgGame" GroupName="exptabs" Style="{StaticResource Seg}" Padding="12,6" Content="Игра"/>
                  </WrapPanel>
                </Border>
                <StackPanel x:Name="ExpGrpStab">
                <StackPanel Margin="0,4,0,12"><TextBlock Text="МГНОВЕННОЕ ПЕРЕКЛЮЧЕНИЕ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkInstant" Title="Мгновенное переключение" Sub="Сервис отвалился: через секунды включается следующая лучшая стратегия"/>
                <StackPanel x:Name="InstantHelp"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="АНТИ-ДУШИЛКА" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkThrottle" Title="Анти-душилка (блокировка 16–20 КБ)" Sub="Сайт открывается, а видео и данные встают: так РКН душит сервис. Замечает это и меняет стратегию. Нужно слежение за связью"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="РАННИЙ СИГНАЛ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkEarly" Title="Ранний сигнал" Sub="Живой пинг дважды не достучался до сервиса: проверка связи сразу, без ожидания расписания"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="БЕЗ QUIC" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkNoQuic" Title="Без QUIC (YouTube стабильнее)" Sub="Запрещает UDP 443 в брандмауэре: браузер идёт по TCP, который обходится надёжнее. Голос Discord не затрагивает"/>
                <StackPanel x:Name="StabHelp"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="БРАУЗЕР" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Grid Margin="0,0,0,8">
                  <Border Panel.ZIndex="-1" Style="{StaticResource RowCard}"/>
                  <Border Width="32" Height="32" CornerRadius="10" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="14,12,0,0" Background="#268B5CF6" BorderBrush="#408B5CF6" BorderThickness="1" IsHitTestVisible="False"><TextBlock Text="🌐" FontFamily="Segoe UI Emoji" FontSize="15" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
                  <StackPanel Margin="58,10,16,12">
                    <TextBlock Text="Настроить ваш браузер под Zapret Studio" FontSize="13" FontWeight="SemiBold" Foreground="{DynamicResource TextBrush}" TextWrapping="Wrap"/>
                    <TextBlock Text="Безопасный DNS и без QUIC — как советуют авторы zapret. 20 популярных браузеров, одной кнопкой" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,2,0,10"/>
                    <StackPanel Orientation="Horizontal">
                      <Button x:Name="BtnBrw" Style="{StaticResource Primary}" Padding="16,8" Content="Настроить браузеры"/>
                      <Button x:Name="BtnBrwUndo" Style="{StaticResource Ghost}" Content="Вернуть как было" Margin="8,0,0,0"/>
                    </StackPanel>
                    <TextBlock x:Name="BrwState" FontSize="11" FontWeight="SemiBold" Foreground="{DynamicResource AccentBrush}" TextWrapping="Wrap" Margin="0,8,0,0"/>
                    <WrapPanel x:Name="BrwList" Margin="0,6,0,0"/>
                  </StackPanel>
                </Grid>
                </StackPanel>
                <StackPanel x:Name="ExpGrpPick" Visibility="Collapsed">
                <StackPanel Margin="0,4,0,12"><TextBlock Text="СУПЕР-ПОДБОР" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkTurbo" Title="Супер-подбор (турбо)" Sub="Ускоряет каждую проверку, но проверяет все стратегии. В «только нужной» — финал по пингу"/>
                <StackPanel x:Name="TurboHelp"/>
                </StackPanel>
                <StackPanel x:Name="ExpGrpSpeed" Visibility="Collapsed">
                <StackPanel Margin="0,4,0,12"><TextBlock Text="УСКОРЕНИЕ (ПИНГ)" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <TextBlock x:Name="BoostState" FontSize="11" FontWeight="SemiBold" Foreground="{DynamicResource AccentBrush}" TextWrapping="Wrap" Margin="0,0,0,10"/>
                <StackPanel Orientation="Horizontal" Margin="0,0,0,12">
                  <Button x:Name="BtnBoost" Style="{StaticResource Primary}" Padding="16,8" Content="Ускорить стратегии"/>
                  <Button x:Name="BtnUnboost" Style="{StaticResource Ghost}" Content="Откатить ускорение" Margin="8,0,0,0"/>
                </StackPanel>
                <StackPanel x:Name="BoostHelp"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ЕЩЁ БЫСТРЕЕ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkDnsWarm" Title="Тёплый DNS" Sub="Заранее держит адреса ваших сервисов в кэше: первое открытие без ожидания DNS"/>
                <Toggle Name="ChkFlushDns" Title="Умный DNS" Sub="Перед запуском сбрасывает кэш DNS (старые заглушки провайдера не мешают), а потом держит адреса ваших сервисов тёплыми — первое открытие без ожидания"/>
                <Toggle Name="ChkFavOnly" Title="Подбор только по избранным" Sub="Проверяются только стратегии со звёздочкой. Секунды вместо минут"/>
                <StackPanel x:Name="ExtraHelp"/>
                </StackPanel>
                <StackPanel x:Name="ExpGrpGame" Visibility="Collapsed">
                <StackPanel Margin="0,4,0,12"><TextBlock Text="ГЕЙММОД" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkGame" Title="Геймрежим" Sub="Все игры идут напрямую через ваш интернет, а не через обход. Программа тихая"/>
                <TextBlock x:Name="GameState" FontSize="11" FontWeight="SemiBold" Foreground="{DynamicResource AccentBrush}" TextWrapping="Wrap" Margin="0,0,0,10"/>
                <StackPanel x:Name="GameHelp"/>
                </StackPanel>
              </StackPanel>
            </ScrollViewer>
          </Border>
          <Border x:Name="PageHelp" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,12,0"><StackPanel x:Name="HelpHost"/>
<Popup x:Name="HelpPop" Placement="Bottom" AllowsTransparency="True" StaysOpen="True" IsHitTestVisible="False" VerticalOffset="-4" HorizontalOffset="-14">
  <Border x:Name="HelpPopCard" Width="460" Margin="14" Background="#F5141420" BorderBrush="{DynamicResource AccentBrush}" BorderThickness="1.5" CornerRadius="16" Padding="18,16" RenderTransformOrigin="0.5,0">
    <Border.RenderTransform><TransformGroup><ScaleTransform ScaleX="1" ScaleY="1"/><TranslateTransform Y="0"/></TransformGroup></Border.RenderTransform>
    <Border.Effect><DropShadowEffect BlurRadius="28" ShadowDepth="0" Opacity="0.75" Color="Black"/></Border.Effect>
    <StackPanel>
      <DockPanel>
        <Border Width="40" Height="40" CornerRadius="12" Background="{DynamicResource AccentBrush}" DockPanel.Dock="Left"><TextBlock x:Name="HelpPopIcon" FontFamily="Segoe UI Emoji" FontSize="20" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
        <StackPanel Margin="12,0,0,0" VerticalAlignment="Center">
          <TextBlock x:Name="HelpPopSec" FontSize="10" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/>
          <TextBlock x:Name="HelpPopTitle" FontSize="16" FontWeight="Bold" TextWrapping="Wrap" Foreground="#FFFFFF"/>
        </StackPanel>
      </DockPanel>
      <Border Height="1" Background="#26FFFFFF" Margin="0,12,0,10"/>
      <StackPanel x:Name="HelpPopBody"/>
    </StackPanel>
  </Border>
</Popup></StackPanel>
            </ScrollViewer>
          </Border>
        </Grid>
      </Grid>
      <!-- сборка 8: настройки на всю рабочую область -->
      <Grid x:Name="SetHub" Grid.ColumnSpan="3" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <Border Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="12,10" Margin="0,0,0,12">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <Button x:Name="SetBack" Style="{StaticResource Ghost}" Content="←  Назад" VerticalAlignment="Center" ToolTip="Вернуться"/>
            <StackPanel Grid.Column="1" Margin="14,0,18,0" VerticalAlignment="Center">
              <TextBlock Text="Настройки" FontSize="18" FontWeight="Bold"/>
              <TextBlock x:Name="SetFound" Text="Всё в одном месте" FontSize="11" Foreground="{DynamicResource SubBrush}"/>
            </StackPanel>
            <Border Grid.Column="2" CornerRadius="11" Background="#14FFFFFF" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" Height="36" VerticalAlignment="Center" MaxWidth="460">
              <Grid Margin="10,0,4,0">
                <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBlock Text="&#xE721;" FontFamily="Segoe MDL2 Assets" FontSize="13" VerticalAlignment="Center" Foreground="{DynamicResource SubBrush}"/>
                <TextBlock x:Name="SetSearchHint" Grid.Column="1" Margin="11,0,0,0" Text="Поиск по настройкам…" FontSize="13" VerticalAlignment="Center" Foreground="{DynamicResource SubBrush}" IsHitTestVisible="False"/>
                <TextBox x:Name="SetSearch" Grid.Column="1" Margin="8,0,0,0" Background="Transparent" BorderThickness="0" Foreground="{DynamicResource TextBrush}" CaretBrush="{DynamicResource TextBrush}" VerticalAlignment="Center" FontSize="13"/>
                <Button x:Name="SetSearchClear" Grid.Column="2" Style="{StaticResource TitleBtn}" Content="&#xE711;" Width="28" Height="28" Visibility="Collapsed" ToolTip="Очистить поиск"/>
              </Grid>
            </Border>
            <StackPanel Grid.Column="3" Orientation="Horizontal" Margin="14,0,0,0" VerticalAlignment="Center">
              <Border CornerRadius="10" Background="#10FFFFFF" Padding="10,6" MaxWidth="340" VerticalAlignment="Center">
                <TextBlock x:Name="SetPingText" Text="● Пинг ещё не проверяли" FontSize="11" Foreground="{DynamicResource SubBrush}" TextTrimming="CharacterEllipsis"/>
              </Border>
              <Button x:Name="BtnSetPing" Style="{StaticResource Ghost}" Content="Пинг" Margin="8,0,0,0" ToolTip="Проверить пинг, не выходя из настроек"/>
            </StackPanel>
          </Grid>
        </Border>
        <Grid Grid.Row="1">
          <Grid.ColumnDefinitions><ColumnDefinition Width="240"/><ColumnDefinition Width="14"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
          <Border Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="8">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled"><StackPanel x:Name="SetNav"/></ScrollViewer>
          </Border>
          <Border Grid.Column="2" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="20,16,8,16">
            <Grid>
              <ScrollViewer x:Name="SetScroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled"><StackPanel x:Name="SetContent" Margin="0,0,14,0"/></ScrollViewer>
              <StackPanel x:Name="SetNoHits" Visibility="Collapsed" VerticalAlignment="Center" HorizontalAlignment="Center" IsHitTestVisible="False">
                <TextBlock Text="🔍" FontFamily="Segoe UI Emoji" FontSize="34" HorizontalAlignment="Center"/>
                <TextBlock Text="Ничего не нашлось" FontSize="16" FontWeight="Bold" HorizontalAlignment="Center" Margin="0,8,0,4"/>
                <TextBlock Text="Попробуйте короче: «пинг», «турбо», «шрифт», «трей», «турбо»" FontSize="12" Foreground="{DynamicResource SubBrush}" HorizontalAlignment="Center"/>
              </StackPanel>
            </Grid>
          </Border>
        </Grid>
      </Grid>
    </Grid>
    <Border x:Name="Overlay" Grid.RowSpan="3" Visibility="Collapsed" Background="#B3000000" CornerRadius="18">
      <Grid>
        <Border x:Name="PrioPanel" Visibility="Collapsed" Width="480" MaxHeight="580" Margin="20" HorizontalAlignment="Center" VerticalAlignment="Center" Background="{DynamicResource DialogBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="18" Padding="24,22">
          <DockPanel>
            <TextBlock DockPanel.Dock="Top" Text="Что для вас важнее?" FontSize="20" FontWeight="Bold"/>
            <TextBlock DockPanel.Dock="Top" Margin="0,6,0,14" TextWrapping="Wrap" Foreground="{DynamicResource SubBrush}" Text="Отметьте сервисы: стратегии проверят именно на них. Звёздочка делает сервис главным, и его вес в 2 раза больше."/>
            <StackPanel DockPanel.Dock="Bottom" Margin="0,14,0,0">
              <TextBlock x:Name="PrioEta" FontSize="11" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,10"/>
              <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
                <Button x:Name="BtnPrioCancel" Style="{StaticResource Ghost}" Content="Отмена"/>
                <Button x:Name="BtnPrioStart" Style="{StaticResource Primary}" Margin="10,0,0,0" Content="Начать проверку"/>
              </StackPanel>
            </StackPanel>
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,6,0">
                <TextBlock Text="РЕЖИМ ПРОВЕРКИ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,6"/>
                <Border Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="13" Padding="4" HorizontalAlignment="Left">
                  <WrapPanel Orientation="Horizontal">
                    <RadioButton x:Name="ModeTarget" Style="{StaticResource Seg}" Padding="12,6" Content="Только нужная" GroupName="pmode" IsChecked="True" ToolTip="Проверяет все стратегии, но только на отмеченных сервисах, и показывает рейтинг. Сама ничего не подключает."/>
                    <RadioButton x:Name="ModeFull" Style="{StaticResource Seg}" Padding="12,6" Content="Полная проверка" GroupName="pmode" ToolTip="Проверяет все стратегии на все сервисы из списка (отметки не нужны). Самый долгий режим, зато самая полная картина."/>
                    <RadioButton x:Name="ModeUrgent" Style="{StaticResource Seg}" Padding="12,6" Content="Срочная проверка" GroupName="pmode" ToolTip="Ищет стратегию для отмеченных сервисов и сразу подключает первую, которая открывает их все. Дальше не проверяет."/>
                  </WrapPanel>
                </Border>
                <TextBlock x:Name="ModeDesc" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="2,8,0,14"/>
                <TextBlock Text="СЕРВИСЫ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,6"/>
                <StackPanel x:Name="PrioList"/>
                <TextBlock Text="СВОЙ САЙТ (НЕОБЯЗАТЕЛЬНО)" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,10,0,6"/>
                <TextBox x:Name="PrioCustom" Style="{StaticResource Input}" ToolTip="Например: example.com, other.org"/>
              </StackPanel>
            </ScrollViewer>
          </DockPanel>
        </Border>
        <Border x:Name="OnbPanel" Visibility="Collapsed" Width="580" MaxHeight="640" Margin="20" HorizontalAlignment="Center" VerticalAlignment="Center" Background="{DynamicResource DialogBrush}" BorderBrush="{DynamicResource AccentBrush}" BorderThickness="1.5" CornerRadius="20" Padding="26,22" RenderTransformOrigin="0.5,0.5" ClipToBounds="False">
          <Border.RenderTransform><ScaleTransform x:Name="OnbScale" ScaleX="1" ScaleY="1"/></Border.RenderTransform>
          <Border.Effect><DropShadowEffect BlurRadius="40" ShadowDepth="0" Opacity="0.6" Color="Black"/></Border.Effect>
          <DockPanel>
            <Grid DockPanel.Dock="Top" Margin="0,0,0,16">
              <TextBlock x:Name="OnbStepText" Text="ШАГ 1 ИЗ 3" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}" VerticalAlignment="Center"/>
              <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center">
                <Border x:Name="OnbDot1" Width="26" Height="6" CornerRadius="3" Background="{DynamicResource AccentBrush}" Margin="0,0,6,0"/>
                <Border x:Name="OnbDot2" Width="10" Height="6" CornerRadius="3" Background="{DynamicResource StrokeBrush}" Margin="0,0,6,0"/>
                <Border x:Name="OnbDot3" Width="10" Height="6" CornerRadius="3" Background="{DynamicResource StrokeBrush}"/>
              </StackPanel>
            </Grid>
            <Grid DockPanel.Dock="Bottom" Margin="0,18,0,0">
              <Button x:Name="OnbBack" Style="{StaticResource Ghost}" Content="Не принимаю" HorizontalAlignment="Left"/>
              <Button x:Name="OnbNext" Style="{StaticResource Primary}" Content="Принимаю и продолжаю" HorizontalAlignment="Right"/>
            </Grid>
