                <Button x:Name="BtnWarpOff" Style="{StaticResource Ghost}" Padding="18,10" Content="Отключить" Margin="0,0,8,8" IsEnabled="False"/>
              </WrapPanel>
              <StackPanel Margin="0,10,0,12">
                <TextBlock Text="ЧТО ТАКОЕ WARP" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/>
                <Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,10"/>
