                        <Border.RenderTransform><TransformGroup><ScaleTransform ScaleX="0.6" ScaleY="0.6"/><TranslateTransform Y="16"/></TransformGroup></Border.RenderTransform>
                        <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="0" Opacity="0.8" Color="Black"/></Border.Effect>
