$script:TogIcons = @{
    ChkGlow = 0x2728; ChkBlur = 0x1F32B; ChkCompact = 0x1F4D0; ChkDesc = 0x1F4DD; ChkTray = 0x1F4E5; ChkAutoLast = 0x23EF
    ChkWinStart = 0x1F4BB; ChkTop = 0x1F4CC; ChkSplash = 0x1F3AC; ChkSound = 0x1F514; ChkStopExit = 0x23F9; ChkPingSpeed = 0x1F4F6
    ChkAutoPing = 0x23F1; ChkMon = 0x1F4E1; ChkAutoFix = 0x1F6E0; ChkHide = 0x1F648; ChkKeep = 0x1F517
    ChkPerf = 0x26A1; ChkInstant = 0x1F501; ChkThrottle = 0x1F40C; ChkEarly = 0x1F6A8; ChkNoQuic = 0x1F9F1
    ChkTurbo = 0x1F680; ChkDnsWarm = 0x1F525; ChkFlushDns = 0x1F9F9; ChkFavOnly = 0x2B50; ChkGame = 0x1F579; ChkSimple = 0x1F331
}
function Get-TogIcon([string]$n) { $c = $script:TogIcons[$n]; if (-not $c) { $c = 0x2699 }; [char]::ConvertFromUtf32([int]$c) }
$Xaml = [regex]::Replace($Xaml, '<Toggle Name="(\w+)" Title="([^"]*)" Sub="([^"]*)"\s*/>', {
    param($m)
    [void]$script:ToggleNames.Add($m.Groups[1].Value)
    $sub = ''
    if ($m.Groups[3].Value) { $sub = '<TextBlock Text="' + $m.Groups[3].Value + '" FontSize="11" Style="{StaticResource RowSub}"/>' }
    '<Grid Margin="0,0,0,8" Background="Transparent" Cursor="Hand"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>' +
    '<StackPanel VerticalAlignment="Center" Margin="58,10,16,10"><TextBlock Text="' + $m.Groups[2].Value + '" FontSize="13" FontWeight="SemiBold" TextWrapping="Wrap"/>' + $sub + '</StackPanel>' +
    '<CheckBox x:Name="' + $m.Groups[1].Value + '" Grid.Column="1" Style="{StaticResource Switch}" VerticalAlignment="Center" Margin="0,0,14,0"/>' +
    '<Border Grid.ColumnSpan="2" Panel.ZIndex="-1" Style="{StaticResource RowCard}"/>' +
    '<Border Tag="zs-ico" Width="32" Height="32" CornerRadius="10" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="14,0,0,0" Background="#268B5CF6" BorderBrush="#408B5CF6" BorderThickness="1" IsHitTestVisible="False">' +
    '<TextBlock Text="' + (Get-TogIcon $m.Groups[1].Value) + '" FontFamily="Segoe UI Emoji" FontSize="15" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border></Grid>'
})
$Xaml = [regex]::Replace($Xaml, '<SliderRow Name="(\w+)" Title="([^"]*)" Min="(\d+)" Max="(\d+)"\s*/>', {
    param($m)
    '<Grid Margin="0,0,0,10"><Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="*"/><ColumnDefinition Width="52"/></Grid.ColumnDefinitions>' +
    '<TextBlock Text="' + $m.Groups[2].Value + '" FontWeight="SemiBold" VerticalAlignment="Center"/>' +
    '<Slider x:Name="' + $m.Groups[1].Value + '" Grid.Column="1" Style="{StaticResource Sld}" Minimum="' + $m.Groups[3].Value + '" Maximum="' + $m.Groups[4].Value + '" VerticalAlignment="Center"/>' +
    '<TextBlock x:Name="Lb' + $m.Groups[1].Value + '" Grid.Column="2" HorizontalAlignment="Right" VerticalAlignment="Center" Foreground="{DynamicResource SubBrush}"/></Grid>'
})

# размеры шрифта идут через ресурсы Fs11, Fs12 ... - их масштабирует вкладка "Шрифт"
$script:FsUsed = @{}
function Scale-Xaml([string]$x) {
    $r = [regex]::Replace($x, '<[A-Za-z][^<>]*>', {
        param($m)
        $t = $m.Value
        if ($t -match 'MDL2|Symbol|Consolas') { return $t }
        [regex]::Replace($t, '\bFontSize="(\d+)"', { param($k) 'FontSize="{DynamicResource Fs' + $k.Groups[1].Value + '}"' })
    })
    foreach ($mm in [regex]::Matches($r, 'Fs(\d+)\}')) { $script:FsUsed[[int]$mm.Groups[1].Value] = 1 }
    if ($app) { Set-FsRes }
    $r
}
function Set-FsRes {
    $k = [double]$Cfg.FontScale / 100
    foreach ($i in @($script:FsUsed.Keys)) { $app.Resources['Fs' + $i] = [double][Math]::Round([int]$i * $k, 1) }
}
$Xaml = Scale-Xaml $Xaml
$app = New-Object System.Windows.Application
$app.ShutdownMode = 'OnExplicitShutdown'
Set-FsRes
Pump-Ui
$Win = [Windows.Markup.XamlReader]::Parse($Xaml)
function N([string]$n) { $Win.FindName($n) }
foreach ($n in 'RenamePanel','RenameBox','RenFile','RenChip','BtnRenReset','BtnRenCancel','BtnRenSave','BtnSort','AlertBox','AlertText','MonText','ChkMon','ChkAutoFix','SlMonInt','LbSlMonInt','BtnCheckNow','Shell','ShadowHost','Overlay','PrioPanel','ResultPanel','PrioList','PrioCustom','PrioEta','BtnPrioCancel','BtnPrioStart','ResTitle','ResBest','ResBestSub','ResList','BtnResClose','BtnResRun','TitleLogoHost','ChkPerf','BtnShortcut','GripL','GripR','GripT','GripB','GripTL','GripTR','GripBL','GripBR','TitleBar','BtnPin','BtnMin','BtnClose','CountText','SearchBox','SearchHint','ListHost','BtnAuto','ProgTrack','ProgFill','AutoText',
    'RingPulse','RingWave','WaveScale','OrbScale','GlyphScale','StratMove','SloganText','PingText','BtnPing','BtnWarp','OrbCore','OrbGlyph','StatusText','StrategyText','UptimeText','BtnToggle','BtnRestart','TabLog','TabLook','TabSet','PageLog','PageLook','PageSet','LogHost','LogScroll','LogEmpty','FltAll','FltKey','FltBad','BtnLogClear','BtnLogCopy',
    'AccentDots','BgDots','SlR','SlG','SlB','HexAccent','HexBg','SlOpacity','SlPanel','SlGrad','SlRadius','ChkGlow','ChkBlur','BtnResetLook',
    'ChkTray','ChkAutoLast','ChkStopExit','ChkHide','ChkTop','ChkWinStart','FolderText','BtnFolder','BtnRescan','BtnOpen',
    'LbSlR','LbSlG','LbSlB','LbSlOpacity','LbSlPanel','LbSlGrad','LbSlRadius','TabFont','PageFont','FontChips','FontBox','SlFont','LbSlFont','TextDots','HexText','BtnTextAuto','ChkCompact','ChkDesc','BtnResetFont','TabHelp','PageHelp','HelpHost','TabExp','PageExp','BtnSimple','SimpleText','ChkTurbo','ChkGame','ChkInstant','TurboHelp','GameHelp','InstantHelp','ChkSplash','ChkAutoPing','ChkSound','ChkDnsWarm','ChkFavOnly','BtnBoost','BtnUnboost','BoostState','BoostHelp','ExtraHelp','LiveText','SlLive','LbSlLive','ChkPingSpeed','SgMain','SgNet','SgSys','SetGrpMain','SetGrpNet','SetGrpSys','EgPick','EgStab','EgSpeed','EgGame','ExpGrpPick','ExpGrpStab','ExpGrpSpeed','ExpGrpGame','ChkThrottle','ChkEarly','ChkNoQuic','StabHelp','BtnCfgExport','BtnCfgImport','BtnCfgFolder','GameState','ColLeft','ColOrb','OrbHost','SearchRow','CountText','BtnSort','BtnAbout','AboutPanel','BtnAboutClose','ChkKeep','ModeTarget','ModeFull','ModeUrgent','ModeDesc','BgFx','BgFxChips','IntroChips','BtnIntroPreview','ChkFlushDns','BadgeDad','BadgeKol','PopDad','PopKol','PopDadCard','PopKolCard','NickDad','NickKol','DiscDad','DiscKol','AboutToast','BtnGit','HelpPop','HelpPopCard','HelpPopIcon','HelpPopSec','HelpPopTitle','HelpPopBody','OnbPanel','OnbScale','OnbStepText','OnbDot1','OnbDot2','OnbDot3','OnbBack','OnbNext','OnbBody','OnbSlide','OnbStep1','OnbStep2','OnbStep3','OnbLic','OnbAgree','OnbTour','OnbFx','OnbHalo','OnbHaloScale','OnbShieldScale','OnbCheck','OnbLuck','OnbLuckSub','LiveBgChips','TabGrid','TabPill','MainArea','SetHub','SetBack','SetFound','SetSearch','SetSearchHint','SetSearchClear','SetPingText','BtnSetPing','SetNav','SetScroll','SetContent','SetNoHits','VerPill') {
