$script:Alert = $null; $script:Mon = $null; $script:NextCheck = $null; $script:MonConfirm = $false
$script:FixTried = @(); $script:LastStrategy = $null
$script:CtlUrl = 'http://www.msftconnecttest.com/connecttest.txt'
$script:OrbAlert = New-Object System.Windows.Media.RadialGradientBrush
$script:OrbAlert.GradientOrigin = New-Object System.Windows.Point 0.35, 0.3
$script:OrbAlert.GradientStops.Add((GStop (ToColor '#FF8A8A') 0))
$script:OrbAlert.GradientStops.Add((GStop (ToColor '#EF4444') 0.75))
$script:OrbAlert.GradientStops.Add((GStop (ToColor '#9F1D1D') 1))

function Get-MonSvcs {
    $keys = @($Cfg.PrioServices)
    if ($keys.Count -eq 0 -and -not $Cfg.PrioCustom) { $keys = @('yt', 'dc') }
    $r = @()
    foreach ($s in $script:Services) { if ($keys -contains $s.Key) { $r += @{ Key = $s.Key; Name = $s.Name; Short = $s.Short; Urls = $s.Urls } } }
    $cu = @(Get-CustomUrls ([string]$Cfg.PrioCustom))
    if ($cu.Count -gt 0) { $r += @{ Key = 'custom'; Name = 'Свой сайт'; Short = 'Сайт'; Urls = $cu } }
    $r
}

function Get-FailReason($task) {
    try {
        if ($task.Status -eq 'Canceled') { return 'таймаут: сервер не отвечает' }
        if ($task.Status -eq 'Faulted') {
            $e = $task.Exception; $web = $null
            while ($e) { if ($e -is [System.Net.WebException]) { $web = $e; break }; $e = $e.InnerException }
            if ($web) {
                switch ([string]$web.Status) {
                    'NameResolutionFailure' { return 'DNS не отвечает (адрес не найден)' }
                    'ConnectFailure' { return 'не удаётся подключиться' }
                    'ReceiveFailure' { return 'соединение сброшено (похоже на блокировку DPI)' }
                    'SendFailure' { return 'соединение сброшено при отправке' }
                    'ConnectionClosed' { return 'соединение закрыто сервером' }
                    'SecureChannelFailure' { return 'ошибка TLS: рукопожатие сорвано (блокировка)' }
                    'TrustFailure' { return 'ошибка сертификата (возможна подмена)' }
                    'Timeout' { return 'таймаут' }
                }
                return 'ошибка: ' + $web.Message
            }
            return 'ошибка: ' + $task.Exception.GetBaseException().Message
        }
        return 'таймаут: нет ответа'
    } catch { return 'неизвестная ошибка' }
}

# минимальное время ответа среди успешных запросов одного сервиса (мс) или $null
function Get-SvcMs($mine) {
    $ms = @()
    foreach ($t in $mine) { if ($t.Task.Status -eq 'RanToCompletion') { try { $ms += [double]$t.Task.Result } catch { } } }
    if ($ms.Count -eq 0) { return $null }
    [int]($ms | Measure-Object -Minimum).Minimum
}
# строка вида « · YT 85 мс · DC 130 мс» (пустая, если ни один сервис не ответил)
function Get-PingLine($tasks, $svcs, [int]$max) {
    $parts = @()
    foreach ($s in $svcs) {
        if ($parts.Count -ge $max) { break }
        $v = Get-SvcMs @($tasks | Where-Object { $_.Svc -eq $s.Key })
        if ($null -ne $v) { $parts += ('{0} {1} мс' -f $s.Short, $v) }
    }
    if ($parts.Count -eq 0) { return '' }
    ' · ' + ($parts -join ' · ')
}
# пинг стратегии из сохранённого результата теста (для сравнения при равном проценте)
function Get-ResMs([string]$name) {
    if ($Results.ContainsKey($name) -and ([string]$Results[$name] -match '·\s+(\d+) мс\s*$')) { return [double]$Matches[1] }
    return 1e9
}

function Set-Slogan([bool]$anim) {
    $txt = Get-Slogan
    if (-not $anim -or $Cfg.Perf -or -not $Win.IsVisible) { $SloganText.Text = $txt; return }
    try {
        if (-not ($SloganText.RenderTransform -is [Windows.Media.TranslateTransform])) { $SloganText.RenderTransform = New-Object Windows.Media.TranslateTransform }
        $script:SlNext = $txt
        $ei = New-Object Windows.Media.Animation.CubicEase; $ei.EasingMode = 'EaseIn'
        $o = New-Anim4 ([double]::NaN) 0 200 0 $ei
        $o.Add_Completed({
            try {
                $SloganText.Text = $script:SlNext
                $eo = New-Object Windows.Media.Animation.CubicEase; $eo.EasingMode = 'EaseOut'
                $SloganText.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Anim4 0 1 340 0 $eo))
                $SloganText.RenderTransform.BeginAnimation([Windows.Media.TranslateTransform]::YProperty, (New-Anim4 9 0 400 0 $eo))
            } catch { $SloganText.Text = $script:SlNext; $SloganText.BeginAnimation([Windows.UIElement]::OpacityProperty, $null); $SloganText.Opacity = 1 }
        })
        $SloganText.BeginAnimation([Windows.UIElement]::OpacityProperty, $o)
        $SloganText.RenderTransform.BeginAnimation([Windows.Media.TranslateTransform]::YProperty, (New-Anim4 ([double]::NaN) -7 200 0 $ei))
    } catch { $SloganText.Text = $txt }
}

# красивая смена стратегии: «хлопок» шара, волна от кольца, текст выезжает справа
function Play-SwitchAnim {
    if ($Cfg.Perf -or $script:GameActive -or -not $Win.IsVisible -or $Win.WindowState -eq 'Minimized') { return }
    try {
        $ce = New-Object Windows.Media.Animation.CubicEase; $ce.EasingMode = 'EaseOut'
        $be = New-Object Windows.Media.Animation.BackEase; $be.EasingMode = 'EaseOut'; $be.Amplitude = 0.8
        $mk = {
            param([double]$from, [double]$to, [int]$ms, $ease)
            $a = New-Object Windows.Media.Animation.DoubleAnimation; $a.From = $from; $a.To = $to
            $a.Duration = New-Object Windows.Duration -ArgumentList ([TimeSpan]::FromMilliseconds($ms))
            if ($ease) { $a.EasingFunction = $ease }
            $a.FillBehavior = [Windows.Media.Animation.FillBehavior]::Stop
            $a
        }
        $sx = [Windows.Media.ScaleTransform]::ScaleXProperty; $sy = [Windows.Media.ScaleTransform]::ScaleYProperty
        $op = [Windows.UIElement]::OpacityProperty
        if ($OrbScale) { $OrbScale.BeginAnimation($sx, (& $mk 0.74 1 560 $be)); $OrbScale.BeginAnimation($sy, (& $mk 0.74 1 560 $be)) }
        if ($GlyphScale) { $GlyphScale.BeginAnimation($sx, (& $mk 0.4 1 650 $be)); $GlyphScale.BeginAnimation($sy, (& $mk 0.4 1 650 $be)) }
        if ($WaveScale -and $RingWave) {
            $WaveScale.BeginAnimation($sx, (& $mk 0.95 1.8 850 $ce)); $WaveScale.BeginAnimation($sy, (& $mk 0.95 1.8 850 $ce))
            $RingWave.BeginAnimation($op, (& $mk 0.9 0 850 $ce))
        }
        if ($StratMove) {
            $StratMove.BeginAnimation([Windows.Media.TranslateTransform]::XProperty, (& $mk 40 0 480 $ce))
            $StrategyText.BeginAnimation($op, (& $mk 0 1 420 $ce))
        }
        $StatusText.BeginAnimation($op, (& $mk 0.35 1 380 $ce))
        Set-Slogan $true
    } catch { }
}

# ---------------------------------------------------------------- пинг и скорость (кнопка на главной)
$script:PingRun = $null
$script:SpeedUrls = @('https://speed.cloudflare.com/__down?bytes=10000000', 'https://proof.ovh.net/files/10Mb.dat')
function Start-SpeedStep($p) {
    $c = New-Object System.Net.Http.HttpClient
    $c.Timeout = [TimeSpan]::FromSeconds(20)
    try { $c.DefaultRequestHeaders.UserAgent.ParseAdd('Mozilla/5.0 (Windows NT 10.0; Win64; x64)') } catch { }
    $p.SClient = $c
    $p.STask = [ZProbe]::Speed($c, $script:SpeedUrls[$p.UrlIdx], 10000000, 8000)
    $p.Until = (Get-Date).AddSeconds(16)
}
function Finish-PingRun($p, [string]$speedLine) {
    $script:PingRun = $null; $script:PingTimer.Stop()
    if ($p.Cl) { try { $p.Cl.Dispose() } catch { } }
    if ($p.SClient) { try { $p.SClient.Dispose() } catch { } }
    if ($script:Running) {
        if ($script:Active) { $mode = 'со стратегией «' + (Disp $script:Active) + '»' } else { $mode = 'с обходом' }
    } else { $mode = 'без обхода' }
    $tail = ''; if ($speedLine) { $tail = ' · ' + $speedLine }
    $LiveText.Text = ('● Пинг {0:HH:mm:ss} ({1}): {2}{3}' -f (Get-Date), $mode, $p.PingLine, $tail); $LiveText.Visibility = 'Visible'; $script:PingManual = -not $script:Running; try { Pretty-Ping $LiveText } catch { }
    if (([string]$MonText.Text).StartsWith('Пинг')) { $MonText.Text = '' }
    $pb = $p.Best; if ($null -eq $pb) { $pb = 1e9 }
    try { if ($pb -lt 90) { $LiveText.Foreground = New-Brush (ToColor '#22C55E') } elseif ($pb -lt 160) { $LiveText.Foreground = New-Brush (ToColor '#F59E0B') } elseif ($pb -lt 100000) { $LiveText.Foreground = New-Brush (ToColor '#EF4444') } } catch { }
    $BtnPing.IsEnabled = $true
    $lt = ''; if ($speedLine) { $lt = ' | ' + $speedLine }
    Log ('Пинг, ' + $mode + ': ' + ($p.PingLine) + $lt)
}
$script:PingTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:PingTimer.Interval = [TimeSpan]::FromMilliseconds(250)
$script:PingTimer.Add_Tick({
    $p = $script:PingRun
    if (-not $p) { $script:PingTimer.Stop(); return }
    try {
        if ($p.Phase -eq 'ping') {
            $done = @($p.Tasks | Where-Object { $_.Task.IsCompleted }).Count
            if ($done -lt $p.Tasks.Count -and (Get-Date) -lt $p.Until) { return }
            $parts = @()
            foreach ($s in $p.Svcs) {
                $wl = @(); $ol = @()
                foreach ($pt in @($p.Tasks | Where-Object { $_.Svc -eq $s.Key })) { if ($pt.Task.Status -eq 'RanToCompletion') { try { $rr = $pt.Task.Result; $ol += [double]$rr[0]; $wl += [double]$rr[1] } catch { } } }
                if ($wl.Count -gt 0) {
                    $wm = [int]($wl | Measure-Object -Minimum).Minimum; $om = [int]($ol | Measure-Object -Minimum).Minimum
                    $parts += ('{0} {1} мс (открытие {2})' -f $s.Name, $wm, $om)
                    if ($wm -lt $p.Best) { $p.Best = $wm }
                } else { $parts += ('{0} — нет ответа' -f $s.Name) }
            }
            $p.PingLine = ($parts -join ' · ')
            try { $p.Cl.Dispose() } catch { }; $p.Cl = $null
            if ($p.NoSpeed -or -not $Cfg.PingSpeed) { Finish-PingRun $p ''; return }
            $LiveText.Text = ('● Пинг: {0} · меряю скорость (до 8 сек)…' -f $p.PingLine); $LiveText.Visibility = 'Visible'; try { Pretty-Ping $LiveText } catch { }
            $p.Phase = 'speed'; $p.UrlIdx = 0
            Start-SpeedStep $p
            return
        }
        if ($p.Phase -eq 'speed') {
            if (-not $p.STask.IsCompleted -and (Get-Date) -lt $p.Until) { return }
            $bytes = 0.0; $dl = 0.0
            if ($p.STask.Status -eq 'RanToCompletion') { $r = $p.STask.Result; $bytes = [double]$r[0]; $dl = [double]$r[1] }
            try { $p.SClient.Dispose() } catch { }; $p.SClient = $null
            if ($bytes -ge 200000 -and $dl -gt 0) {
                $mbit = $bytes * 8.0 / ($dl / 1000.0) / 1000000.0
                if ($mbit -ge 10) { $f = '{0:N0}' } else { $f = '{0:N1}' }
                Finish-PingRun $p (('Скорость скачивания: ' + $f + ' Мбит/с') -f $mbit)
                return
            }
            if ($p.UrlIdx + 1 -lt $script:SpeedUrls.Count) {
                $p.UrlIdx++; Start-SpeedStep $p; return
            }
            Finish-PingRun $p 'Скорость измерить не удалось (серверы теста не ответили)'
        }
    } catch {
        $em = $_.Exception.Message
        try { Finish-PingRun $p ('Ошибка проверки: ' + $em) } catch { $script:PingRun = $null; $script:PingTimer.Stop(); $BtnPing.IsEnabled = $true }
    }
})
function Start-PingRun([switch]$NoSpeed) {
    if ($script:PingRun) { return }
    if ($script:Testing) { Log 'Пинг: сейчас идёт подбор стратегий, дождитесь конца'; return }
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $c = New-Object System.Net.Http.HttpClient
    $c.Timeout = [TimeSpan]::FromSeconds(6)
    try { $c.DefaultRequestHeaders.UserAgent.ParseAdd('Mozilla/5.0 (Windows NT 10.0; Win64; x64)') } catch { }
    $tasks = @()
    $psvcs = @(Get-MonSvcs | Select-Object -First 3)
    foreach ($s in $psvcs) {
        foreach ($u in @($s.Urls | Select-Object -First 2)) { $tasks += @{ Svc = $s.Key; Task = [ZProbe]::Warm($c, $u) } }
    }
    $script:PingRun = @{ Phase = 'ping'; Cl = $c; Tasks = $tasks; Svcs = $psvcs; Until = (Get-Date).AddSeconds(10); PingLine = ''; Best = 1e9; UrlIdx = 0; NoSpeed = [bool]$NoSpeed; SClient = $null; STask = $null }
    $LiveText.Text = '● Пинг: проверяю время ответа сервисов…'; $LiveText.Visibility = 'Visible'; $LiveText.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
    $BtnPing.IsEnabled = $false
    $script:PingTimer.Start()
}

function Get-RankedNames {
    $r = @()
    foreach ($k in $Results.Keys) { if ($Results[$k] -match '^(\d+)%') { $r += [pscustomobject]@{ N = $k; P = [int]$Matches[1] } } }
    @($r | Sort-Object @{ Expression = { -$_.P } }, @{ Expression = { Get-ResMs $_.N } }, @{ Expression = { Sort-Key $_.N } } | ForEach-Object { $_.N })
}

function Update-TrayText {
    if (-not $script:Tray) { return }
    if ($script:Alert) { $t = 'Zapret Studio — СБОЙ: ' + $script:Alert.Title }
    elseif ($script:Running) { $t = 'Zapret Studio — активно'; try { $dn = Disp ([string]$Cfg.Last); if ($dn) { $t = 'Zapret Studio · ' + $dn }; if ($script:PingHist -and $script:PingHist.Count -gt 0) { $t += (' · ' + $script:PingHist[$script:PingHist.Count - 1] + ' мс') } } catch { } }
    else { $t = 'Zapret Studio — выключено' }
    if ($t.Length -gt 62) { $t = $t.Substring(0, 62) }
    $script:Tray.Text = $t
}

function Balloon([string]$title, [string]$text, $icon) {
    if ($script:GameActive) { return }   # геймрежим: ничего не вылезает поверх игры
    try { $script:Tray.ShowBalloonTip(8000, $title, $text, $icon) } catch { }
}

function Set-Alert([string]$title, [string[]]$lines) {
    $new = (-not $script:Alert) -or ($script:Alert.Title -ne $title)
    $fix = ''; if ($script:Alert) { $fix = $script:Alert.Fix }
    $script:Alert = @{ Title = $title; Lines = @($lines); Fix = $fix; Time = Get-Date }
    if ($new) {
        Log ('ПРОБЛЕМА: ' + $title)
        if ($Cfg.Sound -and -not $script:GameActive) { try { [System.Media.SystemSounds]::Hand.Play() } catch { } }
        foreach ($l in $lines) { Log ('   ' + $l) }
        $first = ''; if ($lines.Count -gt 0) { $first = $lines[0] }
        Balloon 'Zapret Studio: сбой' ($title + "`n" + $first) ([Windows.Forms.ToolTipIcon]::Error)
    }
    Render-State
}

function Clear-Alert([switch]$Recovered) {
    if (-not $script:Alert) { return }
    $script:Alert = $null; $script:FixTried = @(); $script:MonConfirm = $false
    if ($Recovered) {
        Log 'Связь восстановлена'
        if ($Cfg.Sound -and -not $script:GameActive) { try { [System.Media.SystemSounds]::Asterisk.Play() } catch { } }
        Balloon 'Zapret Studio' 'Связь восстановлена, всё работает.' ([Windows.Forms.ToolTipIcon]::Info)
    }
    Render-State
}

# кандидаты для автовосстановления: сначала лучшие по результатам подбора, потом избранные, потом ещё не проверявшиеся (0% пропускаем)
function Get-FixCandidates {
    $r = @(Get-RankedNames | Where-Object { (Get-Pct $_) -gt 0 })
    $fav = @($script:Strategies | Where-Object { (@($Cfg.Favorites) -contains $_.Name) -and ((Get-Pct $_.Name) -ne 0) } | ForEach-Object { $_.Name })
    $rest = @($script:Strategies | Sort-Object @{ Expression = { Sort-Key $_.Name } } | Where-Object { (Get-Pct $_.Name) -lt 0 } | ForEach-Object { $_.Name })
    @($r + $fav + $rest | Select-Object -Unique)
}

$script:FixStarted = $false
# память о сбоях: стратегия, которая ломалась недавно, не получает повторный перезапуск, а сразу уступает следующей
$script:FixHist = @{}
$script:LastAutoSearch = [datetime]::MinValue
$script:AutoSearchRun = $false
function Test-RecentFail([string]$n) {
    if (-not $n) { return $false }
    $t = $script:FixHist[$n]
    return [bool]($t -and ((Get-Date) - $t).TotalMinutes -lt $(if ($Cfg.ExpInstant) { 10 } else { 30 }))
}
# готовые варианты кончились: запускаем срочный подбор (подключит первую стратегию, которая открывает всё)
function Start-AutoSearch {
    if ($script:Testing) { return $false }
    $gap = 10; if ($Cfg.ExpInstant) { $gap = 3 }
    if (((Get-Date) - $script:LastAutoSearch).TotalMinutes -lt $gap) { return $false }
    $script:LastAutoSearch = Get-Date
    $script:ModeOv = 'urgent'; $script:AutoSearchRun = $true
    Log 'Автовосстановление: готовые варианты кончились, запускаю срочный подбор…'
    try { Start-Test } catch { Log ('Не удалось запустить подбор: ' + $_.Exception.Message) }
    if (-not $script:Testing) { $script:AutoSearchRun = $false; $script:ModeOv = $null }
    return [bool]$script:Testing
}
function Do-AutoFix {
    if ($script:Testing) { return }
    $script:FixStarted = $false
    $cur = $script:LastStrategy
    $next = $null
    # первый сбой стратегии: пробуем просто перезапустить её; повторный (в т.ч. после «восстановления») - сразу следующая
    if ($cur -and -not $Cfg.ExpInstant -and ($script:FixTried -notcontains $cur) -and -not (Test-RecentFail $cur)) { $next = $cur }
    if ($cur) { $script:FixHist[$cur] = Get-Date }
    if (-not $next) {
        $have = @($script:Strategies | ForEach-Object { $_.Name })
        $c = @(Get-FixCandidates | Where-Object { ($script:FixTried -notcontains $_) -and ($_ -ne $cur) -and ($have -contains $_) })
        $next = @($c | Where-Object { -not (Test-RecentFail $_) }) | Select-Object -First 1
        if (-not $next) {
            if (Start-AutoSearch) {
                $script:FixStarted = $true
                if ($script:Alert) { $script:Alert.Fix = 'Идёт срочный подбор рабочей стратегии…' }
                Render-State; return
            }
        }
    }
    if (-not $next) {
        $msg = 'Автовосстановление не помогло: подходящих стратегий больше нет. Повторю попытку позже, либо запустите «Подбор» вручную.'
        if ($script:Alert -and $script:Alert.Fix -ne $msg) { Log $msg }
        if ($script:Alert) { $script:Alert.Fix = $msg }
        $script:NextCheck = (Get-Date).AddMinutes(2)
        Render-State; return
    }
    $script:FixTried += $next
    $script:FixStarted = $true
    if ($next -eq $cur) { $msg = "Автовосстановление: перезапускаю «$(Disp $next)»…" } else { $msg = "Автовосстановление: переключаюсь на «$(Disp $next)»…" }
    Log $msg
    if ($script:Alert) { $script:Alert.Fix = $msg }
    $script:Selected = $next
    Start-Strategy $next -Auto
    $script:NextCheck = (Get-Date).AddSeconds($(if ($Cfg.ExpInstant) { 7 } else { 14 }))
}

function Start-MonCheck {
    if ($script:Mon -or $script:Testing) { return }
    $svcs = @(Get-MonSvcs)
    if ($svcs.Count -eq 0) { return }
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $c = New-Object System.Net.Http.HttpClient
    $c.Timeout = [TimeSpan]::FromSeconds($(if ($Cfg.ExpInstant) { 4 } else { 6 }))
    try { $c.DefaultRequestHeaders.UserAgent.ParseAdd('Mozilla/5.0 (Windows NT 10.0; Win64; x64)') } catch { }
    $tasks = @()
    foreach ($s in $svcs) {
        foreach ($u in $s.Urls) { $tasks += @{ Svc = $s.Key; Url = $u; Task = [ZProbe]::Timed($c, $u) } }
    }
    $tasks += @{ Svc = '_ctl'; Url = $script:CtlUrl; Task = [ZProbe]::Timed($c, $script:CtlUrl) }
    if ($Cfg.ExpThrottle -and ($script:MonConfirm -or ((Get-Date) - $script:LastThr).TotalSeconds -ge 55)) {
        $script:LastThr = Get-Date
        foreach ($s in $svcs) { $du = $script:ThrUrls[$s.Key]; if ($du) { $tasks += @{ Svc = '_dl'; Key = $s.Key; Name = $s.Name; Url = $du; Task = [ZProbe]::Stall($c, $du, 65536, 4500) } } }
    }
    $script:Mon = @{ Client = $c; Tasks = $tasks; Svcs = $svcs; Until = (Get-Date).AddSeconds($(if ($Cfg.ExpInstant) { 5 } else { 8 })) }
    $script:NextCheck = $null
    $MonText.Text = 'Проверяю связь…'
}

function Finish-MonCheck {
    $m = $script:Mon; $script:Mon = $null
    if ($script:Testing) { try { $m.Client.Dispose() } catch { }; return }
    $now = Get-Date
    $interval = [Math]::Max(1, [Math]::Min(5, [int]$Cfg.MonitorMin))
    $ctl = $m.Tasks | Where-Object { $_.Svc -eq '_ctl' } | Select-Object -First 1
    $ctlOk = $ctl.Task.Status -eq 'RanToCompletion'
    $bad = @(); $total = 0; $totalOk = 0
    foreach ($s in $m.Svcs) {
        $mine = @($m.Tasks | Where-Object { $_.Svc -eq $s.Key })
        $okc = @($mine | Where-Object { $_.Task.Status -eq 'RanToCompletion' }).Count
        $total += $mine.Count; $totalOk += $okc
        if ($okc * 2 -lt $mine.Count) {
            $why = @()
            foreach ($t in $mine) { if ($t.Task.Status -ne 'RanToCompletion') { $why += ([Uri]$t.Url).Host + ': ' + (Get-FailReason $t.Task) } }
            $bad += @{ Name = $s.Name; Why = $why; Ok = $okc; Count = $mine.Count }
        }
    }
    if ($ctlOk) {
        foreach ($t in @($m.Tasks | Where-Object { $_.Svc -eq '_dl' })) {
            if ($t.Task.Status -ne 'RanToCompletion') { continue }
            $r = $t.Task.Result
            if ([double]$r[2] -ge 0 -and [double]$r[3] -eq 0 -and [double]$r[0] -lt 30000 -and [double]$r[1] -ge 4200) {
                $kb = [double]$r[0] / 1024
                if (@($bad | Where-Object { $_.Name -eq $t.Name }).Count -eq 0) { $bad += @{ Name = $t.Name; Why = @(([Uri]$t.Url).Host + (': данные встали на {0:N0} КБ' -f $kb)); Ok = 0; Count = 1; Thr = $true } }
                Log ('Анти-душилка: ' + $t.Name + (' отвечает, но данные застряли на {0:N0} КБ (похоже на блокировку ТСПУ)' -f $kb))
            }
        }
    }
    $pingStr = Get-PingLine $m.Tasks $m.Svcs 2
    try { $m.Client.Dispose() } catch { }

    if (-not $ctlOk -and $totalOk -eq 0) {
        $MonText.Text = ('{0:HH:mm} · нет интернета, проверка пропущена' -f $now)
        $script:NextCheck = $now.AddMinutes(1); return
    }
    if ($bad.Count -eq 0) {
        $nextTxt = ('{0} мин' -f $interval); if ($Cfg.ExpInstant) { $nextTxt = '20 сек' }
        $MonText.Text = ('Связь проверена в {0:HH:mm} · всё открывается · следующая через {1}' -f $now, $nextTxt)
        $wasAlert = [bool]$script:Alert
        $script:MonConfirm = $false
        if ($wasAlert) { Clear-Alert -Recovered }
        if ($Cfg.ExpInstant) { $script:NextCheck = $now.AddSeconds(20) } else { $script:NextCheck = $now.AddMinutes($interval) }; return
    }
    $names = ($bad | ForEach-Object { $_.Name }) -join ', '
    if (-not $script:MonConfirm -and -not $script:Alert) {
        $script:MonConfirm = $true
        $MonText.Text = ('{0:HH:mm} · {1} не отвечает, перепроверяю…' -f $now, $names)
        $rc = 15; if ($Cfg.ExpInstant) { $rc = 3 }
        Log ('Проверка: не отвечает ' + $names + (', перепроверю через {0} сек' -f $rc))
        $script:NextCheck = $now.AddSeconds($rc); return
    }
    $lines = @()
    foreach ($b in $bad) {
        if ($b.Thr) { $lines += ('{0}: открывается, но данные режут (душат)' -f $b.Name) } else { $lines += ('{0}: открылось {1} из {2}' -f $b.Name, $b.Ok, $b.Count) }
        foreach ($w in ($b.Why | Select-Object -First 3)) { $lines += ('   ' + $w) }
    }
    if ($script:LastStrategy) { $lines += ('Стратегия «{0}» перестала помогать. Перезапустите её или запустите «Подбор».' -f (Disp $script:LastStrategy)) }
    $MonText.Text = ('{0:HH:mm} · сбой: {1}' -f $now, $names)
    Set-Alert ('не открывается ' + $names) $lines
    if ($Cfg.AutoFix -or $Cfg.ExpInstant) { Do-AutoFix }
    elseif ($Cfg.KeepAlive -and $script:KeepArmed -and $script:LastStrategy -and ($script:FixTried -notcontains $script:LastStrategy)) { Do-AutoFix }
    else { $script:NextCheck = $now.AddMinutes([Math]::Min(1, $interval)) }
}

function Poll-Mon {
    $m = $script:Mon; if (-not $m) { return }
    $done = @($m.Tasks | Where-Object { $_.Task.IsCompleted }).Count
    if ($done -ge $m.Tasks.Count -or (Get-Date) -ge $m.Until) { Finish-MonCheck }
}

$script:KeepStamps = @(); $script:KeepDone = $false; $script:KeepArmed = $false; $script:KeepGoodName = $null
$script:KeepRetryAt = $null; $script:RestartAt = $null; $script:RestartWhy = ''; $script:NetSig = $null; $script:LastTick = $null
$script:LastNetRestart = [datetime]::MinValue; $script:TickN = 0

function Get-NetSig {
    try {
        $r = foreach ($n in [Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
            if ($n.OperationalStatus -ne 'Up' -or $n.NetworkInterfaceType -eq 'Loopback' -or $n.NetworkInterfaceType -eq 'Tunnel') { continue }
            $ips = @($n.GetIPProperties().UnicastAddresses | Where-Object { $_.Address.AddressFamily -eq 'InterNetwork' } | ForEach-Object { $_.Address.ToString() })
            if ($ips.Count -gt 0) { $n.Id + ':' + ($ips -join ',') }
        }
        return ((@($r) | Sort-Object) -join ';')
    } catch { return '' }
}

# Обход оборвался сам: запускаем заново. После 2-й попытки подряд ещё и сбрасываем драйвер WinDivert.
# Если попыток слишком много, не сдаёмся, а пробуем раз в минуту.
function Try-KeepAlive {
    $script:KeepDone = $false
    if (-not $Cfg.KeepAlive -or -not $script:KeepArmed -or $script:Testing -or $script:Quitting -or -not $script:LastStrategy) { return }
    $now = Get-Date
    $script:KeepStamps = @($script:KeepStamps | Where-Object { ($now - $_).TotalMinutes -lt 10 })
    if ($script:KeepStamps.Count -ge 5) {
        if (-not $script:KeepRetryAt) { Log 'Обход закрывается слишком часто. Не сдаюсь: пробую снова раз в минуту со сбросом WinDivert.' }
        $script:KeepRetryAt = $now.AddSeconds(60)
        return
    }
    # эта стратегия уже получила перезапуски, но не держится: если включено автовосстановление, переходим на другую
    if ($script:KeepStamps.Count -ge 2 -and $Cfg.AutoFix) {
        Log ('«{0}» не держится после перезапусков. Ищу другую рабочую стратегию…' -f (Disp $script:LastStrategy))
        Set-Alert 'обход остановился' @('Процесс winws закрывается сам даже после перезапусков. Пробую другие стратегии.')
        Do-AutoFix
        if ($script:FixStarted) { $script:KeepStamps = @(); $script:MonConfirm = $true; $script:KeepDone = $true; return }
        $script:KeepRetryAt = $now.AddSeconds(60)
        return
    }
    $script:KeepStamps += $now
    if ($script:FixTried -notcontains $script:LastStrategy) { $script:FixTried += $script:LastStrategy }
    if ($script:KeepStamps.Count -ge 2) { Stop-Zapret -Full }
    Log ('Обход оборвался. Запускаю «{0}» снова ({1}/5)…' -f (Disp $script:LastStrategy), $script:KeepStamps.Count)
    $script:KeepDone = $true
    Start-Strategy $script:LastStrategy -Auto
    # если после перезапуска связь не появилась, первая же проверка сразу включит автовосстановление
    $script:MonConfirm = $true
}

# Вызывается раз в секунду из таймера статуса: сон, смена сети, повторные попытки.
function Watch-Resilience {
    $now = Get-Date
    $armed = ($Cfg.KeepAlive -and $script:KeepArmed -and -not $script:Testing -and -not $script:Quitting -and $script:LastStrategy)
    # 1) компьютер проснулся (или интерфейс надолго завис): между тиками пауза, которой не бывает при нормальной работе
    if ($script:LastTick -and ($now - $script:LastTick).TotalSeconds -gt 25) {
        if ($armed -and $script:Running) { $script:RestartAt = $now.AddSeconds(6); $script:RestartWhy = 'компьютер проснулся' }
    }
    $script:LastTick = $now
    # 2) смена сети (Wi-Fi, кабель, VPN): проверяем раз в 5 секунд
    $script:TickN++
    if (($script:TickN % 5) -eq 0) {
        $sig = Get-NetSig
        if ($null -eq $script:NetSig) { $script:NetSig = $sig }
        elseif ($sig -ne $script:NetSig) {
            $script:NetSig = $sig
            if ($armed -and $script:Running -and $sig -and ($now - $script:LastNetRestart).TotalSeconds -gt 30) {
                $script:RestartAt = $now.AddSeconds(5); $script:RestartWhy = 'сеть изменилась'
            }
        }
    }
    # 3) отложенный перезапуск
    if ($script:RestartAt -and $now -ge $script:RestartAt) {
        $script:RestartAt = $null
        if ($armed -and $script:Running) {
            $script:LastNetRestart = $now
            Log ('Обновляю обход ({0}): «{1}»' -f $script:RestartWhy, (Disp $script:LastStrategy))
            Start-Strategy $script:LastStrategy -Auto
        }
    }
    # 4) повторные попытки, если запуск не удался
    if ($script:KeepRetryAt -and $now -ge $script:KeepRetryAt -and -not $script:Running -and -not $script:Starting) {
        $script:KeepRetryAt = $null
        if ($armed -and $script:KeepGoodName -eq $script:LastStrategy) {
            Log ('Повторная попытка запуска «{0}» со сбросом WinDivert…' -f (Disp $script:LastStrategy))
            Stop-Zapret -Full
            $script:KeepRetryAt = (Get-Date).AddSeconds(60)
            $script:FixStarted = $false
            if ($Cfg.AutoFix) { Do-AutoFix }
            if (-not $script:FixStarted) { $script:FixTried = @($script:LastStrategy); Start-Strategy $script:LastStrategy -Auto }
        }
    }
    # 5) долго работает стабильно: обнуляем счётчик аварий
    if ($script:Running -and $script:StartedAt -and ($script:KeepStamps.Count -gt 0 -or ($script:FixTried.Count -gt 0 -and -not $script:Alert)) -and ($now - $script:StartedAt).TotalMinutes -ge 15) { $script:KeepStamps = @(); if (-not $script:Alert) { $script:FixTried = @() } }
}

function Check-Now {
    if (-not $script:Running) { Log 'Обход не запущен: проверять нечего'; return }
    if ($script:Testing) { Log 'Идёт подбор: проверка связи подождёт'; return }
    $script:MonConfirm = $true
    Start-MonCheck
}

