# ---------------------------------------------------------------- инструкция
# ---------------------------------------------------------------- геймрежим (эксперимент)
# Сборка 14: при включённом геймрежиме все игры идут напрямую (Game Filter выключен, см. Test-GameDirect); тут — приоритеты, анимации и всплывашки.
$script:GameProcs = [ordered]@{
    'cs2' = 'CS2'; 'dota2' = 'Dota 2'; 'VALORANT-Win64-Shipping' = 'Valorant'
    'r5apex' = 'Apex Legends'; 'r5apex_dx12' = 'Apex Legends'; 'FortniteClient-Win64-Shipping' = 'Fortnite'; 'GTA5' = 'GTA V'; 'GTA5_Enhanced' = 'GTA V'
    'RustClient' = 'Rust'; 'EscapeFromTarkov' = 'Tarkov'; 'League of Legends' = 'League of Legends'; 'destiny2' = 'Destiny 2'; 'Overwatch' = 'Overwatch 2'
    'TslGame' = 'PUBG'; 'Marvel-Win64-Shipping' = 'Marvel Rivals'; 'deadlock' = 'Deadlock'; 'PathOfExile' = 'Path of Exile'; 'PathOfExileSteam' = 'Path of Exile'
    'PathOfExile_x64Steam' = 'Path of Exile'; 'eldenring' = 'Elden Ring'; 'Minecraft.Windows' = 'Minecraft'; 'RobloxPlayerBeta' = 'Roblox'
}
function Get-RunningGame {
    $names = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($p in [Diagnostics.Process]::GetProcesses()) { try { [void]$names.Add($p.ProcessName) } catch { }; try { $p.Dispose() } catch { } }
    foreach ($k in $script:GameProcs.Keys) { if ($names.Contains($k)) { return $k } }
    return ''
}
function Set-WinwsPrio([string]$cls) {
    foreach ($p in [Diagnostics.Process]::GetProcessesByName('winws')) {
        try { if ([string]$p.PriorityClass -ne $cls) { $p.PriorityClass = $cls } } catch { }
        try { $p.Dispose() } catch { }
    }
}
function Update-GameState {
    if (-not $GameState) { return }
    if (-not $Cfg.ExpGame) { $GameState.Text = 'Сейчас: выключен' }
    elseif ($script:GameActive) { $GameState.Text = ('Сейчас: вы в игре ({0}) — геймрежим работает' -f $script:GameProcs[$script:GameName]) }
    else { $GameState.Text = 'Сейчас: включён, жду запуска игры' }
}
function Update-GameMode([switch]$Force) {
    $was = [bool]$script:GameActive
    $g = ''; if ($Cfg.ExpGame) { $g = Get-RunningGame }
    $script:GameActive = [bool]$g; $script:GameName = $g
    if ($Cfg.ExpGame) { if ($script:GameActive -or $Cfg.Boost) { Set-WinwsPrio 'High' } else { Set-WinwsPrio 'AboveNormal' } }
    elseif ($Cfg.Boost) { Set-WinwsPrio 'High' }
    elseif ($Force -or $was) { Set-WinwsPrio 'AboveNormal' }
    if ($Force -or $was -ne $script:GameActive) {
        try { $me = [Diagnostics.Process]::GetCurrentProcess(); if ($script:GameActive) { $me.PriorityClass = 'BelowNormal' } else { $me.PriorityClass = 'Normal' } } catch { }
        if ($script:GameActive -and -not $was) { Log ('Геймрежим: вижу игру ' + $script:GameProcs[$g] + '. winws без очереди, анимации и всплывашки на паузе') }
        elseif ($was -and -not $script:GameActive) { Log 'Геймрежим: игра закрыта, всё как обычно' }
        try { Set-Pulse $script:WantPulse } catch { }; try { Bg-Idle } catch { }
    }
    Update-GameState
}

# ---------------------------------------------------------------- тексты экспериментов
function Find-RowStack([string]$h) {
    # сборка 10: ищет карточку настройки по названию, чтобы описание жило прямо в ней, а не внизу раздела
    $h = ([string]$h).Trim().ToLowerInvariant(); if (-not $h) { return $null }
    foreach ($tn in @($script:ToggleNames)) {
        $cb = $null; try { $cb = $Win.FindName($tn) } catch { }
        if (-not $cb -or -not ($cb.Parent -is [Windows.Controls.Grid])) { continue }
        $sp = $cb.Parent.Children[0]
        if (-not ($sp -is [Windows.Controls.StackPanel]) -or $sp.Children.Count -eq 0 -or -not ($sp.Children[0] -is [Windows.Controls.TextBlock])) { continue }
        $t = ([string]$sp.Children[0].Text).Trim().ToLowerInvariant()
        if ($t -eq $h -or $t.StartsWith($h + ' ') -or $t.StartsWith($h + ' (') -or $h.StartsWith($t + ' ')) { return $sp }
    }
    $null
}
function Add-RowDetail($sp, [string]$text) {
    $text = $text.Replace([string][char]0x00B6, "`n")
    foreach ($ch in @($sp.Children)) { if ($ch -is [Windows.Controls.TextBlock] -and [string]$ch.Tag -eq 'zs-det') { $ch.Text = $text; return } }
    $lnk = New-Object Windows.Controls.TextBlock
    $lnk.Text = 'Подробнее ▾'; $lnk.FontSize = 11; $lnk.Margin = New-Object Windows.Thickness 0, 5, 0, 0
    $lnk.HorizontalAlignment = 'Left'; $lnk.Cursor = [Windows.Input.Cursors]::Hand; $lnk.Opacity = 0.75
    $lnk.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'AccentBrush')
    $det = New-Object Windows.Controls.TextBlock
    $det.Tag = 'zs-det'; $det.Text = $text; $det.TextWrapping = 'Wrap'; $det.Visibility = 'Collapsed'
    $det.Margin = New-Object Windows.Thickness 0, 6, 0, 2
    $det.SetResourceReference([Windows.Controls.TextBlock]::FontSizeProperty, 'Fs11')
    $det.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
    $lnk.Tag = $det
    $lnk.Add_MouseEnter({ param($s, $e) $s.Opacity = 1 })
    $lnk.Add_MouseLeave({ param($s, $e) $s.Opacity = 0.75 })
    $lnk.Add_MouseLeftButtonDown({ param($s, $e) $e.Handled = $true })
    $lnk.Add_MouseLeftButtonUp({
        param($s, $e)
        $e.Handled = $true
        $d = $s.Tag
        if ([string]$d.Visibility -eq 'Visible') { $d.Visibility = 'Collapsed'; $s.Text = 'Подробнее ▾' }
        else {
            $d.Visibility = 'Visible'; $s.Text = 'Свернуть ▴'
            if (-not $Cfg.Perf) { $a = New-Object Windows.Media.Animation.DoubleAnimation 0.0, 1.0, (New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(220))); $d.BeginAnimation([Windows.UIElement]::OpacityProperty, $a) }
        }
    })
    $det.Add_MouseLeftButtonDown({ param($s, $e) $e.Handled = $true })
    $det.Add_MouseLeftButtonUp({ param($s, $e) $e.Handled = $true })
    [void]$sp.Children.Add($lnk); [void]$sp.Children.Add($det)
}
# сборка 12: строки описания, не нашедшие свою карточку, уходят в «Подробнее» своей настройки
$script:HelpOwnerMap = @{ InstantHelp = 'ChkInstant'; TurboHelp = 'ChkTurbo' }
function Get-HelpOwnerSp($panel) {
    $tn = $script:HelpOwnerMap[[string]$panel.Name]
    if (-not $tn) { return $null }
    $cb = $Win.FindName($tn)
    if (-not $cb -or -not ($cb.Parent -is [Windows.Controls.Grid])) { return $null }
    $sp = $cb.Parent.Children[0]
    if ($sp -is [Windows.Controls.StackPanel]) { return $sp }
    $null
}
function Add-HelpLines($panel, [string[]]$lines) {
    $panel.Children.Clear()
    $extra = @(); $osp = $null; try { $osp = Get-HelpOwnerSp $panel } catch { }
    foreach ($l in $lines) {
        $i = $l.IndexOf('|')
        $hd = $l.Substring(0, $i); $body = $l.Substring($i + 1)
        $sp = $null; try { $sp = Find-RowStack $hd } catch { }
        if ($sp) { Add-RowDetail $sp $body; continue }
        if ($osp) { $extra += ($hd + ': ' + $body); continue }
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.TextWrapping = 'Wrap'
        $tb.SetResourceReference([Windows.Controls.TextBlock]::FontSizeProperty, 'Fs11')
        $r1 = New-Object System.Windows.Documents.Run ($hd)
        $r1.FontWeight = 'SemiBold'
        $r2 = New-Object System.Windows.Documents.Run ($body)
        $r2.SetResourceReference([Windows.Documents.TextElement]::ForegroundProperty, 'SubBrush')
        [void]$tb.Inlines.Add($r1)
        [void]$tb.Inlines.Add((New-Object System.Windows.Documents.LineBreak))
        [void]$tb.Inlines.Add($r2)
        $tb.Margin = New-Object System.Windows.Thickness 0, 0, 0, 8
        [void]$panel.Children.Add($tb)
    }
    if ($osp -and $extra.Count -gt 0) {
        $base = ''; try { $tn = $script:HelpOwnerMap[[string]$panel.Name]; if ($script:DetailText -and $script:DetailText[$tn]) { $base = [string]$script:DetailText[$tn] } } catch { }
        $parts = @(); if ($base) { $parts += $base }; foreach ($x in $extra) { $parts += ([string][char]0x2022 + ' ' + $x) }
        Add-RowDetail $osp ($parts -join ([string][char]0x00B6))
    }
    if ($panel.Children.Count -eq 0) { $panel.Visibility = 'Collapsed' } else { $panel.Visibility = 'Visible' }
}
function Build-ExpHelp {
    Add-HelpLines $TurboHelp @(
        'Как работает|Сначала проверяет стратегии, которые раньше показали себя лучше всех. Все сервисы и все их адреса проверяются одновременно, прогрев winws 0.7 с вместо 1.5, таймаут 3 с вместо 5. Если провайдер сбросил хоть один адрес, стратегия сразу отсеивается, остальные ответы не ждём.',
        'Финал по пингу|Как только набралось 4 стратегии на 100%, перебор останавливается. Три самые быстрые проходят финал: по два замера пинга каждая, побеждает самый низкий средний пинг. Победитель подключается сам, без окна с результатами.',
        'Почему не все стратегии разом|Честно: запустить несколько winws одновременно нельзя. Они все работают через один драйвер WinDivert и хватают одни и те же пакеты, результаты были бы враньём. Поэтому скорость берётся из параллельных проверок внутри стратегии, раннего отсева и умного порядка. Выходит примерно в 2-3 раза быстрее.',
        'Риск|На очень медленном интернете короткие таймауты могут забраковать нормальную стратегию. Проверяются все стратегии (сборка 15), досрочно останавливается только срочный подбор.'
    )
    Add-HelpLines $GameHelp @(
        'Что это|Пока вы играете, программа ведёт себя тише и отдаёт ресурсы игре и обходу. Включается сама, когда видит запущенную игру (CS2, Dota 2, Valorant, Apex, Fortnite, GTA V, Rust, Tarkov, LoL, PUBG, Roblox и др.), и сама выключается, когда игра закрыта. Проверка раз в 5 секунд.',
        'Приоритет winws: высокий|Игра грузит процессор, и Windows может придерживать winws в очереди. Тогда войс в Discord хрипит, а YouTube на втором мониторе подвисает. С высоким приоритетом пакеты обрабатываются сразу. Вне игры winws работает с приоритетом чуть выше обычного.',
        'Сама программа: ниже обычного|Окно Zapret Studio уступает процессор игре и не отъедает кадры.',
        'Анимации на паузе|Пульс шара и анимации переключения не рисуются, видеокарта занята только игрой.',
        'Без всплывающих уведомлений|Уведомления из трея не вылезают поверх игры. Всё пишется в журнал, а значок в трее всё равно покажет сбой.',
        'Игры — напрямую|Главное с сборки 14: при включённом геймрежиме все игры идут через ваш обычный интернет, а не через обход. Обход остаётся только для YouTube, Discord и сайтов. Переключать лучше не в игре: стратегия перезапустится на 2–3 секунды.'
    )
    Add-HelpLines $InstantHelp @(
        'Как работает|Пока обход включён, связь проверяется каждые 20 секунд (даже если слежение в Настройках выключено). Сервис не ответил — через 3 секунды перепроверка, и если опять нет, сразу включается следующая лучшая стратегия: сначала по проценту, потом по пингу. Сломавшуюся не перезапускаем, время не тратим.',
        'Если и она не открывает|Через 7 секунд проверка и дальше по списку. Варианты кончились — запускается срочный подбор (с турбо, если он включён).',
        'Риск|Запросы к вашим сервисам раз в 20 секунд — это копейки трафика. Но на очень нестабильном интернете стратегия может переключаться чаще, чем нужно.'
    )
    Update-GameState
}

