    $s = [bool]$Cfg.Simple
    $vis = 'Visible'; if ($s) { $vis = 'Collapsed' }
    foreach ($e in @($SearchRow, $BtnSort, $CountText, $SloganText, $BtnRestart, $TabHelp)) { if ($e) { $e.Visibility = $vis } }
    if ($s) {
        $ColLeft.Width = New-Object System.Windows.GridLength 250
        $ColOrb.Width = New-Object System.Windows.GridLength 110
        $OrbHost.LayoutTransform = New-Object System.Windows.Media.ScaleTransform 0.6, 0.6
        if ($TabLook.IsChecked -or $TabFont.IsChecked -or $TabHelp.IsChecked) { $TabSet.IsChecked = $true }
        $BtnSimple.Content = 'Обычный режим'
        $SimpleText.Text = 'Сейчас простой: только главное. Нажмите, чтобы вернуть всё как было'
    } else {
        $ColLeft.Width = New-Object System.Windows.GridLength 310
        $ColOrb.Width = New-Object System.Windows.GridLength 176
        $OrbHost.LayoutTransform = [System.Windows.Media.Transform]::Identity
        $BtnSimple.Content = 'Простой режим'
        $SimpleText.Text = 'Минимум всего: список, запуск, пинг, журнал и настройки. Остальное спрячется'
    }
    try { Cards-Refresh } catch { }
}

# ---------------------------------------------------------------- ускорение (пинг): всё обратимо, копия исходных значений лежит рядом с настройками
$script:BoostFile = Join-Path (Split-Path -Parent $script:SettingsPath) 'zs-boost-backup.json'
$script:TcpIfBase = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
$script:MmKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
function Get-BoostAdapters { @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }) }
function Test-DnsMs([string]$srv) {
    $best = 99999
    foreach ($h in @('www.youtube.com', 'discord.com')) {
        $sw = [Diagnostics.Stopwatch]::StartNew()
        try {
            $r = @(Resolve-DnsName -Name $h -Server $srv -Type A -DnsOnly -QuickTimeout -ErrorAction Stop | Where-Object { $_.IPAddress })
            $sw.Stop()
            if ($r.Count -gt 0 -and $sw.ElapsedMilliseconds -lt $best) { $best = [int]$sw.ElapsedMilliseconds }
        } catch { }
        Pump-Ui
    }
    $best
}
function Read-BoostBackup {
    if (-not (Test-Path -LiteralPath $script:BoostFile)) { return $null }
    try { return (Get-Content -LiteralPath $script:BoostFile -Raw -Encoding UTF8 | ConvertFrom-Json) } catch { return $null }
}
function Update-BoostState {
    if (-not $BoostState) { return }
    $bk = Read-BoostBackup
    if ($Cfg.Boost) {
        $when = ''; if ($bk -and $bk.When) { $when = ' (с ' + ([string]$bk.When).Replace('T', ' ') + ')' }
        $BoostState.Text = 'Сейчас: ускорение включено' + $when + '. Можно нажать ещё раз — перемерит DNS'
        $BtnBoost.Content = 'Ускорить ещё раз'
    } else {
        $BoostState.Text = 'Сейчас: выключено, всё как в Windows по умолчанию'
        $BtnBoost.Content = 'Ускорить стратегии'
    }
    $BtnUnboost.IsEnabled = ([bool]$Cfg.Boost -or ($null -ne $bk))
}
function Apply-Boost {
    $BoostState.Text = 'Ускоряю… меряю DNS (до 15 секунд)'; Pump-Ui
    $bk = Read-BoostBackup
    $newBk = ($null -eq $bk)
    if ($newBk) { $bk = [pscustomobject]@{ Dns = @(); Tcp = @(); Mm = $null; When = (Get-Date).ToString('yyyy-MM-ddTHH:mm') } }
    $done = @()
    $ads = Get-BoostAdapters
    if ($ads.Count -eq 0) { Log 'Ускорение: не нашёл активных сетевых карт, DNS и TCP не трогаю' }
    # 1) самый быстрый рабочий DNS (только если он быстрее текущего)
    try {
        if ($ads.Count -gt 0) {
            $cur = ''
            foreach ($a in $ads) { $c = @((Get-DnsClientServerAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue).ServerAddresses); if ($c.Count -gt 0) { $cur = [string]$c[0]; break } }
            $curMs = 99999; if ($cur) { $curMs = Test-DnsMs $cur }
            $res = @()
            foreach ($s in @('1.1.1.1', '8.8.8.8', '77.88.8.8', '1.0.0.1', '8.8.4.4')) { $res += [pscustomobject]@{ S = $s; Ms = (Test-DnsMs $s) } }
            $ok = @($res | Where-Object { $_.Ms -lt 3000 } | Sort-Object Ms)
            $curTxt = 'не отвечает'; if ($curMs -lt 99999) { $curTxt = ('{0} мс' -f $curMs) }
            if ($ok.Count -gt 0 -and ($ok[0].Ms + 3) -lt $curMs) {
                $pick = @($ok | Select-Object -First 2 | ForEach-Object { $_.S })
                foreach ($a in $ads) {
                    $g = [string]$a.InterfaceGuid
                    if (-not @(@($bk.Dns) | Where-Object { $_ -and $_.Guid -eq $g }).Count) {
                        $ns = ''; try { $ns = [string](Get-ItemProperty -LiteralPath (Join-Path $script:TcpIfBase $g) -Name NameServer -ErrorAction Stop).NameServer } catch { }
                        $bk.Dns = @(@($bk.Dns) | Where-Object { $_ }) + @([pscustomobject]@{ Guid = $g; NS = $ns })
                    }
                    Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses $pick -ErrorAction Stop
                }
                $done += ('DNS ' + ($pick -join ', ') + (' ({0} мс, было {1})' -f $ok[0].Ms, $curTxt))
            } else { $done += ('DNS оставлен свой: он и так быстрый (' + $curTxt + ')') }
            try { Clear-DnsClientCache -ErrorAction SilentlyContinue } catch { }
        }
    } catch { Log ('Ускорение: DNS не поменялся — ' + $_.Exception.Message) }
    $BoostState.Text = 'Ускоряю… TCP и приоритеты'; Pump-Ui
    # 2) TCP без задержки подтверждений и склейки мелких пакетов (Nagle)
    try {
        $n = 0
        foreach ($a in $ads) {
            $k = Join-Path $script:TcpIfBase ([string]$a.InterfaceGuid)
            if (-not (Test-Path -LiteralPath $k)) { continue }
            foreach ($nm in @('TcpAckFrequency', 'TCPNoDelay', 'TcpDelAckTicks')) {
                if (-not @(@($bk.Tcp) | Where-Object { $_ -and $_.K -eq $k -and $_.N -eq $nm }).Count) {
                    $old = $null; try { $old = (Get-ItemProperty -LiteralPath $k -Name $nm -ErrorAction Stop).$nm } catch { }
                    $bk.Tcp = @(@($bk.Tcp) | Where-Object { $_ }) + @([pscustomobject]@{ K = $k; N = $nm; V = $old })
                }
                $v = 1; if ($nm -eq 'TcpDelAckTicks') { $v = 0 }
                New-ItemProperty -LiteralPath $k -Name $nm -PropertyType DWord -Value $v -Force -ErrorAction Stop | Out-Null
            }
            $n++
        }
        if ($n -gt 0) { $done += ('TCP без задержек на {0} сетевых картах' -f $n) }
    } catch { Log ('Ускорение: TCP не настроился — ' + $_.Exception.Message) }
    # 3) сетевой троттлинг Windows (резал сеть, пока играет музыка/видео)
    try {
        if ($null -eq $bk.Mm) {
            $o1 = $null; $o2 = $null
            try { $o1 = (Get-ItemProperty -LiteralPath $script:MmKey -Name NetworkThrottlingIndex -ErrorAction Stop).NetworkThrottlingIndex } catch { }
            try { $o2 = (Get-ItemProperty -LiteralPath $script:MmKey -Name SystemResponsiveness -ErrorAction Stop).SystemResponsiveness } catch { }
            $bk.Mm = [pscustomobject]@{ Nti = $o1; Sr = $o2 }
        }
        New-ItemProperty -LiteralPath $script:MmKey -Name NetworkThrottlingIndex -PropertyType DWord -Value ([int]-1) -Force -ErrorAction Stop | Out-Null
        New-ItemProperty -LiteralPath $script:MmKey -Name SystemResponsiveness -PropertyType DWord -Value 10 -Force -ErrorAction Stop | Out-Null
        $done += 'троттлинг сети выключен'
    } catch { Log ('Ускорение: троттлинг не выключился — ' + $_.Exception.Message) }
    # 4) winws без очереди
    $Cfg.Boost = $true; Save-Settings
    Set-WinwsPrio 'High'
    $done += 'winws с высоким приоритетом'
    try { $bk | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $script:BoostFile -Encoding UTF8 } catch { Log ('Ускорение: не смог сохранить копию для отката — ' + $_.Exception.Message) }
    Log ('Ускорение включено: ' + ($done -join '; '))
    Log 'Ускорение: TCP-часть заработает полностью после перезагрузки (сеть специально не переподключаю, чтобы не выкинуло из игры)'
    Update-BoostState
    if ($script:Running -and -not $script:Testing) { $script:AutoPingAt = (Get-Date).AddSeconds(2); Reset-LiveClient; $script:LiveAt = (Get-Date).AddSeconds(3) }
}
function Undo-Boost {
    $bk = Read-BoostBackup
    $errs = 0
    if ($bk) {
        foreach ($d in @($bk.Dns)) {
            if (-not $d) { continue }
            try {
                $a = @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { [string]$_.InterfaceGuid -eq [string]$d.Guid } | Select-Object -First 1)
                if ($a.Count -gt 0) {
                    $list = @(([string]$d.NS) -split '[,\s]+' | Where-Object { $_ })
                    if ($list.Count -gt 0) { Set-DnsClientServerAddress -InterfaceIndex $a[0].ifIndex -ServerAddresses $list -ErrorAction Stop }
                    else { Set-DnsClientServerAddress -InterfaceIndex $a[0].ifIndex -ResetServerAddresses -ErrorAction Stop }
                }
            } catch { $errs++; Log ('Откат: DNS — ' + $_.Exception.Message) }
        }
        foreach ($t in @($bk.Tcp)) {
            if (-not $t) { continue }
            try {
                if ($null -eq $t.V) { Remove-ItemProperty -LiteralPath $t.K -Name $t.N -ErrorAction SilentlyContinue }
                else { New-ItemProperty -LiteralPath $t.K -Name $t.N -PropertyType DWord -Value ([int64]$t.V) -Force -ErrorAction Stop | Out-Null }
            } catch { $errs++ }
        }
        if ($bk.Mm) {
            foreach ($pair in @(@('NetworkThrottlingIndex', $bk.Mm.Nti), @('SystemResponsiveness', $bk.Mm.Sr))) {
                try {
                    if ($null -eq $pair[1]) { Remove-ItemProperty -LiteralPath $script:MmKey -Name $pair[0] -ErrorAction SilentlyContinue }
                    else { $v = [int64]$pair[1]; if ($v -lt 0) { $v = [int]$v }; New-ItemProperty -LiteralPath $script:MmKey -Name $pair[0] -PropertyType DWord -Value ([int]$v) -Force -ErrorAction Stop | Out-Null }
                } catch { $errs++ }
            }
        }
        try { Clear-DnsClientCache -ErrorAction SilentlyContinue } catch { }
        if ($errs -eq 0) { try { Remove-Item -LiteralPath $script:BoostFile -Force -ErrorAction SilentlyContinue } catch { } }
    }
    $Cfg.Boost = $false; Save-Settings
    if ($Cfg.ExpGame -and $script:GameActive) { Set-WinwsPrio 'High' } elseif ($Cfg.ExpGame) { Set-WinwsPrio 'AboveNormal' } else { Set-WinwsPrio 'AboveNormal' }
    if ($errs -eq 0) { Log 'Ускорение откачено: DNS, TCP и приоритеты как были до нажатия' }
    else { Log ('Ускорение откачено частично, ошибок: {0}. Копия не удалена — можно нажать «Откатить» ещё раз' -f $errs) }
    Update-BoostState
}
function Build-BoostHelp {
    Add-HelpLines $BoostHelp @(
        'Почему было 180+|Раньше пинг считался как время открытия НОВОГО соединения: DNS + TCP + TLS + ответ сервера. Это 3-4 хода до сервера и обратно, поэтому цифра была в 3-4 раза больше настоящего пинга. Теперь кнопка «Пинг» показывает оба числа: настоящий пинг на открытом соединении (так работают браузер и Discord) и в скобках время открытия. Цвет: зелёный до 90 мс, жёлтый до 160, красный выше.',
        'Что делает «Ускорить»|1) Меряет DNS Cloudflare, Google и Яндекс и ставит самый быстрый, если он быстрее вашего (DNS провайдера часто тормозит и подсовывает заглушки). 2) Выключает задержку подтверждений TCP и склейку мелких пакетов (Nagle) — до 200 мс задержки в чатах и играх на TCP. 3) Отключает сетевой троттлинг Windows. 4) Ставит winws высокий приоритет. Потом сам меряет пинг.',
        'Откат|«Откатить ускорение» возвращает DNS, TCP, троттлинг и приоритет ровно как было до первого нажатия. Копия исходных значений — файл zs-boost-backup.json рядом с настройками.',
        'Честно про 90 мс|Пинг в основном задаёт маршрут провайдера до сервера, обход добавляет копейки. Ускорение убирает лишние задержки на самом компьютере и в DNS. Ещё один приём — подбор теперь среди стратегий на 100% выбирает самую быструю.'
    )
    Add-HelpLines $ExtraHelp @(
        'Тёплый DNS|Раз в 90 секунд заранее узнаёт адреса ваших сервисов. Когда вы открываете YouTube или Discord, адрес уже в кэше Windows — минус один запрос к DNS при каждом первом открытии. Трафика почти ноль.',
        'Подбор только по избранным|Проверяются только стратегии со звёздочкой — секунды вместо минут. Нет избранных — проверяются все. Срочный подбор при сбое всегда проверяет все, чтобы не остаться без связи.'
    )
}

# ---------------------------------------------------------------- живой пинг (только пинг, без скачивания) + анти-РКН фишки
$script:Live = $null; $script:LiveAt = $null; $script:LiveClient = $null; $script:LiveFails = @{}; $script:LastThr = [datetime]::MinValue
$script:ThrUrls = @{ yt = 'https://www.youtube.com/'; dc = 'https://discord.com/'; tw = 'https://www.twitch.tv/' }
$script:QuicRule = 'Zapret Studio - no QUIC'
function Format-LiveSec([int]$s) {
    if ($s -le 0) { return 'выкл' }
    if ($s -lt 60) { return ('{0} сек' -f $s) }
    if (($s % 60) -eq 0) { return ('{0} мин' -f [int]($s / 60)) }
    return ('{0}:{1:00}' -f [int][Math]::Floor($s / 60), ($s % 60))
}
function Get-LiveClient {
    if (-not $script:LiveClient) {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        # соединение держим открытым до 5,5 мин, чтобы живой пинг мерил сам путь, а не рукопожатие
        try { if ([Net.ServicePointManager]::MaxServicePointIdleTime -lt 330000) { [Net.ServicePointManager]::MaxServicePointIdleTime = 330000 } } catch { }
        $c = New-Object System.Net.Http.HttpClient
        $c.Timeout = [TimeSpan]::FromSeconds(5)
        try { $c.DefaultRequestHeaders.UserAgent.ParseAdd('Mozilla/5.0 (Windows NT 10.0; Win64; x64)') } catch { }
        $script:LiveClient = $c
    }
    $script:LiveClient
}
function Reset-LiveClient {
    if ($script:LiveClient) { try { $script:LiveClient.Dispose() } catch { } }
    $script:LiveClient = $null; $script:Live = $null
}
function Start-LivePing {
    if ($script:Live -or $script:Testing -or -not $script:Running) { return }
    $svcs = @(Get-MonSvcs | Select-Object -First 4)
    if ($svcs.Count -eq 0) { return }
    $c = Get-LiveClient
    # редкий интервал: сервер мог закрыть соединение, поэтому первый HEAD открывает, второй меряет
    $twice = ([int]$Cfg.LivePing -ge 90)
    $tasks = @()
    foreach ($s in $svcs) { $u = @($s.Urls)[0]; $tasks += @{ Svc = $s.Key; Short = $s.Short; Name = $s.Name; Url = $u; Task = [ZProbe]::RealPing($c, $u, $twice) } }
    $script:Live = @{ Tasks = $tasks; Until = (Get-Date).AddSeconds($(if ($twice) { 16 } else { 11 })) }
}
function Poll-Live {
    $l = $script:Live; if (-not $l) { return }
    $done = @($l.Tasks | Where-Object { $_.Task.IsCompleted }).Count
    if ($done -lt $l.Tasks.Count -and (Get-Date) -lt $l.Until) { return }
    $script:Live = $null
    # сборка 14: причина ложного «нет ответа» - запрос шёл по старому keep-alive соединению, которое DPI/сервер молча закрыл,
    # а ручная проверка открывает свежее. Теперь перед «нет ответа» молчавшие сервисы перепроверяются на новом соединении
    $lvBad = @($l.Tasks | Where-Object { $_.Task.Status -ne 'RanToCompletion' -and $_.Url })
    if ($lvBad.Count -gt 0 -and -not $l.Retry -and $script:Running -and -not $script:Testing) {
        Reset-LiveClient
        $lvC = Get-LiveClient
        $lvT = @()
        foreach ($lvX in $l.Tasks) {
            if ($lvX.Task.Status -eq 'RanToCompletion' -or -not $lvX.Url) { $lvT += $lvX }
            else { $lvT += @{ Svc = $lvX.Svc; Short = $lvX.Short; Name = $lvX.Name; Url = $lvX.Url; Task = [ZProbe]::RealPing($lvC, $lvX.Url, $true) } }
        }
        $script:Live = @{ Tasks = $lvT; Until = (Get-Date).AddSeconds(16); Retry = $true }
        return
    }
    $parts = @(); $best = 1e9; $okN = 0; $lost = @()
    foreach ($t in $l.Tasks) {
        if ($t.Task.Status -eq 'RanToCompletion') {
            $ms = [int]$t.Task.Result[1]; $okN++
            if ($ms -lt $best) { $best = $ms }
            $parts += ('{0} {1} мс' -f $t.Short, $ms)
            $script:LiveFails[$t.Svc] = 0
        } else {
            $parts += ('{0} нет ответа' -f $t.Short)
            $script:LiveFails[$t.Svc] = [int]$script:LiveFails[$t.Svc] + 1
            if ($script:LiveFails[$t.Svc] -ge 2) { $lost += $t }
        }
    }
    if ($okN -lt $l.Tasks.Count) { Reset-LiveClient }
    if (-not $script:Running) { return }
    $script:PingManual = $false
    if ($okN -gt 0) { try { Push-PingHist $best } catch { } }
    $LiveText.Visibility = 'Visible'
    $LiveText.Text = ('● Пинг {0:HH:mm:ss} · {1} · раз в {2}' -f (Get-Date), ($parts -join ' · '), (Format-LiveSec ([int]$Cfg.LivePing))); try { Pretty-Ping $LiveText } catch { }
    try {
        if ($okN -eq 0) { $LiveText.Foreground = New-Brush (ToColor '#EF4444') }
        elseif ($best -lt 90) { $LiveText.Foreground = New-Brush (ToColor '#22C55E') }
        elseif ($best -lt 160) { $LiveText.Foreground = New-Brush (ToColor '#F59E0B') }
        else { $LiveText.Foreground = New-Brush (ToColor '#EF4444') }
    } catch { }
    # ранний сигнал: сервис дважды подряд молчит - проверяем связь сразу, без ожидания расписания
    if ($Cfg.ExpEarly -and $lost.Count -gt 0 -and -not $script:Mon -and -not $script:Testing -and -not $script:Alert) {
        $nm = ($lost | ForEach-Object { $_.Name }) -join ', '
        Log ('Ранний сигнал: ' + $nm + ' дважды подряд не ответил, проверяю связь сейчас')
        foreach ($t in $lost) { $script:LiveFails[$t.Svc] = 0 }
        $script:MonConfirm = $true
        try { Start-MonCheck } catch { }
    }
}

# без QUIC: правило брандмауэра на исходящий UDP 443, браузер сам уходит на TCP
function Test-NoQuic { try { return [bool](Get-NetFirewallRule -DisplayName $script:QuicRule -ErrorAction SilentlyContinue) } catch { return $false } }
function Set-NoQuic([bool]$on) {
    try {
        Get-NetFirewallRule -DisplayName $script:QuicRule -ErrorAction SilentlyContinue | Remove-NetFirewallRule -ErrorAction SilentlyContinue
        if ($on) {
            New-NetFirewallRule -DisplayName $script:QuicRule -Direction Outbound -Protocol UDP -RemotePort 443 -Action Block -Profile Any -ErrorAction Stop | Out-Null
            Log 'Без QUIC: правило брандмауэра добавлено, браузер переходит на TCP. Откройте вкладки заново'
        } else { Log 'Без QUIC: правило брандмауэра удалено' }
        return $true
    } catch { Log ('Без QUIC: не получилось (нужны права администратора): ' + $_.Exception.Message); return $false }
}

# копия настроек
function Export-Cfg {
    Save-Settings
    $dst = Join-Path ([Environment]::GetFolderPath('Desktop')) ('ZapretStudio-настройки-{0:yyyyMMdd-HHmm}.json' -f (Get-Date))
    try { Copy-Item -LiteralPath $script:SettingsPath -Destination $dst -Force; Log ('Копия настроек сохранена: ' + $dst) } catch { Log ('Не удалось сохранить копию: ' + $_.Exception.Message) }
}
function Import-Cfg {
    $d = New-Object Microsoft.Win32.OpenFileDialog
    $d.Filter = 'Настройки Zapret Studio (*.json)|*.json'
    $d.InitialDirectory = [Environment]::GetFolderPath('Desktop')
    if (-not $d.ShowDialog($Win)) { return }
    try {
        $j = Get-Content -LiteralPath $d.FileName -Raw -Encoding UTF8 | ConvertFrom-Json
        $names = @($j.PSObject.Properties | ForEach-Object { $_.Name })
        if (-not ($names -contains 'Accent' -or $names -contains 'Favorites' -or $names -contains 'MonitorMin')) { throw 'это не файл настроек Zapret Studio' }
        Copy-Item -LiteralPath $d.FileName -Destination $script:SettingsPath -Force
        $script:CfgImported = $true
        Log 'Настройки загружены из копии. Перезапустите Zapret Studio, чтобы они применились'
    } catch { Log ('Не удалось загрузить настройки: ' + $_.Exception.Message) }
}

# конфликты: что чем управляется, видно прямо в настройках
# ---- сборка 5: заблокированная настройка красится и получает подпись «кто блокирует» (по ней можно нажать — переход к настройке-блокировщику)
$script:Locks = @{}
function Set-Lock($ctl, [string]$why, $nav) {
    if (-not $ctl) { return }
    $key = [string]$ctl.Name
    $st = $script:Locks[$key]
    if (-not $st) {
        $row = $ctl.Parent; $title = $null; $lb = $null
        if ($row -is [Windows.Controls.Panel] -and $row.Children.Count -gt 0) {
            $f = $row.Children[0]
            if ($f -is [Windows.Controls.TextBlock]) { $title = $f }
            elseif ($f -is [Windows.Controls.Panel] -and $f.Children.Count -gt 0 -and $f.Children[0] -is [Windows.Controls.TextBlock]) { $title = $f.Children[0] }
        }
        $hp = $null; if ($row) { $hp = $row.Parent }
        if ($hp -is [Windows.Controls.Panel]) {
            $lb = New-Object Windows.Controls.TextBlock
            $lb.TextWrapping = 'Wrap'; $lb.Margin = New-Object Windows.Thickness 14, -4, 70, 10; $lb.Visibility = 'Collapsed'
            $lb.Cursor = [Windows.Input.Cursors]::Hand
            $lb.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'WarnBrush')
            $lb.SetResourceReference([Windows.Controls.TextBlock]::FontSizeProperty, 'Fs11')
            $lb.Add_MouseLeftButtonUp({ param($s, $ev) try { if ($s.Tag -is [scriptblock]) { & $s.Tag } } catch { } })
            $i = $hp.Children.IndexOf($row)
            if ($i -ge 0) { $hp.Children.Insert($i + 1, $lb) }
        }
        $st = @{ Title = $title; Lb = $lb }
        $script:Locks[$key] = $st
    }
    if ($why) {
        $ctl.IsEnabled = $false; $ctl.Opacity = 0.55
        if ($st.Title) { $st.Title.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'WarnBrush') }
        if ($st.Lb) {
            $tail = ''; if ($nav) { $tail = '  → нажмите, чтобы перейти' }
            $st.Lb.Text = ('🔒 Недоступно: ' + $why + $tail); $st.Lb.Tag = $nav; $st.Lb.Visibility = 'Visible'
            if ($nav) { $st.Lb.Cursor = [Windows.Input.Cursors]::Hand } else { $st.Lb.Cursor = $null }
        }
        $ctl.ToolTip = ('Недоступно: ' + $why)
        [Windows.Controls.ToolTipService]::SetShowOnDisabled($ctl, $true)
    } else {
        $ctl.IsEnabled = $true; $ctl.Opacity = 1
        if ($st.Title) { $st.Title.ClearValue([Windows.Controls.TextBlock]::ForegroundProperty) }
        if ($st.Lb) { $st.Lb.Visibility = 'Collapsed'; $st.Lb.Tag = $null }
        $ctl.ToolTip = $null
    }
}
# полная карта зависимостей (кто кого блокирует) — единственное место, где это решается
function Sync-Conflicts {
    $inst = [bool]$Cfg.ExpInstant; $live = [int]$Cfg.LivePing -gt 0; $mon = [bool]$Cfg.Monitor
    $nStab = { Hub-Goto 'exp' $ChkInstant { $EgStab.IsChecked = $true } }
    $nMon = { Hub-Goto 'net' $ChkMon $null }
    $nNet = { Hub-Goto 'net' $SlLive $null }
    $nSys = { Hub-Goto 'sys' $ChkPerf $null }
    $nLook = { Hub-Goto 'look' $ChkBlur $null }
    $nSplash = { Hub-Goto 'look' $ChkSplash $null }
    $wI = '«Мгновенное переключение» (Экспериментальное → Стабильность)'
    # 1. Слежение за связью / автосмена / интервал
    if ($inst) {
        Set-Lock $ChkMon $null $null
        $ChkMon.ToolTip = 'Связь уже проверяет «Мгновенное переключение» — раз в 20 секунд. Этот тумблер не нужен'
        Set-Lock $ChkAutoFix 'включено «Мгновенное переключение» — оно само меняет стратегию при сбое' $nStab
        Set-Lock $SlMonInt 'включено «Мгновенное переключение» — оно само проверяет связь каждые 20 секунд' $nStab
        $LbSlMonInt.Text = '20 сек'
    } else {
        Set-Lock $ChkMon $null $null
        if ($mon) { Set-Lock $ChkAutoFix $null $null; Set-Lock $SlMonInt $null $null }
        else {
            Set-Lock $ChkAutoFix 'выключено «Следить за связью» — включите его выше, иначе менять стратегию не по чему' $nMon
            Set-Lock $SlMonInt 'выключено «Следить за связью» — включите его выше' $nMon
        }
        $LbSlMonInt.Text = ('{0} мин' -f [int][Math]::Round($SlMonInt.Value))
    }
    # 2. Пинг
    # «мерить пинг после запуска» теперь всегда включён и скрыт (сборка 8)
    # 3. Экспериментальное, зависящее от обычных настроек
    if ($live) { Set-Lock $ChkEarly $null $null } else { Set-Lock $ChkEarly 'выключен «Живой пинг» — раннему сигналу нечего отслеживать' $nNet }
    if ($mon -or $inst) { Set-Lock $ChkThrottle $null $null } else { Set-Lock $ChkThrottle 'выключены и «Следить за связью», и «Мгновенное переключение» — включите любое из двух' $nMon }
    # 4. Вид
    if ($Cfg.Perf) { Set-Lock $ChkGlow 'включён «Режим производительности» — он отключает всё лишнее ради скорости' $nSys } else { Set-Lock $ChkGlow $null $null }
    if ($Cfg.Blur) { Set-Lock $SlRadius 'включено «Размытие фона» — с ним окно не может быть скруглённым' $nLook } else { Set-Lock $SlRadius $null $null }
    # 5. Заставка
    if ($script:IntroChips) {
        if ($Cfg.Splash) { Set-Lock $IntroChips $null $null } else { Set-Lock $IntroChips 'выключена «Заставка при запуске» — включите её выше. Кнопка «Посмотреть» работает всегда' $nSplash }
    }
}

# под-вкладки внутри Настроек и Экспериментального
function Show-Grp($map, [string]$key) {
    foreach ($k in @($map.Keys)) {
        $p = $map[$k]
        if ($k -eq $key) {
            $p.Visibility = 'Visible'
            if (-not $Cfg.Perf) {
                $a = New-Object System.Windows.Media.Animation.DoubleAnimation 0.0, 1.0, (New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(200)))
                $p.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
            }
        } else { $p.Visibility = 'Collapsed' }
    }
}
function Build-StabHelp {
    Add-HelpLines $StabHelp @(
        'Анти-душилка|Ловит «тихую» блокировку: сайт открывается, но данные встают на первых 16–20 КБ. Так ТСПУ душит отдельный сервис, и обычная проверка этого не видит. Раз в минуту при проверке связи скачивает до 64 КБ главной страницы YouTube, Discord и Twitch (только тех, что у вас в приоритете). Если данные застряли, это считается сбоем и запускается автосмена стратегии. Трафик: около 4–8 МБ в час.',
        'Ранний сигнал|Работает от живого пинга. Если сервис два раза подряд не ответил, проверка связи запускается сразу, а не по расписанию, и без лишней перепроверки. Вместе с мгновенным переключением стратегия сменится через секунды после сбоя.',
        'Без QUIC|YouTube и Google в браузере ходят по QUIC (UDP 443). Его душат чаще, а обходить сложнее. Правило брандмауэра Windows запрещает исходящий UDP 443, и браузер сам переходит на обычный TCP, который стратегии обходят стабильнее. Голос Discord (UDP 50000+) не затрагивается. Правило называется «Zapret Studio - no QUIC», выключение тумблера его удаляет. Пока тумблер включён, правило действует и после выхода из программы.'
    )
}

