        $ht = New-Object System.Windows.Controls.TextBlock; $ht.Text = ($sec.I + '  ' + $sec.H.ToUpper()); $ht.FontWeight = 'Bold'; $ht.Margin = New-Object System.Windows.Thickness 10, 0, 0, 0; $ht.VerticalAlignment = 'Center'
        $ht.SetResourceReference([Windows.Controls.TextBlock]::FontSizeProperty, 'Fs13')
