$script:HelpCur = $null
$script:HelpTm = New-Object Windows.Threading.DispatcherTimer
$script:HelpTm.Interval = [TimeSpan]::FromMilliseconds(260)
$script:HelpTm.Add_Tick({ $script:HelpTm.Stop(); if ($script:HelpCur) { Show-HelpPop $script:HelpCur } })
function Help-Hover($card, [bool]$on) {
    try {
        if ($on) {
            $card.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'AccentBrush')
            $card.Tag.Mo.Opacity = 1
            $script:HelpCur = $card; $script:HelpTm.Stop(); $script:HelpTm.Start()
        } else {
            $card.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'StrokeBrush')
            $card.Tag.Mo.Opacity = 0.55
            if ($script:HelpCur -eq $card) { $script:HelpCur = $null; $script:HelpTm.Stop(); $HelpPop.IsOpen = $false }
        }
    } catch { }
}
function Show-HelpPop($card) {
    try {
        $d = $card.Tag
        $HelpPopIcon.Text = $d.Icon; $HelpPopSec.Text = $d.Sec.ToUpper(); $HelpPopTitle.Text = $d.Title
        $HelpPopBody.Children.Clear()
        foreach ($p in ($d.Body -split '¶')) {
            $p = $p.Trim(); if (-not $p) { continue }
            $tb = New-Object System.Windows.Controls.TextBlock; $tb.TextWrapping = 'Wrap'; $tb.LineHeight = 19
            $tb.Foreground = New-Brush (ToColor '#D4D8EA'); $tb.Margin = New-Object System.Windows.Thickness 0, 0, 0, 6
            if ($p.StartsWith('! ')) {
                $bx = New-Object System.Windows.Controls.Border; $bx.CornerRadius = New-Object System.Windows.CornerRadius 10; $bx.Padding = New-Object System.Windows.Thickness 10, 7, 10, 7; $bx.Margin = New-Object System.Windows.Thickness 0, 4, 0, 2
                $bx.Background = New-Brush (ToColor '#1F22C55E'); $bx.BorderThickness = New-Object System.Windows.Thickness 1; $bx.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'AccentBrush')
                $tb.Text = ('💡 ' + $p.Substring(2)); $tb.Margin = New-Object System.Windows.Thickness 0; $tb.Foreground = New-Brush (ToColor '#FFFFFF')
                $bx.Child = $tb; [void]$HelpPopBody.Children.Add($bx)
            } elseif ($p -match '^(•|\d+\.)\s*(.*)$') {
                $row = New-Object System.Windows.Controls.DockPanel; $row.Margin = New-Object System.Windows.Thickness 2, 0, 0, 5
                $mk = New-Object System.Windows.Controls.TextBlock; $mk.Text = $Matches[1]; $mk.MinWidth = 16; $mk.FontWeight = 'Bold'
                $mk.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'AccentBrush')
                [System.Windows.Controls.DockPanel]::SetDock($mk, 'Left'); [void]$row.Children.Add($mk)
                $tb.Text = $Matches[2]; $tb.Margin = New-Object System.Windows.Thickness 4, 0, 0, 0; [void]$row.Children.Add($tb)
                [void]$HelpPopBody.Children.Add($row)
            } else { $tb.Text = $p; [void]$HelpPopBody.Children.Add($tb) }
        }
        $HelpPop.PlacementTarget = $card
        $HelpPop.IsOpen = $true
        if (-not $Cfg.Perf) {
            $tg = $HelpPopCard.RenderTransform
            $bk = New-Object Windows.Media.Animation.BackEase; $bk.EasingMode = 'EaseOut'; $bk.Amplitude = 0.35
            $ce = New-Object Windows.Media.Animation.CubicEase; $ce.EasingMode = 'EaseOut'
            foreach ($pp in @([Windows.Media.ScaleTransform]::ScaleXProperty, [Windows.Media.ScaleTransform]::ScaleYProperty)) {
                $a = New-Object Windows.Media.Animation.DoubleAnimation 0.9, 1, ([TimeSpan]::FromMilliseconds(320)); $a.EasingFunction = $bk; $tg.Children[0].BeginAnimation($pp, $a)
            }
            $a = New-Object Windows.Media.Animation.DoubleAnimation -12, 0, ([TimeSpan]::FromMilliseconds(320)); $a.EasingFunction = $ce; $tg.Children[1].BeginAnimation([Windows.Media.TranslateTransform]::YProperty, $a)
            $a = New-Object Windows.Media.Animation.DoubleAnimation 0, 1, ([TimeSpan]::FromMilliseconds(220)); $HelpPopCard.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
        }
    } catch { }
}

