function Show-Page([string]$n) {
    $PageLog.Visibility = 'Collapsed'; $PageLook.Visibility = 'Collapsed'; $PageFont.Visibility = 'Collapsed'; $PageSet.Visibility = 'Collapsed'; $PageHelp.Visibility = 'Collapsed'; $PageExp.Visibility = 'Collapsed'
    $hub = [bool]$script:HubReady
    switch ($n) {
        'log' { $script:HubPrev = 'log'; if ($hub) { Close-Hub -KeepTab }; $PageLog.Visibility = 'Visible'; Page-In $PageLog }
        'help' { $script:HubPrev = 'help'; if ($hub) { Close-Hub -KeepTab }; $PageHelp.Visibility = 'Visible'; Page-In $PageHelp }
        'set' { if ($hub) { Open-Hub '' } else { $PageSet.Visibility = 'Visible' } }
        'look' { if ($hub) { Open-Hub 'look' } else { $PageLook.Visibility = 'Visible' } }
        'font' { if ($hub) { Open-Hub 'font' } else { $PageFont.Visibility = 'Visible' } }
        'exp' { if ($hub) { Open-Hub 'exp' } else { $PageExp.Visibility = 'Visible' } }
    }
}
