function Hub-Esc([string]$s) { [System.Security.SecurityElement]::Escape([string]$s) }
function Hub-Parse([string]$x) {
    $x = [regex]::Replace($x, '^<(\w+)', '<$1 xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"')
    [Windows.Markup.XamlReader]::Parse((Scale-Xaml $x))
}
function Hub-Tint([int]$a) {
    try {
        $c = $Win.TryFindResource('AccentBrush').Color
        $b = New-Object Windows.Media.SolidColorBrush ([Windows.Media.Color]::FromArgb([byte]$a, $c.R, $c.G, $c.B)); $b.Freeze(); $b
    } catch { [Windows.Media.BrushConverter]::new().ConvertFromString('#22FFFFFF') }
}
# забирает элемент у старого родителя (панель / ScrollViewer / Border), обработчики остаются на месте
function Hub-Take($el) {
    if (-not $el) { return $null }
    $p = $el.Parent
    if ($p -is [Windows.Controls.Panel]) { [void]$p.Children.Remove($el) }
    elseif ($p -is [Windows.Controls.ContentControl]) { $p.Content = $null }
    elseif ($p -is [Windows.Controls.Decorator]) { $p.Child = $null }
    $el
}
# весь текст элемента (заголовки, подписи, подсказки) — для поиска
function Hub-Text($o) {
    $sb = New-Object System.Text.StringBuilder
    $st = New-Object System.Collections.Stack; $st.Push($o)
    while ($st.Count -gt 0) {
        $n = $st.Pop()
        if ($n -is [Windows.Controls.TextBlock]) { [void]$sb.Append(' ').Append($n.Text) }
        if ($n -is [Windows.Controls.ContentControl] -and $n.Content -is [string]) { [void]$sb.Append(' ').Append($n.Content) }
        if ($n -is [Windows.FrameworkElement] -and $n.ToolTip -is [string]) { [void]$sb.Append(' ').Append($n.ToolTip) }
        if ($n -is [Windows.DependencyObject]) { foreach ($c in [Windows.LogicalTreeHelper]::GetChildren($n)) { if ($c -is [Windows.FrameworkElement]) { $st.Push($c) } } }
    }
    $sb.ToString()
}
function Hub-SetBg($el, $br) {
    if ($el -is [Windows.Controls.Panel] -or $el -is [Windows.Controls.Border] -or $el -is [Windows.Controls.Control]) { $el.Background = $br }
}
function Hub-Fade($el, [double]$dx, [double]$dy) {
    if (-not $el -or [bool]$Cfg.Perf) { return }
    try {
        $tt = New-Object Windows.Media.TranslateTransform $dx, $dy
        $el.RenderTransform = $tt
        $ease = New-Object Windows.Media.Animation.CubicEase; $ease.EasingMode = 'EaseOut'
        $d = [Windows.Duration][TimeSpan]::FromMilliseconds(240)
        $a = New-Object Windows.Media.Animation.DoubleAnimation 0, 1, $d; $a.EasingFunction = $ease
        $el.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
        $ax = New-Object Windows.Media.Animation.DoubleAnimation $dx, 0, $d; $ax.EasingFunction = $ease
        $ay = New-Object Windows.Media.Animation.DoubleAnimation $dy, 0, $d; $ay.EasingFunction = $ease
        $tt.BeginAnimation([Windows.Media.TranslateTransform]::XProperty, $ax)
        $tt.BeginAnimation([Windows.Media.TranslateTransform]::YProperty, $ay)
    } catch { }
}
function Hub-PaintNav {
    $sel = Hub-Tint 46; $acc = $Win.TryFindResource('AccentBrush')
    foreach ($k in @($script:HubNav.Keys)) {
        $n = $script:HubNav[$k]
        if ($k -eq $script:HubCat -and -not $script:HubQuery) { $n.B.Background = $sel; $n.Ic.Background = $acc }
        else { $n.B.Background = [Windows.Media.Brushes]::Transparent; $n.Ic.Background = $script:HubIcOff }
    }
}
function Hub-Select([string]$k) {
    if (-not $script:HubSec.Contains($k)) { $k = 'main' }
    if ($script:HubQuery) { $SetSearch.Text = ''; Hub-Search '' }
    $script:HubCat = $k
    if ($Cfg.HubCat -ne $k) { $Cfg.HubCat = $k; Request-Save }
    foreach ($kk in @($script:HubSec.Keys)) {
        $p = $script:HubSec[$kk].Panel
        if ($kk -eq $k) { $p.Visibility = 'Visible' } else { $p.Visibility = 'Collapsed' }
    }
    $SetScroll.ScrollToTop()
    Hub-PaintNav
    Hub-Fade $script:HubSec[$k].Panel 16 0
}
function Hub-Search([string]$q) {
    $q = ([string]$q).Trim().ToLowerInvariant()
    if ($q.Length -lt 2) { $q = '' }
    if ($q -eq $script:HubQuery) { return }
    if ($q -and -not $script:HubQuery) {
        # входим в поиск: запоминаем, что было видно, чтобы потом вернуть ровно как было
        $script:HubSaved = @{}
        foreach ($it in $script:HubItems) { $script:HubSaved[$it.El] = [string]$it.El.Visibility; if ($it.Hdr) { $script:HubSaved[$it.Hdr] = [string]$it.Hdr.Visibility } }
        foreach ($g in @($ExpGrpStab, $ExpGrpPick, $ExpGrpSpeed, $ExpGrpGame, $script:HubEgBar)) { if ($g) { $script:HubSaved[$g] = [string]$g.Visibility } }
    }
    $script:HubQuery = $q
    if (-not $q) {
        foreach ($kv in @($script:HubSaved.GetEnumerator())) { try { $kv.Key.Visibility = $kv.Value } catch { } }
        foreach ($it in $script:HubItems) { Hub-SetBg $it.El $it.Bg }
        $script:HubSaved = @{}
        foreach ($n in $script:HubNav.Values) { $n.Badge.Visibility = 'Collapsed'; $n.B.Opacity = 1 }
        $SetNoHits.Visibility = 'Collapsed'
        $SetFound.Text = 'Всё в одном месте'
        Hub-Select $script:HubCat
        return
    }
    $words = @($q -split '\s+' | Where-Object { $_ })
    $hl = Hub-Tint 34
    $cnt = @{}; $total = 0; $hdrOn = @{}
    foreach ($it in $script:HubItems) {
        $ok = $script:HubSaved[$it.El] -eq 'Visible'
        if ($ok) { foreach ($w in $words) { if ($it.Text.IndexOf($w) -lt 0) { $ok = $false; break } } }
        if ($ok) {
            $it.El.Visibility = 'Visible'; Hub-SetBg $it.El $hl
            $total++; $cnt[$it.Cat] = 1 + [int]$cnt[$it.Cat]
            if ($it.Hdr) { $hdrOn[$it.Hdr] = 1 }
        } else { $it.El.Visibility = 'Collapsed'; Hub-SetBg $it.El $it.Bg }
    }
    foreach ($it in $script:HubItems) { if ($it.Hdr) { if ($hdrOn.ContainsKey($it.Hdr)) { $it.Hdr.Visibility = 'Visible' } else { $it.Hdr.Visibility = 'Collapsed' } } }
    foreach ($g in @($ExpGrpStab, $ExpGrpPick, $ExpGrpSpeed, $ExpGrpGame)) { if ($g) { $g.Visibility = 'Visible' } }
    if ($script:HubEgBar) { $script:HubEgBar.Visibility = 'Collapsed' }
    foreach ($k in @($script:HubSec.Keys)) {
        $c = [int]$cnt[$k]; $p = $script:HubSec[$k].Panel; $n = $script:HubNav[$k]
        if ($c -gt 0) {
            if ($p.Visibility -ne 'Visible') { $p.Visibility = 'Visible'; Hub-Fade $p 0 10 }
            $n.Badge.Visibility = 'Visible'; $n.BadgeT.Text = [string]$c; $n.B.Opacity = 1
        } else { $p.Visibility = 'Collapsed'; $n.Badge.Visibility = 'Collapsed'; $n.B.Opacity = 0.4 }
    }
    Hub-PaintNav
    $SetScroll.ScrollToTop()
    if ($total -eq 0) { $SetNoHits.Visibility = 'Visible'; $SetFound.Text = 'Ничего не нашлось' }
    else { $SetNoHits.Visibility = 'Collapsed'; $SetFound.Text = ('Найдено: {0}' -f $total) }
}
function Hub-SyncPing {
    if ($LiveText.Text) {
        $SetPingText.Text = $LiveText.Text; $SetPingText.Foreground = $LiveText.Foreground; try { Pretty-Ping $SetPingText } catch { }
    } else {
        $SetPingText.Text = '● Пинг ещё не проверяли — нажмите «Пинг»'
        $SetPingText.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
    }
    $SetPingText.ToolTip = $SetPingText.Text
}
function Open-Hub([string]$cat) {
    if ($cat) { $script:HubCat = $cat }
    if (-not $script:HubReady) { return }
    if (-not $TabSet.IsChecked) { $TabSet.IsChecked = $true; return }   # дальше нас позовёт Show-Page 'set'
    if ($SetHub.Visibility -ne 'Visible') {
        $script:HubHidden = @{}
        foreach ($ch in @($MainArea.Children)) { if ($ch -ne $SetHub) { $script:HubHidden[$ch] = [string]$ch.Visibility; $ch.Visibility = 'Hidden' } }
        $SetHub.Visibility = 'Visible'
        Hub-Fade $SetHub 0 18
    }
    Hub-Select $script:HubCat
    Hub-SyncPing
}
function Close-Hub([switch]$KeepTab) {
    if ($SetHub.Visibility -ne 'Visible') { return }
    if ($script:HubQuery) { $SetSearch.Text = ''; Hub-Search '' }
    $SetHub.Visibility = 'Collapsed'
    foreach ($ch in @($MainArea.Children)) {
        if ($ch -ne $SetHub) { $v = $script:HubHidden[$ch]; if ($v) { $ch.Visibility = $v } else { $ch.Visibility = 'Visible' } }
    }
    $script:HubHidden = @{}
    if (-not $KeepTab) { if ($script:HubPrev -eq 'help') { $TabHelp.IsChecked = $true } else { $TabLog.IsChecked = $true } }
}

function Init-SetHub {
    $lookSp = $PageLook.Child.Content; $fontSp = $PageFont.Child.Content; $expSp = $PageExp.Child.Content
    $p = $EgStab.Parent; while ($p -and -not ($p -is [Windows.Controls.Border])) { $p = $p.Parent }; $script:HubEgBar = $p
    $cats = @(
        @{ k = 'main'; ic = '⚙️'; t = 'Основное'; s = 'Трей, автозапуск, звук'; a = 'основное общее трей автозапуск запуск выход'
           d = 'То, что нужно каждый день: как приложение запускается, сворачивается в трей и что делает при выходе.'; el = @($SetGrpMain); rows = @($SetGrpMain) }
        @{ k = 'net'; ic = '📡'; t = 'Связь и пинг'; s = 'Пинг, слежение, автосмена'; a = 'связь пинг сеть интернет слежение мониторинг'
           d = 'Как часто мерить пинг, следить за связью и что делать, если сервис вдруг перестал открываться.'; el = @($SetGrpNet); rows = @($SetGrpNet) }
        @{ k = 'look'; ic = '🎨'; t = 'Оформление'; s = 'Цвет, фон, заставка'; a = 'оформление тема цвет фон дизайн заставка вид'
           d = 'Акцентный цвет, прозрачность, фоны, свечение и заставка при запуске.'; el = @($lookSp); rows = @($lookSp) }
        @{ k = 'font'; ic = '🔤'; t = 'Шрифт'; s = 'Гарнитура и размер'; a = 'шрифт текст размер буквы масштаб'
           d = 'Шрифт интерфейса и его масштаб — чтобы читалось комфортно на любом мониторе.'; el = @($fontSp); rows = @($fontSp) }
        @{ k = 'sys'; ic = '🖥️'; t = 'Система и скорость'; s = 'Производительность, конфиг'; a = 'система производительность скорость ускорение конфиг папка'
           d = 'Производительность интерфейса, ускорение стратегий, экспорт и импорт настроек, папки программы.'; el = @($SetGrpSys); rows = @($SetGrpSys) }
        @{ k = 'exp'; ic = '⚗️'; t = 'Экспериментальное'; s = 'Быстро, резко, рискованно'; warn = $true; a = 'экспериментальное эксперимент риск турбо геймрежим мгновенное'
