# ---- сборка 8: родные функции (энергосбережение winws, очистка памяти, уровень звука для живых фонов)
$script:ZsNativeSrc = @'
using System;
using System.Runtime.InteropServices;
namespace ZS8 {
  public static class Native {
    [StructLayout(LayoutKind.Sequential)] struct PPTS { public uint Version; public uint ControlMask; public uint StateMask; }
    [DllImport("kernel32.dll", SetLastError = true)] static extern bool SetProcessInformation(IntPtr h, int cls, ref PPTS info, int size);
    [DllImport("kernel32.dll")] static extern bool SetProcessWorkingSetSize(IntPtr h, IntPtr mn, IntPtr mx);
    [DllImport("kernel32.dll")] static extern IntPtr GetCurrentProcess();
    public static bool NoThrottle(IntPtr h) {
      try {
        PPTS s = new PPTS(); s.Version = 1; s.ControlMask = 5; s.StateMask = 0;
        if (SetProcessInformation(h, 4, ref s, Marshal.SizeOf(typeof(PPTS)))) return true;
        s.ControlMask = 1; return SetProcessInformation(h, 4, ref s, Marshal.SizeOf(typeof(PPTS)));
      } catch { return false; }
    }
    public static void Trim() { try { SetProcessWorkingSetSize(GetCurrentProcess(), new IntPtr(-1), new IntPtr(-1)); } catch { } }
  }
  [ComImport, Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")] class MMDevEnumCo { }
  [ComImport, Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IMMDeviceEnumerator {
    [PreserveSig] int EnumAudioEndpoints(int dataFlow, int stateMask, out IntPtr devices);
    [PreserveSig] int GetDefaultAudioEndpoint(int dataFlow, int role, out IMMDevice endpoint);
  }
  [ComImport, Guid("D666063F-1587-4E43-81F1-B948E807363F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IMMDevice {
    [PreserveSig] int Activate(ref Guid iid, int clsCtx, IntPtr p, [MarshalAs(UnmanagedType.IUnknown)] out object o);
  }
  [ComImport, Guid("C02216F6-8C67-4B5B-9D00-D008E73E0064"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioMeterInformation { [PreserveSig] int GetPeakValue(out float peak); }
  public static class Meter {
    static IAudioMeterInformation m; static DateTime t = DateTime.MinValue;
    public static float Peak() {
      try {
        if (m == null || (DateTime.UtcNow - t).TotalSeconds > 8) {
          m = null; t = DateTime.UtcNow;
          IMMDeviceEnumerator e = (IMMDeviceEnumerator)(new MMDevEnumCo());
          IMMDevice d;
          if (e.GetDefaultAudioEndpoint(0, 1, out d) != 0 || d == null) return 0f;
          Guid g = typeof(IAudioMeterInformation).GUID; object o;
          if (d.Activate(ref g, 23, IntPtr.Zero, out o) != 0 || o == null) return 0f;
          m = (IAudioMeterInformation)o;
        }
        float p;
        if (m.GetPeakValue(out p) != 0) { m = null; return 0f; }
        return p;
      } catch { m = null; return 0f; }
    }
  }
}
'@
$script:ZsNative = $null
function Ensure-ZsNative {
    if ($null -ne $script:ZsNative) { return [bool]$script:ZsNative }
    try { Add-Type -TypeDefinition $script:ZsNativeSrc -ErrorAction Stop; $script:ZsNative = $true }
    catch { $script:ZsNative = $false; try { Log ('Родные функции недоступны: ' + $_.Exception.Message) } catch { } }
    [bool]$script:ZsNative
}

# ---- стабильность winws: приоритет выше обычного и без «режима эффективности» Windows 11
$script:TunedPids = @{}
$script:TuneTick = 0
function Tune-Winws {
    $script:TuneTick++
    if (($script:TuneTick % 5) -ne 1) { return }
    $want = 'AboveNormal'
    if ($Cfg.ExpGame -and $script:GameActive) { $want = 'High' }
    foreach ($p in [Diagnostics.Process]::GetProcessesByName('winws')) {
        try {
            $pc = [string]$p.PriorityClass
            if ($pc -ne $want -and $pc -ne 'High' -and $pc -ne 'RealTime') { $p.PriorityClass = $want }
            if (-not $script:TunedPids.ContainsKey($p.Id)) {
                $script:TunedPids[$p.Id] = $true
                if (Ensure-ZsNative) { if ([ZS8.Native]::NoThrottle($p.Handle)) { Log 'Стабильность: winws работает без энергосбережения Windows' } }
            }
        } catch { }
        try { $p.Dispose() } catch { }
    }
}

