$script:BgPaused = $false
function Bg-Idle {
    $idle = $false
    try { $idle = (-not $Win.IsVisible) -or ($Win.WindowState -eq 'Minimized') -or [bool]$script:GameActive } catch { }
    if ($idle -eq [bool]$script:BgPaused) { return }
    $script:BgPaused = $idle
    if ($idle) {
        try { Stop-LiveBg } catch { }
        try { $BgFx.Children.Clear() } catch { }
        try { $script:SloganTm.Stop() } catch { }
        try { if ($StatusTimer) { $StatusTimer.Interval = [TimeSpan]::FromMilliseconds(2500) } } catch { }
        if (-not $script:GameActive) { try { [Diagnostics.Process]::GetCurrentProcess().PriorityClass = 'BelowNormal' } catch { } }
        try { [GC]::Collect(); [GC]::WaitForPendingFinalizers(); if (Ensure-ZsNative) { [ZS8.Native]::Trim() } } catch { }
    } else {
        if (-not $script:GameActive) { try { [Diagnostics.Process]::GetCurrentProcess().PriorityClass = 'Normal' } catch { } }
        try { if ($StatusTimer) { $StatusTimer.Interval = [TimeSpan]::FromMilliseconds(1000) } } catch { }
        try { $script:SloganTm.Start() } catch { }
        try { Apply-BgFx } catch { }
    }
}

