# ---- плавный переход к настройке, которая блокирует другую
$script:GoTm = New-Object Windows.Threading.DispatcherTimer
$script:GoTm.Interval = [TimeSpan]::FromMilliseconds(15)
$script:GoFrom = 0.0; $script:GoTo = 0.0; $script:GoT0 = [DateTime]::Now; $script:GoCtl = $null
$script:GoTm.Add_Tick({
    $t = ([DateTime]::Now - $script:GoT0).TotalMilliseconds / 420.0
    if ($t -ge 1) { $t = 1; $script:GoTm.Stop() }
    $k = 1 - [Math]::Pow(1 - $t, 3)
    try { $SetScroll.ScrollToVerticalOffset($script:GoFrom + ($script:GoTo - $script:GoFrom) * $k) } catch { $script:GoTm.Stop() }
})
function Hub-Flash($row) {
    try {
        try { $ac = ToColor ([string]$Cfg.Accent) } catch { $ac = [Windows.Media.Color]::FromRgb(124, 92, 255) }
        if ($Cfg.Perf) { return }
        $b = New-Object Windows.Media.SolidColorBrush ([Windows.Media.Color]::FromArgb(0, $ac.R, $ac.G, $ac.B))
        if ($row -is [Windows.Controls.Panel]) { $row.Background = $b } elseif ($row -is [Windows.Controls.Control]) { $row.Background = $b } else { return }
        $a = New-Object Windows.Media.Animation.ColorAnimation
        $a.From = [Windows.Media.Color]::FromArgb(90, $ac.R, $ac.G, $ac.B); $a.To = [Windows.Media.Color]::FromArgb(0, $ac.R, $ac.G, $ac.B)
        $a.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(700))
        $a.BeginTime = [TimeSpan]::FromMilliseconds(300)
        $a.RepeatBehavior = New-Object Windows.Media.Animation.RepeatBehavior 3.0
        $b.BeginAnimation([Windows.Media.SolidColorBrush]::ColorProperty, $a)
    } catch { }
}
function Hub-GoScroll {
    try {
        $c = $script:GoCtl; if (-not $c) { return }
        $row = $c; if ($c.Parent -is [Windows.Controls.Panel]) { $row = $c.Parent }
        $SetScroll.UpdateLayout()
        $y = $row.TranslatePoint((New-Object Windows.Point 0, 0), $SetScroll).Y + $SetScroll.VerticalOffset
        $to = [Math]::Max(0, [Math]::Min($SetScroll.ScrollableHeight, $y - ($SetScroll.ViewportHeight * 0.3)))
        if ($Cfg.Perf) { $SetScroll.ScrollToVerticalOffset($to) }
        else { $script:GoFrom = $SetScroll.VerticalOffset; $script:GoTo = $to; $script:GoT0 = [DateTime]::Now; $script:GoTm.Start() }
        Hub-Flash $row
        try { [void]$c.Focus() } catch { }
    } catch { }
}
function Hub-Goto([string]$cat, $ctl, $pre) {
    try {
        if ($script:HubQuery) { $SetSearch.Text = ''; Hub-Search '' }
        Open-Hub $cat
        if ($pre -is [scriptblock]) { & $pre }
        $script:GoCtl = $ctl
        [void]$Win.Dispatcher.BeginInvoke([Action]{ Hub-GoScroll }, [Windows.Threading.DispatcherPriority]::Loaded)
    } catch { }
}

# ---- вкладки на всю ширину и скользящая плашка под активной
function Move-TabPill([bool]$anim) {
    try {
        if (-not $TabPill -or -not $TabGrid) { return }
        $rb = $null
        foreach ($t in @($TabLog, $TabSet, $TabHelp, $TabLook, $TabFont, $TabExp)) { if ($t -and $t.IsChecked -and $t.Visibility -eq 'Visible') { $rb = $t } }
        if (-not $rb -or $rb.ActualWidth -lt 1) { $TabPill.Opacity = 0; return }
        $TabPill.Opacity = 1
        $x = $rb.TranslatePoint((New-Object Windows.Point 0, 0), $TabGrid).X; $w = $rb.ActualWidth
        $tt = $TabPill.RenderTransform
        if ($anim -and -not $Cfg.Perf -and $TabPill.Width -gt 1) {
            $ez = New-Object Windows.Media.Animation.CubicEase; $ez.EasingMode = 'EaseInOut'
            $tt.BeginAnimation([Windows.Media.TranslateTransform]::XProperty, (New-Anim4 ([double]::NaN) $x 320 0 $ez))
            $TabPill.BeginAnimation([Windows.FrameworkElement]::WidthProperty, (New-Anim4 ([double]::NaN) $w 320 0 $ez))
        } else {
            $tt.BeginAnimation([Windows.Media.TranslateTransform]::XProperty, $null); $TabPill.BeginAnimation([Windows.FrameworkElement]::WidthProperty, $null)
            $tt.X = $x; $TabPill.Width = $w
        }
    } catch { }
}
foreach ($tb in @($TabLog, $TabSet, $TabHelp, $TabLook, $TabFont, $TabExp)) {
    if ($tb) { $tb.Add_Checked({ try { [void]$Win.Dispatcher.BeginInvoke([Action]{ Move-TabPill $true }, [Windows.Threading.DispatcherPriority]::Loaded) } catch { } }) }
}
