        $t = New-Object System.Windows.Controls.TextBlock; $t.Text = $l[1]; $t.TextWrapping = 'Wrap'; $t.Margin = New-Object System.Windows.Thickness 0, 0, 0, 8
        $t.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
        [void]$OnbLic.Children.Add($h); [void]$OnbLic.Children.Add($t)
    }
    $tour = @(
        @('▶️', 'Одна кнопка', 'Большой шар в центре включает и выключает обход. Под ним виден пинг до ваших сервисов.'),
        @('🎯', 'Подбор делает всё сам', 'Программа сама проверит стратегии и поставит первой самую быструю из рабочих.'),
