        @('⚗️', 'Экспериментальное', 'Для смелых: мгновенное переключение, анти-душилка, ускорение. Если одна настройка блокирует другую, это подсвечено.'),
        @('🎨', 'Под себя', 'Цвета, фоны, шрифты, заставки и простой режим. Настройки сохраняются даже после обновления.'),
        @('📖', 'Всё описано', 'Во вкладке «Инструкция» наведите на любую карточку, и появится подробное объяснение.')
    )
    foreach ($r in $tour) {
