        $b.SetResourceReference([Windows.Controls.Border]::BackgroundProperty, 'PanelBrush'); $b.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'StrokeBrush')
        $d = New-Object System.Windows.Controls.DockPanel
        $ic = New-Object System.Windows.Controls.TextBlock; $ic.Text = $r[0]; $ic.FontFamily = New-Object System.Windows.Media.FontFamily 'Segoe UI Emoji'; $ic.FontSize = 20; $ic.Margin = New-Object System.Windows.Thickness 0, 0, 12, 0; $ic.VerticalAlignment = 'Center'
        [System.Windows.Controls.DockPanel]::SetDock($ic, 'Left'); [void]$d.Children.Add($ic)
        $sp = New-Object System.Windows.Controls.StackPanel
        $t1 = New-Object System.Windows.Controls.TextBlock; $t1.Text = $r[1]; $t1.FontWeight = 'SemiBold'
        $t2 = New-Object System.Windows.Controls.TextBlock; $t2.Text = $r[2]; $t2.TextWrapping = 'Wrap'; $t2.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush'); $t2.SetResourceReference([Windows.Controls.TextBlock]::FontSizeProperty, 'Fs11')
        [void]$sp.Children.Add($t1); [void]$sp.Children.Add($t2); [void]$d.Children.Add($sp)
