}
function Onb-Anim($el, $prop, [double]$from, [double]$to, [int]$ms, [int]$delay = 0) {
    $a = New-Object Windows.Media.Animation.DoubleAnimation $from, $to, ([TimeSpan]::FromMilliseconds($ms))
    $a.BeginTime = [TimeSpan]::FromMilliseconds($delay)
    $ce = New-Object Windows.Media.Animation.CubicEase; $ce.EasingMode = 'EaseOut'; $a.EasingFunction = $ce
    $el.BeginAnimation($prop, $a)
}
function Onb-Go([int]$n) {
    $script:OnbStep = $n
    $OnbStep1.Visibility = $(if ($n -eq 1) { 'Visible' } else { 'Collapsed' })
    $OnbStep2.Visibility = $(if ($n -eq 2) { 'Visible' } else { 'Collapsed' })
    $OnbStep3.Visibility = $(if ($n -eq 3) { 'Visible' } else { 'Collapsed' })
    $OnbStepText.Text = ('ШАГ {0} ИЗ 3' -f $n)
    $i = 0
    foreach ($dt in @($OnbDot1, $OnbDot2, $OnbDot3)) {
        $i++
        if ($i -eq $n) { $dt.Width = 26; $dt.SetResourceReference([Windows.Controls.Border]::BackgroundProperty, 'AccentBrush'); $dt.Opacity = 1 }
        elseif ($i -lt $n) { $dt.Width = 10; $dt.SetResourceReference([Windows.Controls.Border]::BackgroundProperty, 'AccentBrush'); $dt.Opacity = 0.5 }
        else { $dt.Width = 10; $dt.SetResourceReference([Windows.Controls.Border]::BackgroundProperty, 'StrokeBrush'); $dt.Opacity = 1 }
    }
    switch ($n) {
        1 { $OnbBack.Visibility = 'Visible'; $OnbBack.Content = 'Не принимаю'; $OnbNext.Content = 'Принимаю и продолжаю'; $OnbNext.IsEnabled = [bool]$OnbAgree.IsChecked }
        2 { $OnbBack.Visibility = 'Visible'; $OnbBack.Content = 'Назад'; $OnbNext.Content = 'Понятно'; $OnbNext.IsEnabled = $true }
        3 { $OnbBack.Visibility = 'Hidden'; $OnbNext.Content = 'Поехали! 🚀'; $OnbNext.IsEnabled = $true }
    }
    if (-not $Cfg.Perf) {
        Onb-Anim $OnbSlide ([Windows.Media.TranslateTransform]::XProperty) 46 0 380
        Onb-Anim $OnbBody ([Windows.UIElement]::OpacityProperty) 0 1 300
    }
    if ($n -eq 2) {
        $k = 0
        foreach ($c in $OnbTour.Children) {
            if ($Cfg.Perf) { $c.Opacity = 1; continue }
            $tt = New-Object Windows.Media.TranslateTransform; $c.RenderTransform = $tt
            Onb-Anim $c ([Windows.UIElement]::OpacityProperty) 0 1 360 (120 + 90 * $k)
            Onb-Anim $tt ([Windows.Media.TranslateTransform]::YProperty) 14 0 420 (120 + 90 * $k)
            $k++
        }
    }
    if ($n -eq 3) { Onb-Party }
}
function Onb-Party {
    try {
        $OnbFx.Children.Clear()
        if ($Cfg.Perf) {
            $OnbShieldScale.ScaleX = 1; $OnbShieldScale.ScaleY = 1; $OnbCheck.StrokeDashOffset = 0; $OnbLuck.Opacity = 1; $OnbLuckSub.Opacity = 1; return
        }
        $bk = New-Object Windows.Media.Animation.ElasticEase; $bk.EasingMode = 'EaseOut'; $bk.Oscillations = 2; $bk.Springiness = 5
        foreach ($pp in @([Windows.Media.ScaleTransform]::ScaleXProperty, [Windows.Media.ScaleTransform]::ScaleYProperty)) {
            $a = New-Object Windows.Media.Animation.DoubleAnimation 0, 1, ([TimeSpan]::FromMilliseconds(1100)); $a.EasingFunction = $bk; $a.BeginTime = [TimeSpan]::FromMilliseconds(150)
            $OnbShieldScale.BeginAnimation($pp, $a)
            $h = New-Object Windows.Media.Animation.DoubleAnimation 0.85, 1.25, ([TimeSpan]::FromMilliseconds(1400)); $h.AutoReverse = $true; $h.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
            $se = New-Object Windows.Media.Animation.SineEase; $se.EasingMode = 'EaseInOut'; $h.EasingFunction = $se
            $OnbHaloScale.BeginAnimation($pp, $h)
        }
        Onb-Anim $OnbCheck ([Windows.Shapes.Shape]::StrokeDashOffsetProperty) 10 0 520 850
        Onb-Anim $OnbLuck ([Windows.UIElement]::OpacityProperty) 0 1 600 1000
        Onb-Anim $OnbLuckSub ([Windows.UIElement]::OpacityProperty) 0 1 600 1350
        # конфетти из центра — взрыв свободы
        $W = 580; $H = 330; $cx = $W / 2; $cy = 95
        $acc = $Win.Resources['AccentBrush'].Color
        $cols = @($acc, [Windows.Media.Color]::FromRgb(255, 255, 255), [Windows.Media.Color]::FromRgb(250, 204, 21), [Windows.Media.Color]::FromRgb(34, 211, 238), [Windows.Media.Color]::FromRgb(244, 114, 182))
        $rnd = New-Object System.Random
        for ($q = 0; $q -lt 64; $q++) {
            $r = New-Object Windows.Shapes.Rectangle
            $r.Width = 4 + $rnd.Next(6); $r.Height = 6 + $rnd.Next(8); $r.RadiusX = 1.5; $r.RadiusY = 1.5
            $r.Fill = New-Object Windows.Media.SolidColorBrush ($cols[$rnd.Next($cols.Count)])
            $r.RenderTransformOrigin = New-Object Windows.Point 0.5, 0.5
            $tg = New-Object Windows.Media.TransformGroup
            $rt = New-Object Windows.Media.RotateTransform; $tt = New-Object Windows.Media.TranslateTransform
            [void]$tg.Children.Add($rt); [void]$tg.Children.Add($tt); $r.RenderTransform = $tg
            [Windows.Controls.Canvas]::SetLeft($r, $cx); [Windows.Controls.Canvas]::SetTop($r, $cy)
            $r.Opacity = 0
            [void]$OnbFx.Children.Add($r)
            $ang = $rnd.NextDouble() * [Math]::PI * 2; $sp = 120 + $rnd.NextDouble() * 200
            $dx = [Math]::Cos($ang) * $sp; $dyUp = [Math]::Sin($ang) * $sp * 0.7 - 60
            $dl = 300 + $rnd.Next(250); $dur = 1600 + $rnd.Next(1200)
            $kx = New-Object Windows.Media.Animation.DoubleAnimation 0, $dx, ([TimeSpan]::FromMilliseconds($dur))
            $qe = New-Object Windows.Media.Animation.QuadraticEase; $qe.EasingMode = 'EaseOut'; $kx.EasingFunction = $qe; $kx.BeginTime = [TimeSpan]::FromMilliseconds($dl)
            $tt.BeginAnimation([Windows.Media.TranslateTransform]::XProperty, $kx)
            $ky = New-Object Windows.Media.Animation.DoubleAnimationUsingKeyFrames; $ky.BeginTime = [TimeSpan]::FromMilliseconds($dl)
            $k1 = New-Object Windows.Media.Animation.EasingDoubleKeyFrame $dyUp, ([Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds($dur * 0.35)))
            $e1 = New-Object Windows.Media.Animation.QuadraticEase; $e1.EasingMode = 'EaseOut'; $k1.EasingFunction = $e1
            $k2 = New-Object Windows.Media.Animation.EasingDoubleKeyFrame ($H - $cy + 20), ([Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds($dur)))
            $e2 = New-Object Windows.Media.Animation.QuadraticEase; $e2.EasingMode = 'EaseIn'; $k2.EasingFunction = $e2
            [void]$ky.KeyFrames.Add($k1); [void]$ky.KeyFrames.Add($k2)
            $tt.BeginAnimation([Windows.Media.TranslateTransform]::YProperty, $ky)
            $ra = New-Object Windows.Media.Animation.DoubleAnimation 0, (360 * (1 + $rnd.Next(3)) * $(if ($rnd.Next(2)) { 1 } else { -1 })), ([TimeSpan]::FromMilliseconds($dur)); $ra.BeginTime = [TimeSpan]::FromMilliseconds($dl)
            $rt.BeginAnimation([Windows.Media.RotateTransform]::AngleProperty, $ra)
            $oa = New-Object Windows.Media.Animation.DoubleAnimationUsingKeyFrames; $oa.BeginTime = [TimeSpan]::FromMilliseconds($dl)
            [void]$oa.KeyFrames.Add((New-Object Windows.Media.Animation.LinearDoubleKeyFrame 1, ([Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(60)))))
            [void]$oa.KeyFrames.Add((New-Object Windows.Media.Animation.LinearDoubleKeyFrame 1, ([Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds($dur * 0.75)))))
            [void]$oa.KeyFrames.Add((New-Object Windows.Media.Animation.LinearDoubleKeyFrame 0, ([Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds($dur)))))
            $r.BeginAnimation([Windows.UIElement]::OpacityProperty, $oa)
        }
    } catch { }
}
function Show-Onboarding {
    try {
        Onb-Fill
        $script:OnbActive = $true
        $PrioPanel.Visibility = 'Collapsed'; $ResultPanel.Visibility = 'Collapsed'; $RenamePanel.Visibility = 'Collapsed'; $AboutPanel.Visibility = 'Collapsed'
        $OnbPanel.Visibility = 'Visible'; $Overlay.Visibility = 'Visible'
        Onb-Go 1
        if (-not $Cfg.Perf) {
            $bk = New-Object Windows.Media.Animation.BackEase; $bk.EasingMode = 'EaseOut'; $bk.Amplitude = 0.3
            foreach ($pp in @([Windows.Media.ScaleTransform]::ScaleXProperty, [Windows.Media.ScaleTransform]::ScaleYProperty)) {
                $a = New-Object Windows.Media.Animation.DoubleAnimation 0.86, 1, ([TimeSpan]::FromMilliseconds(520)); $a.EasingFunction = $bk; $OnbScale.BeginAnimation($pp, $a)
            }
            Onb-Anim $OnbPanel ([Windows.UIElement]::OpacityProperty) 0 1 380
        }
    } catch { $script:OnbActive = $false }
}
function Close-Onboarding {
    $script:OnbActive = $false
    $OnbPanel.Visibility = 'Collapsed'; $Overlay.Visibility = 'Collapsed'
    $OnbFx.Children.Clear()
}
