function Tidy-Headers {
    # если под заголовком всего одна карточка с тем же названием, заголовок лишний: прячем, текста становится меньше
    $by = @{}
    foreach ($it in @($script:HubItems)) {
        if (-not $it.Hdr) { continue }
        $el = $it.El
        if (($el -is [Windows.Controls.Panel]) -and -not ($el -is [Windows.Controls.Grid]) -and $el.Children.Count -eq 0) { continue }
        if ([string]$el.Visibility -eq 'Collapsed') { continue }
        if (-not $by.ContainsKey($it.Hdr)) { $by[$it.Hdr] = New-Object Collections.ArrayList }
        [void]$by[$it.Hdr].Add($el)
    }
    foreach ($h in @($by.Keys)) {
        $els = $by[$h]; if ($els.Count -ne 1) { continue }
        $el = $els[0]; if (-not ($el -is [Windows.Controls.Grid]) -or $el.Children.Count -eq 0) { continue }
        $sp = $el.Children[0]; if (-not ($sp -is [Windows.Controls.StackPanel]) -or $sp.Children.Count -eq 0) { continue }
        if (-not ($h -is [Windows.Controls.Panel]) -or $h.Children.Count -eq 0) { continue }
        $ht = ([string]$h.Children[0].Text).Trim().ToLowerInvariant(); $rt = ([string]$sp.Children[0].Text).Trim().ToLowerInvariant()
        if ($ht -and $rt.StartsWith($ht)) { $h.Visibility = 'Collapsed' }
    }
}
