function Ensure-AllDetails {
    foreach ($tn in @($script:ToggleNames)) {
        $cb = $null; try { $cb = $Win.FindName($tn) } catch { }
        if (-not $cb -or -not ($cb.Parent -is [Windows.Controls.Grid])) { continue }
        $sp = $cb.Parent.Children[0]
        if (-not ($sp -is [Windows.Controls.StackPanel])) { continue }
        $has = $false
        foreach ($ch in @($sp.Children)) { if ($ch -is [Windows.Controls.TextBlock] -and [string]$ch.Tag -eq 'zs-det') { $has = $true } }
        if ($has) { continue }
        $t = [string]$script:DetailText[$tn]
        if (-not $t) {
            # запасной вариант: полное короткое описание, чтобы «Подробнее» было у всех
            if ($sp.Children.Count -gt 1 -and $sp.Children[1] -is [Windows.Controls.TextBlock]) { $t = [string]$sp.Children[1].Text }
        }
        if ($t) { try { Add-RowDetail $sp $t } catch { } }
    }
}
