# ---- сборка 12 (1.1.0): предупреждение версии разработчика, красивый пинг, статус в трее, итог сессии, VPN
function Get-PingHex([int]$ms) { if ($ms -lt 90) { '#22C55E' } elseif ($ms -lt 160) { '#F59E0B' } else { '#EF4444' } }
function New-PRun([string]$t, [string]$hex, [string]$res, [bool]$bold) {
    $r = New-Object Windows.Documents.Run $t
    if ($hex) { $r.Foreground = New-Brush (ToColor $hex) } elseif ($res) { $r.SetResourceReference([Windows.Documents.TextElement]::ForegroundProperty, $res) }
    if ($bold) { $r.FontWeight = 'SemiBold' }
    $r
}
$script:PingHist = New-Object System.Collections.ArrayList
$script:Sess = $null; $script:VpnWarned = $false
function Push-PingHist([int]$ms) {
    [void]$script:PingHist.Add($ms)
    while ($script:PingHist.Count -gt 14) { $script:PingHist.RemoveAt(0) }
    if ($script:Sess) { $script:Sess.N++; $script:Sess.Sum += $ms; if ($ms -lt $script:Sess.Min) { $script:Sess.Min = $ms } }
    try { Update-TrayText } catch { }
}
function Pretty-Ping($tb) {
    if (-not $tb) { return }
    $txt = [string]$tb.Text
    if (-not $txt -or $txt -notmatch 'мс|нет ответа') { return }
    $segs = @($txt -split '\s+·\s+|:\s+(?=\S)')
    $tb.Inlines.Clear()
    $emo = New-Object Windows.Media.FontFamily 'Segoe UI Emoji'
    $n = 0
    foreach ($sg in $segs) {
        $sg = ([string]$sg).Trim(); if (-not $sg) { continue }
        if ($n -gt 0) { [void]$tb.Inlines.Add((New-PRun '   ' '' 'SubBrush' $false)) }
        $n++
        if ($sg -match '^●?\s*Пинг\b(.*)$') {
            $rest = $Matches[1].Trim()
            $ic = New-PRun ([char]::ConvertFromUtf32(0x1F4F6) + ' ') '' '' $false; $ic.FontFamily = $emo
            [void]$tb.Inlines.Add($ic)
            [void]$tb.Inlines.Add((New-PRun 'Пинг' '' 'TextBrush' $true))
            if ($rest) { [void]$tb.Inlines.Add((New-PRun (' ' + $rest) '' 'SubBrush' $false)) }
            continue
        }
        if ($sg -match '^(.+?)\s+(\d+)\s*мс(.*)$') {
            $nm = $Matches[1]; $ms = [int]$Matches[2]; $rest = $Matches[3]; $hx = Get-PingHex $ms
            [void]$tb.Inlines.Add((New-PRun '● ' $hx '' $false))
            [void]$tb.Inlines.Add((New-PRun ($nm + ' ') '' 'TextBrush' $true))
            [void]$tb.Inlines.Add((New-PRun ([string]$ms) $hx '' $true))
            [void]$tb.Inlines.Add((New-PRun (' мс' + $rest) '' 'SubBrush' $false))
            continue
        }
        if ($sg -match '^(.+?)\s+нет ответа$') {
            $nm = $Matches[1]
            [void]$tb.Inlines.Add((New-PRun '● ' '#EF4444' '' $false))
            [void]$tb.Inlines.Add((New-PRun ($nm + ' ') '' 'TextBrush' $true))
            [void]$tb.Inlines.Add((New-PRun 'нет ответа' '#EF4444' '' $true))
            continue
        }
        [void]$tb.Inlines.Add((New-PRun $sg '' 'SubBrush' $false))
    }
    # мини-график последних проверок - в той же строке
    if ([string]$tb.Name -eq 'LiveText' -and $script:PingHist.Count -ge 3) {
        $mx = 60; foreach ($v in $script:PingHist) { if ($v -gt $mx) { $mx = $v } }
        $bars = New-Object Windows.Controls.StackPanel; $bars.Orientation = 'Horizontal'; $bars.Height = 12; $bars.Margin = New-Object Windows.Thickness 10, 0, 0, 0
        foreach ($v in $script:PingHist) {
            $rc = New-Object Windows.Shapes.Rectangle
            $rc.Width = 3; $rc.Height = [Math]::Max(2, [Math]::Round(12.0 * $v / $mx)); $rc.VerticalAlignment = 'Bottom'
            $rc.Margin = New-Object Windows.Thickness 0, 0, 1, 0; $rc.RadiusX = 1; $rc.RadiusY = 1; $rc.Opacity = 0.85
            $rc.Fill = New-Brush (ToColor (Get-PingHex $v))
            [void]$bars.Children.Add($rc)
        }
        $bars.ToolTip = 'Пинг за последние проверки (лучший сервис)'
        $uc = New-Object Windows.Documents.InlineUIContainer $bars
        $uc.BaselineAlignment = 'Center'
        [void]$tb.Inlines.Add($uc)
    }
}
function Format-Dur([TimeSpan]$d) {
    if ($d.TotalMinutes -lt 1) { return 'меньше минуты' }
    $h = [int][Math]::Floor($d.TotalHours)
    if ($h -gt 0) { return ('{0} ч {1} мин' -f $h, $d.Minutes) }
    ('{0} мин' -f [int][Math]::Floor($d.TotalMinutes))
}
function Log-SessSummary {
    $s = $script:Sess; $script:Sess = $null
    if (-not $s) { return }
    $line = 'Итог сессии: обход работал ' + (Format-Dur ((Get-Date) - $s.Start))
    if ($s.N -gt 0) { $line += (' · средний пинг {0} мс (лучший {1})' -f [int]($s.Sum / $s.N), [int]$s.Min) }
    if ($s.Sw -gt 0) { $line += (' · смен стратегии: ' + $s.Sw) }
    Log $line 'ok'
}
function Check-Vpn {
    if ($script:VpnWarned) { return }
    $hits = @()
    foreach ($ni in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
        if ([string]$ni.OperationalStatus -ne 'Up') { continue }
        $dd = ([string]$ni.Description + ' ' + [string]$ni.Name)
        if ($dd -match 'WireGuard|OpenVPN|TAP-Windows|Wintun|Amnezia|Outline|NordLynx|ProtonVPN|Hiddify|sing-box|v2ray|Xray|Cloudflare WARP|Psiphon|Windscribe|Surfshark|ExpressVPN') { $hits += [string]$ni.Name }
    }
    if ($hits.Count -gt 0) {
        $script:VpnWarned = $true
        Log ('Включён VPN (' + (@($hits | Select-Object -First 2) -join ', ') + ') — он может мешать обходу. Если сайты не открываются, отключите VPN или обход.') 'warn'
    }
}

# ---- 2.0: установка zapret с GitHub прямо из заставки
function Install-ZapretFromFolder([string]$src, $sync) {
    try {
        $sync.Stage = 'Проверяю папку…'; $sync.Progress = 0.2
        $hasBin = Test-Path -LiteralPath (Join-Path $src 'bin')
        $bats = @(Get-ChildItem -LiteralPath $src -Filter 'general*.bat' -File -ErrorAction SilentlyContinue)
        if (-not $hasBin -and $bats.Count -eq 0) { throw 'в этой папке нет zapret — нужны bin и general*.bat' }
        $sync.Stage = 'Переношу файлы…'; $sync.Progress = 0.55
        Copy-Item -Path (Join-Path $src '*') -Destination $script:AppDir -Recurse -Force
        $sync.Progress = 1.0; $sync.Stage = 'Готово'
        try { Reload-Strategies; Rebuild-List } catch { }
        try { Log ('zapret перенесён из папки: ' + $src) 'ok' } catch { }
        $sync.Ok = $true
    } catch {
        $sync.Err = $_.Exception.Message; $sync.Fail = $true; $sync.Stage = 'Не удалось установить'
    }
}

function Expand-ZapretZip([string]$zip, $sync) {
    $tmpDir = Join-Path $env:TEMP ('zs-zapret-' + [guid]::NewGuid().ToString('N'))
    [void](New-Item -ItemType Directory -Path $tmpDir -Force)
    Expand-Archive -LiteralPath $zip -DestinationPath $tmpDir -Force
    $src = $tmpDir
    if (-not (Test-Path -LiteralPath (Join-Path $src 'bin'))) {
        $cand = @(Get-ChildItem -LiteralPath $tmpDir -Directory | Where-Object { Test-Path -LiteralPath (Join-Path $_.FullName 'bin') })
        if ($cand.Count -gt 0) { $src = $cand[0].FullName }
    }
    if (-not (Test-Path -LiteralPath (Join-Path $src 'bin'))) { throw 'в архиве не нашлась папка bin' }
    $sync.Stage = 'Устанавливаю файлы…'; $sync.Progress = 0.92
    Copy-Item -Path (Join-Path $src '*') -Destination $script:AppDir -Recurse -Force
    try { Remove-Item -LiteralPath $tmpDir -Recurse -Force -ErrorAction SilentlyContinue } catch { }
}

function Install-ZapretFromZip([string]$path, $sync) {
    try {
        $sync.Stage = 'Распаковываю архив…'; $sync.Progress = 0.25
        Expand-ZapretZip $path $sync
        $sync.Progress = 1.0; $sync.Stage = 'Готово'
        try { Reload-Strategies; Rebuild-List } catch { }
        try { Log 'zapret установлен из выбранного архива' 'ok' } catch { }
        $sync.Ok = $true
    } catch {
        $sync.Err = $_.Exception.Message; $sync.Fail = $true; $sync.Stage = 'Не удалось установить'
    }
}

function Install-ZapretZip($sync) {
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $sync.Stage = 'Ищу последнюю версию…'; $sync.Progress = 0.03
        $hdr = @{ 'User-Agent' = 'ZapretStudio/2.0'; 'Accept' = 'application/vnd.github+json' }
        $rel = Invoke-RestMethod -Uri 'https://api.github.com/repos/Flowseal/zapret-discord-youtube/releases/latest' -Headers $hdr -TimeoutSec 25
        $asset = @($rel.assets | Where-Object { $_.name -like '*.zip' })[0]
        if (-not $asset) { throw 'в последнем релизе нет zip-архива' }
        $url = [string]$asset.browser_download_url
        $tmpZip = Join-Path $env:TEMP ('zs-zapret-' + [guid]::NewGuid().ToString('N') + '.zip')
        $sync.Stage = 'Скачиваю zapret…'; $sync.Progress = 0.05
        $req = [Net.HttpWebRequest]::Create($url)
        $req.UserAgent = 'ZapretStudio/2.0'
        $req.Timeout = 60000
        $resp = $req.GetResponse()
        $total = [int64]$resp.ContentLength
        $inS = $resp.GetResponseStream()
        $outS = [IO.File]::Create($tmpZip)
        $buf = New-Object byte[] 131072
        $done = [int64]0
        while (($n = $inS.Read($buf, 0, $buf.Length)) -gt 0) {
            $outS.Write($buf, 0, $n)
            $done += $n
            if ($total -gt 0) { $sync.Progress = 0.05 + 0.75 * ($done / $total) }
        }
        $outS.Close(); $inS.Close(); $resp.Close()
        $sync.Stage = 'Распаковываю…'; $sync.Progress = 0.85
        Expand-ZapretZip $tmpZip $sync
        try { Remove-Item -LiteralPath $tmpZip -Force -ErrorAction SilentlyContinue } catch { }
        $sync.Progress = 1.0
        $sync.Stage = 'Готово'
        try { Reload-Strategies; Rebuild-List } catch { }
        try { Log 'zapret установлен с GitHub — стратегии готовы' 'ok' } catch { }
        $sync.Ok = $true
    } catch {
        $sync.Err = $_.Exception.Message
        $sync.Fail = $true
        $sync.Stage = 'Не удалось установить'
        try { Log ('Установка zapret не удалась: ' + $_.Exception.Message) 'err' } catch { }
    }
}

