    try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop; [void]$sb.AppendLine('Windows: ' + $os.Caption + ' ' + $os.Version + ' (' + $os.OSArchitecture + ')') } catch { [void]$sb.AppendLine('Windows: ' + [Environment]::OSVersion.VersionString) }
