    $st = 'выключен'; if ($script:Running) { $st = 'включён' }
    $sn = '—'; try { if ($script:Active) { $sn = Disp ([string]$script:Active) } elseif ($script:Selected) { $sn = Disp ([string]$script:Selected) } } catch { }
    [void]$sb.AppendLine('Обход: ' + $st + '; стратегия: ' + $sn)
    [void]$sb.AppendLine('Файлы: ' + $script:Integrity)
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine('--- журнал (последние 150 строк) ---')
    $li = @($script:LogItems); $from = [Math]::Max(0, $li.Count - 150)
    for ($i = $from; $i -lt $li.Count; $i++) { [void]$sb.AppendLine([string]$li[$i].Text) }
    $txt = $sb.ToString()
    if ($env:USERNAME) { $txt = $txt.Replace($env:USERNAME, '<пользователь>') }
    try { [Windows.Clipboard]::SetText($txt); Log 'Отчёт скопирован в буфер обмена. Вставьте его (Ctrl+V) в сообщение разработчику в Discord или в issue на GitHub' 'ok' }
    catch { Log ('Не удалось скопировать отчёт: ' + $_.Exception.Message) 'warn' }
}
try {
    $fh = $Win.FindName('FootHelp')
    if ($fh) {
        [void]$fh.Inlines.Add((New-Object Windows.Documents.Run '  ·  '))
        $hl = New-Object Windows.Documents.Hyperlink (New-Object Windows.Documents.Run 'Отчёт')
        $hl.ToolTip = 'Скопировать в буфер версию, Windows, стратегию и последние строки журнала (без имени пользователя) — приложите к сообщению о проблеме'
        $hl.Add_Click({ Copy-DevReport })
        [void]$fh.Inlines.Add($hl)
    }
} catch { }
Apply-Simple
try { Update-GameMode -Force } catch { }
$pr = [Diagnostics.Process]::GetProcessesByName('winws')
if ($pr.Count -gt 0) { $script:Running = $true; $script:StartedAt = Get-Date; Log 'Обнаружен запущенный winws' }
foreach ($x in $pr) { $x.Dispose() }
if ($script:LastSlogan) { $SloganText.Text = $script:LastSlogan } else { $SloganText.Text = (Get-Slogan) }
$script:Ready = $true
Log 'Zapret Studio готов. Двойной щелчок по карточке — запуск стратегии.'
Render-State
$StatusTimer.Start()

# ---------------------------------------------------------------- сборка 5: фоны окна, варианты заставки, «О создателях», чистый DNS
$script:BgList = @(@('none', 'Без фона'), @('aurora', 'Северное сияние'), @('stars', 'Звёзды'), @('waves', 'Волны'), @('grid', 'Сетка'), @('hex', 'Соты'), @('dots', 'Точки'))
if (-not ((@('random') + @($script:IntroList)) -contains [string]$Cfg.Intro)) { $Cfg.Intro = 'random' }
$script:IntroChoices = @(@('zs', 'ZS'))
$script:BgAcc = ''
function Ac4([byte]$al, $c) { [Windows.Media.Color]::FromArgb($al, $c.R, $c.G, $c.B) }
function Inv4([double]$x, [double]$y) { [string]::Format([Globalization.CultureInfo]::InvariantCulture, '{0:0.##},{1:0.##}', $x, $y) }
function New-Loop4([double]$from, [double]$to, [double]$sec, [bool]$rev) {
    $a = New-Object Windows.Media.Animation.DoubleAnimation
    $a.From = $from; $a.To = $to
    $a.Duration = New-Object Windows.Duration ([TimeSpan]::FromSeconds($sec))
    $a.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
    if ($rev) { $a.AutoReverse = $true; $s = New-Object Windows.Media.Animation.SineEase; $s.EasingMode = 'EaseInOut'; $a.EasingFunction = $s }
    $a
}
function Set-BgClip {
    try {
        if ($BgFx.ActualWidth -lt 2) { return }
        $r = [Math]::Max(0, [double]$Cfg.Radius - 1); if ($Cfg.Blur) { $r = 0 }
        $BgFx.Clip = New-Object Windows.Media.RectangleGeometry (New-Object Windows.Rect 0, 0, $BgFx.ActualWidth, $BgFx.ActualHeight), $r, $r
    } catch { }
}
# ---- сборка 8: живые фоны (летящие звёзды, метеоры, под музыку, пульс сети)
# звёзды/метеоры/пульс движет сам WPF на потоке отрисовки (скрипт на каждом кадре не работает),
# «под музыку» читает уровень звука Windows 30 раз в секунду. В трее, свёрнутом окне и в игре всё спит.
$script:LiveKinds = @('warp', 'meteor', 'music', 'pulse')
$script:LiveBgList = @(@('warp', 'Звёздный полёт'), @('meteor', 'Метеоры'), @('music', 'Под музыку ♪'), @('pulse', 'Пульс сети'))
$script:LiveBars = $null; $script:LiveGlow = $null; $script:LiveGlowEl = $null
$script:LiveLvl = 0.0; $script:LivePh = 0.0; $script:LiveMusicOk = $false
$script:LiveTimer = New-Object Windows.Threading.DispatcherTimer ([Windows.Threading.DispatcherPriority]::Render)
$script:LiveTimer.Interval = [TimeSpan]::FromMilliseconds(33)
function Stop-LiveBg { try { $script:LiveTimer.Stop() } catch { }; $script:LiveBars = $null; $script:LiveGlow = $null; $script:LiveGlowEl = $null }
function Live-C([Windows.Media.Color]$c, [int]$a) { [Windows.Media.Color]::FromArgb([byte]$a, $c.R, $c.G, $c.B) }
function Live-B([Windows.Media.Color]$c) { $b = New-Object Windows.Media.SolidColorBrush $c; $b.Freeze(); $b }
function Live-A([double]$from, [double]$to, [double]$sec, [double]$bt, $ease) {
    $a = New-Object Windows.Media.Animation.DoubleAnimation
    $a.From = $from; $a.To = $to
    $a.Duration = New-Object Windows.Duration ([TimeSpan]::FromSeconds($sec))
    $a.BeginTime = [TimeSpan]::FromSeconds($bt)
    $a.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
    if ($ease) { $a.EasingFunction = $ease }
    $a
}
# кадры: массив пар (секунда, значение); после последнего кадра значение держится до конца цикла
function Live-K([double]$cycle, [double]$bt, $keys) {
    $a = New-Object Windows.Media.Animation.DoubleAnimationUsingKeyFrames
    $a.Duration = New-Object Windows.Duration ([TimeSpan]::FromSeconds($cycle))
    $a.BeginTime = [TimeSpan]::FromSeconds($bt)
    $a.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
    for ($i = 0; $i -lt $keys.Count; $i += 2) {
        $kt = [Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromSeconds([double]$keys[$i]))
        [void]$a.KeyFrames.Add((New-Object Windows.Media.Animation.LinearDoubleKeyFrame ([double]$keys[$i + 1]), $kt))
    }
    $a
}
function Live-Dots($cv, [int]$n, $rnd, [double]$maxOp) {
    $w = Live-B ([Windows.Media.Colors]::White)
    for ($i = 0; $i -lt $n; $i++) {
        $e = New-Object Windows.Shapes.Ellipse; $s = 1 + $rnd.NextDouble() * 1.8; $e.Width = $s; $e.Height = $s; $e.Fill = $w
        $e.Opacity = 0.1 + $rnd.NextDouble() * $maxOp
        [Windows.Controls.Canvas]::SetLeft($e, $rnd.NextDouble() * 1000); [Windows.Controls.Canvas]::SetTop($e, $rnd.NextDouble() * 700)
        [void]$cv.Children.Add($e)
    }
}
function Build-LiveBg($cv, [Windows.Media.Color]$ac, [string]$v) {
    $rnd = New-Object Random
    $TX = [Windows.Media.TranslateTransform]::XProperty; $TY = [Windows.Media.TranslateTransform]::YProperty
    $SX = [Windows.Media.ScaleTransform]::ScaleXProperty; $SY = [Windows.Media.ScaleTransform]::ScaleYProperty
    $OP = [Windows.UIElement]::OpacityProperty
    $white = Live-B ([Windows.Media.Colors]::White)
    $acB = Live-B (Live-C $ac 255)
    switch ($v) {
        'warp' {
            # свечение в центре + звёзды-штрихи, которые разгоняются от центра к краям
            $g = New-Object Windows.Media.RadialGradientBrush
            [void]$g.GradientStops.Add((New-Object Windows.Media.GradientStop (Live-C $ac 70), 0)); [void]$g.GradientStops.Add((New-Object Windows.Media.GradientStop (Live-C $ac 0), 1))
            $glow = New-Object Windows.Shapes.Ellipse; $glow.Width = 560; $glow.Height = 420; $glow.Fill = $g
            [Windows.Controls.Canvas]::SetLeft($glow, 220); [Windows.Controls.Canvas]::SetTop($glow, 140); [void]$cv.Children.Add($glow)
            $ein = New-Object Windows.Media.Animation.QuadraticEase; $ein.EasingMode = 'EaseIn'
            for ($i = 0; $i -lt 90; $i++) {
                $ang = $rnd.NextDouble() * 2 * [Math]::PI; $dist = 560 + $rnd.NextDouble() * 220
                $sz = 1.4 + $rnd.NextDouble() * 2.2
                $r = New-Object Windows.Shapes.Rectangle; $r.Width = $sz; $r.Height = $sz; $r.RadiusX = $sz / 2; $r.RadiusY = $sz / 2
                if ($i % 4 -eq 0) { $r.Fill = $acB } else { $r.Fill = $white }
                $r.Opacity = 0; $r.RenderTransformOrigin = New-Object Windows.Point 0.5, 0.5
                $sc = New-Object Windows.Media.ScaleTransform; $ro = New-Object Windows.Media.RotateTransform ($ang * 180 / [Math]::PI); $tt = New-Object Windows.Media.TranslateTransform
                $tg = New-Object Windows.Media.TransformGroup; [void]$tg.Children.Add($sc); [void]$tg.Children.Add($ro); [void]$tg.Children.Add($tt)
                $r.RenderTransform = $tg
                [Windows.Controls.Canvas]::SetLeft($r, 500); [Windows.Controls.Canvas]::SetTop($r, 350)
                [void]$cv.Children.Add($r)
                $dur = 2.4 + $rnd.NextDouble() * 3.0; $bt = $rnd.NextDouble() * $dur
                $tt.BeginAnimation($TX, (Live-A 0 ([Math]::Cos($ang) * $dist) $dur $bt $ein))
                $tt.BeginAnimation($TY, (Live-A 0 ([Math]::Sin($ang) * $dist * 0.75) $dur $bt $ein))
                $sc.BeginAnimation($SX, (Live-A 0.6 14 $dur $bt $ein))
                $sc.BeginAnimation($SY, (Live-A 0.5 1.5 $dur $bt $ein))
                $r.BeginAnimation($OP, (Live-K $dur $bt @(0, 0, ($dur * 0.35), 0.95)))
            }
        }
        'meteor' {
            Live-Dots $cv 80 $rnd 0.5
            for ($i = 0; $i -lt 9; $i++) {
                $lg = New-Object Windows.Media.LinearGradientBrush; $lg.StartPoint = New-Object Windows.Point 0, 0.5; $lg.EndPoint = New-Object Windows.Point 1, 0.5
                [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop (Live-C $ac 0), 0))
                [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop (Live-C $ac 180), 0.7))
                [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.Colors]::White), 1))
                $r = New-Object Windows.Shapes.Rectangle; $r.Width = 150 + $rnd.NextDouble() * 90; $r.Height = 2; $r.RadiusX = 1; $r.RadiusY = 1; $r.Fill = $lg; $r.Opacity = 0
                $ro = New-Object Windows.Media.RotateTransform 150; $tt = New-Object Windows.Media.TranslateTransform
                $tg = New-Object Windows.Media.TransformGroup; [void]$tg.Children.Add($ro); [void]$tg.Children.Add($tt); $r.RenderTransform = $tg
                [void]$cv.Children.Add($r)
                $sx = 350 + $rnd.NextDouble() * 750; $sy = -60 + $rnd.NextDouble() * 260
                $fly = 1.0 + $rnd.NextDouble() * 0.5; $cyc = 5 + $rnd.NextDouble() * 7; $bt = $rnd.NextDouble() * 6
                $tt.BeginAnimation($TX, (Live-K $cyc $bt @(0, $sx, $fly, ($sx - 720))))
                $tt.BeginAnimation($TY, (Live-K $cyc $bt @(0, $sy, $fly, ($sy + 415))))
                $r.BeginAnimation($OP, (Live-K $cyc $bt @(0, 0, 0.12, 1, ($fly * 0.75), 0.85, $fly, 0)))
            }
        }
        'pulse' {
            Live-Dots $cv 50 $rnd 0.35
            $ez = New-Object Windows.Media.Animation.CubicEase; $ez.EasingMode = 'EaseOut'
            for ($i = 0; $i -lt 5; $i++) {
                $e = New-Object Windows.Shapes.Ellipse; $e.Width = 160; $e.Height = 160; $e.Stroke = $acB; $e.StrokeThickness = 2; $e.Opacity = 0
                $e.RenderTransformOrigin = New-Object Windows.Point 0.5, 0.5
                $sc = New-Object Windows.Media.ScaleTransform; $e.RenderTransform = $sc
                [Windows.Controls.Canvas]::SetLeft($e, 420); [Windows.Controls.Canvas]::SetTop($e, 270)
                [void]$cv.Children.Add($e)
                $bt = $i * 1.3
                $sc.BeginAnimation($SX, (Live-A 0.3 5.5 6.5 $bt $ez)); $sc.BeginAnimation($SY, (Live-A 0.3 5.5 6.5 $bt $ez))
                $e.BeginAnimation($OP, (Live-A 0.7 0 6.5 $bt $null))
            }
            $c = New-Object Windows.Shapes.Ellipse; $c.Width = 26; $c.Height = 26; $c.Fill = $acB
            [Windows.Controls.Canvas]::SetLeft($c, 487); [Windows.Controls.Canvas]::SetTop($c, 337); [void]$cv.Children.Add($c)
            $c.BeginAnimation($OP, (Live-K 1.3 0 @(0, 0.5, 0.25, 1, 1.3, 0.5)))
        }
        'music' {
            $script:LiveMusicOk = [bool](Ensure-ZsNative)
            Live-Dots $cv 60 $rnd 0.4
            $g = New-Object Windows.Media.RadialGradientBrush
            [void]$g.GradientStops.Add((New-Object Windows.Media.GradientStop (Live-C $ac 90), 0)); [void]$g.GradientStops.Add((New-Object Windows.Media.GradientStop (Live-C $ac 0), 1))
            $glow = New-Object Windows.Shapes.Ellipse; $glow.Width = 760; $glow.Height = 560; $glow.Fill = $g; $glow.Opacity = 0.35
            $glow.RenderTransformOrigin = New-Object Windows.Point 0.5, 0.5
            $gs = New-Object Windows.Media.ScaleTransform; $glow.RenderTransform = $gs
            [Windows.Controls.Canvas]::SetLeft($glow, 120); [Windows.Controls.Canvas]::SetTop($glow, 120); [void]$cv.Children.Add($glow)
            $lg = New-Object Windows.Media.LinearGradientBrush; $lg.StartPoint = New-Object Windows.Point 0.5, 1; $lg.EndPoint = New-Object Windows.Point 0.5, 0
            [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop (Live-C $ac 210), 0)); [void]$lg.GradientStops.Add((New-Object Windows.Media.GradientStop (Live-C $ac 0), 1)); $lg.Freeze()
            $bars = New-Object System.Collections.Generic.List[Windows.Media.ScaleTransform]
            for ($i = 0; $i -lt 40; $i++) {
                $r = New-Object Windows.Shapes.Rectangle; $r.Width = 17; $r.Height = 340; $r.RadiusX = 4; $r.RadiusY = 4; $r.Fill = $lg
                $r.RenderTransformOrigin = New-Object Windows.Point 0.5, 1
                $sc = New-Object Windows.Media.ScaleTransform 1, 0.05; $r.RenderTransform = $sc
                [Windows.Controls.Canvas]::SetLeft($r, 4 + $i * 25); [Windows.Controls.Canvas]::SetTop($r, 360)
                [void]$cv.Children.Add($r); $bars.Add($sc)
            }
            $script:LiveBars = $bars; $script:LiveGlow = $gs; $script:LiveGlowEl = $glow; $script:LiveLvl = 0.0
            $script:LiveTimer.Start()
        }
    }
}
function Live-Tick {
    $bars = $script:LiveBars
    if (-not $bars -or $script:BgPaused) { $script:LiveTimer.Stop(); return }
    $pk = 0.0
    if ($script:LiveMusicOk) { try { $pk = [double][ZS8.Meter]::Peak() } catch { $pk = 0.0 } }
    $L = [double]$script:LiveLvl
    if ($pk -gt $L) { $L = $L + ($pk - $L) * 0.6 } else { $L = $L * 0.9 }
    $script:LiveLvl = $L
    $script:LivePh = [double]$script:LivePh + 0.06 + $L * 0.3
    $ph = $script:LivePh; $n = $bars.Count; $half = $n / 2.0
    for ($i = 0; $i -lt $n; $i++) {
        $w = 0.5 + 0.5 * [Math]::Sin($ph * (1.0 + ($i % 5) * 0.37) + $i * 0.9)
        $env = 1.0 - [Math]::Abs(($i - $half) / $half) * 0.55
        $h = 0.04 + 0.05 * $w + $L * $env * (0.35 + 0.65 * $w)
        if ($h -gt 1) { $h = 1 }
        $bars[$i].ScaleY = $h
    }
    if ($script:LiveGlow) { $q = 0.9 + $L * 0.4; $script:LiveGlow.ScaleX = $q; $script:LiveGlow.ScaleY = $q }
    if ($script:LiveGlowEl) { $script:LiveGlowEl.Opacity = 0.3 + [Math]::Min(0.7, $L * 0.9) }
}
$script:LiveTimer.Add_Tick({ try { Live-Tick } catch { $script:LiveTimer.Stop() } })

function Apply-BgFx {
    try {
        $BgFx.Children.Clear(); Stop-LiveBg
        $script:BgAcc = [string]$Cfg.Accent
        if ($script:BgPaused) { return }
        $v = [string]$Cfg.BgFx
        if (-not $v -or $v -eq 'none') { return }
        try { $ac = ToColor ([string]$Cfg.Accent) } catch { $ac = [Windows.Media.Color]::FromRgb(124, 92, 255) }
        $anim = -not [bool]$Cfg.Perf
        $cv = New-Object Windows.Controls.Canvas; $cv.Width = 1000; $cv.Height = 700; $cv.ClipToBounds = $true
        $vb = New-Object Windows.Controls.Viewbox; $vb.Stretch = 'UniformToFill'; $vb.Child = $cv
        [void]$BgFx.Children.Add($vb)
        $TX = [Windows.Media.TranslateTransform]::XProperty; $TY = [Windows.Media.TranslateTransform]::YProperty
        if ($script:LiveKinds -contains $v) { if ($anim) { Build-LiveBg $cv $ac $v; try { Set-BgClip } catch { }; return } else { $v = 'stars' } }
        switch ($v) {
            'aurora' {
                foreach ($s in @(@(40, 20, 620, 'acc', 26), @(520, 300, 640, '#22D3EE', 34), @(260, 400, 520, '#A855F7', 30))) {
                    $c = $ac; if ($s[3] -ne 'acc') { $c = ToColor $s[3] }
                    $el = New-Object Windows.Shapes.Ellipse; $el.Width = $s[2]; $el.Height = $s[2] * 0.7
                    $rg = New-Object Windows.Media.RadialGradientBrush
                    [void]$rg.GradientStops.Add((New-Object Windows.Media.GradientStop (Ac4 64 $c), 0))
                    [void]$rg.GradientStops.Add((New-Object Windows.Media.GradientStop (Ac4 0 $c), 1))
                    $el.Fill = $rg
                    [Windows.Controls.Canvas]::SetLeft($el, $s[0]); [Windows.Controls.Canvas]::SetTop($el, $s[1])
                    $tt = New-Object Windows.Media.TranslateTransform; $el.RenderTransform = $tt
                    [void]$cv.Children.Add($el)
                    if ($anim) { $tt.BeginAnimation($TX, (New-Loop4 -70 70 $s[4] $true)); $tt.BeginAnimation($TY, (New-Loop4 45 -45 ($s[4] * 0.8) $true)) }
                }
            }
            'stars' {
                $rnd = New-Object Random 7
                for ($i = 0; $i -lt 90; $i++) {
                    $d = 1 + $rnd.NextDouble() * 2.2
                    $el = New-Object Windows.Shapes.Ellipse; $el.Width = $d; $el.Height = $d
                    if ($i % 9 -eq 0) { $el.Fill = New-Object Windows.Media.SolidColorBrush (Ac4 210 $ac) } else { $el.Fill = New-Object Windows.Media.SolidColorBrush ([Windows.Media.Color]::FromArgb([byte](70 + $rnd.Next(130)), 255, 255, 255)) }
                    [Windows.Controls.Canvas]::SetLeft($el, $rnd.Next(1000)); [Windows.Controls.Canvas]::SetTop($el, $rnd.Next(700))
                    [void]$cv.Children.Add($el)
                    if ($anim -and $i % 7 -eq 0) { $el.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Loop4 0.15 1 (2 + $rnd.NextDouble() * 3) $true)) }
                }
            }
            'waves' {
                for ($k = 0; $k -lt 3; $k++) {
                    $sb = New-Object Text.StringBuilder
                    for ($x = -250; $x -le 1250; $x += 10) {
                        $y = 470 + $k * 55 + [Math]::Sin(2 * [Math]::PI * $x / 250) * (18 + $k * 6)
                        if ($x -eq -250) { [void]$sb.Append('M ') } else { [void]$sb.Append(' L ') }
                        [void]$sb.Append((Inv4 $x $y))
                    }
                    $p = New-Object Windows.Shapes.Path
                    $p.Data = [Windows.Media.Geometry]::Parse($sb.ToString())
                    $p.Stroke = New-Object Windows.Media.SolidColorBrush (Ac4 ([byte](70 - $k * 18)) $ac); $p.StrokeThickness = 2
                    $tt = New-Object Windows.Media.TranslateTransform; $p.RenderTransform = $tt
                    [void]$cv.Children.Add($p)
                    if ($anim) { $tt.BeginAnimation($TX, (New-Loop4 0 -250 (9 + $k * 4) $false)) }
                }
            }
            default {
                $br = New-Object Windows.Media.SolidColorBrush (Ac4 38 $ac)
                $gd = New-Object Windows.Media.GeometryDrawing
                if ($v -eq 'grid') { $tw = 40; $th = 40; $gd.Geometry = [Windows.Media.Geometry]::Parse('M 0,0 L 40,0 M 0,0 L 0,40'); $gd.Pen = New-Object Windows.Media.Pen $br, 1 }
                elseif ($v -eq 'hex') { $tw = 30; $th = 51.96; $gd.Geometry = [Windows.Media.Geometry]::Parse('M 15,0 L 30,8.66 L 30,25.98 L 15,34.64 L 0,25.98 L 0,8.66 Z M 15,34.64 L 15,51.96'); $gd.Pen = New-Object Windows.Media.Pen $br, 1 }
                else { $tw = 24; $th = 24; $gd.Geometry = New-Object Windows.Media.EllipseGeometry (New-Object Windows.Point 12, 12), 1.6, 1.6; $gd.Brush = New-Object Windows.Media.SolidColorBrush (Ac4 70 $ac) }
                $db = New-Object Windows.Media.DrawingBrush $gd
                $db.TileMode = 'Tile'; $db.Stretch = 'None'
                $db.Viewport = New-Object Windows.Rect 0, 0, $tw, $th; $db.ViewportUnits = 'Absolute'
                $db.Viewbox = New-Object Windows.Rect 0, 0, $tw, $th; $db.ViewboxUnits = 'Absolute'
                $rc = New-Object Windows.Shapes.Rectangle; $rc.Width = 1000; $rc.Height = 700; $rc.Fill = $db
                $om = New-Object Windows.Media.RadialGradientBrush
                [void]$om.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(255, 0, 0, 0)), 0))
                [void]$om.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(50, 0, 0, 0)), 1))
                $rc.OpacityMask = $om
                [void]$cv.Children.Add($rc)
            }
        }
        Set-BgClip
    } catch { try { $BgFx.Children.Clear() } catch { } }
}
function Build-Chips($panel, $list, [string]$group, [string]$cur, [scriptblock]$onPick) {
    $panel.Children.Clear()
    foreach ($it in $list) {
        $rb = New-Object Windows.Controls.RadioButton
        $rb.Style = $Win.FindResource('Seg'); $rb.GroupName = $group
        $rb.Padding = New-Object Windows.Thickness 12, 6, 12, 6; $rb.Margin = New-Object Windows.Thickness 0, 0, 6, 6
        $rb.SetResourceReference([Windows.Controls.Control]::FontSizeProperty, 'Fs13')
        $rb.Content = $it[1]; $rb.Tag = $it[0]; $rb.IsChecked = ($it[0] -eq $cur)
        $rb.Add_Click($onPick)
        [void]$panel.Children.Add($rb)
    }
}

