function Open-Discord([string]$who) {
    $d = $script:Devs[$who]; if (-not $d) { return }
    try { [Windows.Clipboard]::SetText([string]$d.Nick) } catch { }
    $url = 'https://discord.com/app'
    if ([string]$d.Id -match '^\d{15,21}$') { $url = 'https://discord.com/users/' + $d.Id }
    elseif (Test-Path -LiteralPath 'Registry::HKEY_CLASSES_ROOT\discord') { $url = 'discord://-/channels/@me' }
    try { Start-Process $url } catch { try { Start-Process 'https://discord.com/app' } catch { } }
    if ([string]$d.Id -match '^\d{15,21}$') { $AboutToast.Text = ('Открываю профиль {0} в Discord. Ник @{1} скопирован.' -f $d.Name, $d.Nick) }
    else { $AboutToast.Text = ('Ник @{0} скопирован — в Discord: «Друзья» → «Добавить в друзья» → Ctrl+V' -f $d.Nick) }
    $AboutToast.Visibility = 'Visible'
    $script:ToastTm.Stop(); $script:ToastTm.Start()
}
function New-Anim4([double]$from, [double]$to, [int]$ms, [int]$delay, $ease) {
    $a = New-Object Windows.Media.Animation.DoubleAnimation
    if (-not [double]::IsNaN($from)) { $a.From = $from }
    $a.To = $to
    $a.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds($ms))
    $a.BeginTime = [TimeSpan]::FromMilliseconds($delay)
    if ($ease) { $a.EasingFunction = $ease }
    $a
}
function Badge-Hover($badge, $pop, $card, [bool]$on) {
    try {
        $ez = New-Object Windows.Media.Animation.CubicEase; $ez.EasingMode = 'EaseOut'
        $sc = $badge.RenderTransform.Children[0]
        $to = 1.0; $gl = 0.0; if ($on) { $to = 1.04; $gl = 24 }
        $sc.BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, (New-Anim4 ([double]::NaN) $to 220 0 $ez))
        $sc.BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, (New-Anim4 ([double]::NaN) $to 220 0 $ez))
        if ($badge.Effect -and -not $Cfg.Perf) { $badge.Effect.BeginAnimation([Windows.Media.Effects.DropShadowEffect]::BlurRadiusProperty, (New-Anim4 ([double]::NaN) $gl 260 0 $ez)) }
        if ($on) {
            $pop.IsOpen = $true
            $bk = New-Object Windows.Media.Animation.BackEase; $bk.EasingMode = 'EaseOut'; $bk.Amplitude = 0.5
            $g = $card.RenderTransform
            $g.Children[0].BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, (New-Anim4 0.6 1 380 0 $bk))
            $g.Children[0].BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, (New-Anim4 0.6 1 380 0 $bk))
            $g.Children[1].BeginAnimation([Windows.Media.TranslateTransform]::YProperty, (New-Anim4 16 0 380 0 $ez))
            $card.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Anim4 0 1 240 0 $ez))
        } else { $pop.IsOpen = $false }
    } catch { }
}
function Play-About {
    try {
        $ez = New-Object Windows.Media.Animation.CubicEase; $ez.EasingMode = 'EaseOut'
        $bk = New-Object Windows.Media.Animation.BackEase; $bk.EasingMode = 'EaseOut'; $bk.Amplitude = 0.4
        $t = New-Object Windows.Media.TranslateTransform; $AboutPanel.RenderTransform = $t
        $AboutPanel.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Anim4 0 1 260 0 $ez))
        $t.BeginAnimation([Windows.Media.TranslateTransform]::YProperty, (New-Anim4 24 0 380 0 $ez))
        try { $acC = ToColor ([string]$Cfg.Accent) } catch { $acC = [Windows.Media.Color]::FromRgb(124, 92, 255) }
        $i = 0
        foreach ($bd in @($BadgeDad, $BadgeKol)) {
            $sx0 = -40; if ($i -eq 1) { $sx0 = 40 }
            $bd.RenderTransform.Children[1].BeginAnimation([Windows.Media.TranslateTransform]::XProperty, (New-Anim4 $sx0 0 520 (140 + $i * 140) $bk))
            $bd.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Anim4 0 1 360 (140 + $i * 140) $ez))
            if ($bd.Effect -and $bd -eq $BadgeDad) { $bd.Effect.Color = $acC }
            $i++
        }
        if (-not $Cfg.Perf) {
            $gb = New-Object Windows.Media.LinearGradientBrush
            [void]$gb.GradientStops.Add((New-Object Windows.Media.GradientStop $acC, 0))
            [void]$gb.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromRgb(34, 211, 238)), 0.5))
            [void]$gb.GradientStops.Add((New-Object Windows.Media.GradientStop $acC, 1))
            $rt = New-Object Windows.Media.RotateTransform; $rt.CenterX = 0.5; $rt.CenterY = 0.5
            $gb.RelativeTransform = $rt
            $BadgeDad.BorderBrush = $gb
            $kb = New-Object Windows.Media.LinearGradientBrush
            foreach ($gs in @(@('#3B82F6', 0), @('#93C5FD', 0.5), @('#3B82F6', 1))) { [void]$kb.GradientStops.Add((New-Object Windows.Media.GradientStop ([Windows.Media.ColorConverter]::ConvertFromString($gs[0])), ([double]$gs[1]))) }
            $kb.RelativeTransform = $rt; $BadgeKol.BorderBrush = $kb
            $rt.BeginAnimation([Windows.Media.RotateTransform]::AngleProperty, (New-Loop4 0 360 4 $false))
        }
    } catch { }
}
