function Test-FileLocked([string]$f) {
    if (-not (Test-Path -LiteralPath $f)) { return $false }
    try { $fs = [IO.File]::Open($f, 'Open', 'ReadWrite', 'None'); $fs.Close(); return $false } catch { return $true }
}
function Get-BrwProcs($bw) {
    $ps = @(Get-Process -Name $bw.P -ErrorAction SilentlyContinue)
    if ($bw.H) { $hh = '*' + $bw.H + '*'; $ps = @($ps | Where-Object { $pth = $null; try { $pth = $_.Path } catch { }; $pth -and ($pth -like $hh) }) }
    $ps
}
function Test-BrwRunning($bw, [string]$dir) {
    if (Test-FileLocked (Join-Path $dir 'lockfile')) { return $true }
    (@(Get-BrwProcs $bw).Count -gt 0)
}
function Close-Brw($bw) {
    $ps = @(Get-BrwProcs $bw)
    foreach ($p in $ps) { try { [void]$p.CloseMainWindow() } catch { } }
    $t0 = Get-Date
    while (((Get-Date) - $t0).TotalMilliseconds -lt 5000) {
        $alive = @($ps | Where-Object { $ex = $true; try { $ex = $_.HasExited } catch { }; -not $ex })
        if ($alive.Count -eq 0) { break }
        Start-Sleep -Milliseconds 200; Pump-Ui
    }
    foreach ($p in $ps) { try { if (-not $p.HasExited) { $p.Kill() } } catch { } }
    Start-Sleep -Milliseconds 700
}
function Set-JProp($o, [string]$k, $v) {
    if ($o.PSObject.Properties[$k]) { $o.$k = $v } else { $o | Add-Member -NotePropertyName $k -NotePropertyValue $v -Force }
}
function Load-BrwPrev {
    $h = @{}
    try {
        if (Test-Path -LiteralPath $script:BrwPrevFile) {
            $o = [IO.File]::ReadAllText($script:BrwPrevFile) | ConvertFrom-Json
            foreach ($p in $o.PSObject.Properties) { $h[$p.Name] = @{ Mode = [string]$p.Value.Mode; Tpl = [string]$p.Value.Tpl; Quic = [string]$p.Value.Quic } }
        }
    } catch { }
    $h
}
function Save-BrwPrev($h) {
    try {
        if ($h.Count -eq 0) { Remove-Item -LiteralPath $script:BrwPrevFile -Force -ErrorAction SilentlyContinue; return }
        [IO.File]::WriteAllText($script:BrwPrevFile, ($h | ConvertTo-Json -Depth 4), (New-Object Text.UTF8Encoding($false)))
    } catch { }
}
# Chromium: Local State. $on - настроить, иначе вернуть $pv (что было до нас). Возвращает @{ Ok; Why; Prev }
function Set-CrLocalState([string]$dir, [bool]$on, $pv) {
    $f = Join-Path $dir 'Local State'
    if (-not (Test-Path -LiteralPath $f)) { return @{ Ok = $false; Why = 'ещё ни разу не запускался' } }
    $enc = New-Object Text.UTF8Encoding($false)
    $j = $null
    try { $j = [IO.File]::ReadAllText($f, $enc) | ConvertFrom-Json } catch { return @{ Ok = $false; Why = 'не смог прочитать настройки' } }
    if (-not $j) { return @{ Ok = $false; Why = 'пустые настройки' } }
    $prev = @{ Mode = ''; Tpl = ''; Quic = '' }
    if (-not $j.PSObject.Properties['dns_over_https'] -or -not $j.dns_over_https) { Set-JProp $j 'dns_over_https' (New-Object PSObject) }
    $dd = $j.dns_over_https
    if ($dd.PSObject.Properties['mode']) { $prev.Mode = [string]$dd.mode }
    if ($dd.PSObject.Properties['templates']) { $prev.Tpl = [string]$dd.templates }
    if (-not $j.PSObject.Properties['browser'] -or -not $j.browser) { Set-JProp $j 'browser' (New-Object PSObject) }
    $exl = @()
    if ($j.browser.PSObject.Properties['enabled_labs_experiments']) {
        foreach ($x in @($j.browser.enabled_labs_experiments)) {
            if (-not $x) { continue }
            if ([string]$x -match '^enable-quic@') { $prev.Quic = [string]$x } else { $exl += [string]$x }
        }
    }
    if ($on) {
        Set-JProp $dd 'mode' 'automatic'
        Set-JProp $dd 'templates' $script:BrwDohCr
        $exl += 'enable-quic@2'
    } else {
        $om = ''; $ot = ''; $oq = ''
        if ($pv) { $om = [string]$pv.Mode; $ot = [string]$pv.Tpl; $oq = [string]$pv.Quic }
        if ($om) { Set-JProp $dd 'mode' $om } elseif ($dd.PSObject.Properties['mode']) { $dd.PSObject.Properties.Remove('mode') }
        if ($ot) { Set-JProp $dd 'templates' $ot } elseif ($dd.PSObject.Properties['templates']) { $dd.PSObject.Properties.Remove('templates') }
        if ($oq) { $exl += $oq }
    }
    Set-JProp $j.browser 'enabled_labs_experiments' ([object[]]$exl)
    $out = $j | ConvertTo-Json -Depth 100 -Compress
    try { $null = $out | ConvertFrom-Json } catch { return @{ Ok = $false; Why = 'проверка файла не прошла, не тронул' } }
    $bak = $f + '.zs-backup'
    try { if (-not (Test-Path -LiteralPath $bak)) { Copy-Item -LiteralPath $f -Destination $bak -Force } } catch { }
    try { [IO.File]::WriteAllText($f, $out, $enc) } catch { return @{ Ok = $false; Why = 'файл занят' } }
    @{ Ok = $true; Why = ''; Prev = $prev }
}
# Firefox-семейство: блок в user.js каждого профиля
function Set-FxProfiles([string]$dir, [bool]$on) {
    $n = 0
    $enc = New-Object Text.UTF8Encoding($false)
    foreach ($pd in @(Get-ChildItem -LiteralPath $dir -Directory -ErrorAction SilentlyContinue)) {
        if (-not (Test-Path -LiteralPath (Join-Path $pd.FullName 'prefs.js'))) { continue }
        $uj = Join-Path $pd.FullName 'user.js'
        $txt = ''
        try { if (Test-Path -LiteralPath $uj) { $txt = [IO.File]::ReadAllText($uj) } } catch { continue }
        $txt = [regex]::Replace($txt, '(?s)// >>> Zapret Studio.*?// <<< Zapret Studio\r?\n?', '')
        if ($on) {
            $blk = "// >>> Zapret Studio: безопасный DNS и без QUIC (убрать - кнопка «Вернуть как было»)`r`n" +
                "user_pref(`"network.trr.mode`", 2);`r`nuser_pref(`"network.trr.uri`", `"$($script:BrwDoh)`");`r`n" +
                "user_pref(`"network.trr.custom_uri`", `"$($script:BrwDoh)`");`r`nuser_pref(`"network.http.http3.enable`", false);`r`n// <<< Zapret Studio`r`n"
        } else {
            # user.js навсегда пишет значения в prefs.js, поэтому возвращаем стандартные, а не просто удаляем строки
            $blk = "// >>> Zapret Studio: стандартные значения браузера`r`nuser_pref(`"network.trr.mode`", 0);`r`nuser_pref(`"network.http.http3.enable`", true);`r`n// <<< Zapret Studio`r`n"
        }
        $txt = $txt.TrimEnd(); if ($txt) { $txt += "`r`n" }
        $txt += $blk
        try { [IO.File]::WriteAllText($uj, $txt, $enc); $n++ } catch { }
    }
    $n
}
function Add-BrwChip([string]$t, [string]$hex) {
    try {
        $bd = New-Object Windows.Controls.Border
        $bd.CornerRadius = New-Object Windows.CornerRadius(8)
        $bd.Padding = New-Object Windows.Thickness(9, 3, 9, 3)
        $bd.Margin = New-Object Windows.Thickness(0, 0, 6, 6)
        $cc = ToColor $hex
        $bd.Background = New-Brush ([Windows.Media.Color]::FromArgb(38, $cc.R, $cc.G, $cc.B))
        $bd.BorderBrush = New-Brush ([Windows.Media.Color]::FromArgb(110, $cc.R, $cc.G, $cc.B))
        $bd.BorderThickness = New-Object Windows.Thickness(1)
        $tx = New-Object Windows.Controls.TextBlock
        $tx.Text = $t; $tx.FontSize = 11; $tx.Foreground = New-Brush $cc
        $bd.Child = $tx
        $bd.Opacity = 0
        [void]$script:BrwListUi.Children.Add($bd)
        if ($Cfg.Perf) { $bd.Opacity = 1 } else {
            $a = New-Object Windows.Media.Animation.DoubleAnimation(0, 1, [TimeSpan]::FromMilliseconds(260))
            $a.BeginTime = [TimeSpan]::FromMilliseconds(70 * ($script:BrwListUi.Children.Count - 1))
            $bd.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
        }
    } catch { }
}
function Invoke-BrwSetup([bool]$on) {
    $script:BtnBrwUi.IsEnabled = $false; $script:BtnBrwUndoUi.IsEnabled = $false
    try {
        $script:BrwListUi.Children.Clear()
        $found = @()
        foreach ($bw in $script:BrwTable) {
            $dir = [Environment]::ExpandEnvironmentVariables($bw.D)
            if (Test-Path -LiteralPath $dir) { $found += @{ B = $bw; Dir = $dir } }
        }
        if ($found.Count -eq 0) { $script:BrwStateUi.Text = 'Не нашёл ни одного из 20 поддерживаемых браузеров'; return }
        $run = @($found | Where-Object { $_.B.T -eq 'cr' -and (Test-BrwRunning $_.B $_.Dir) })
        $skipRun = $false
        if ($run.Count -gt 0) {
            $names = ($run | ForEach-Object { $_.B.N }) -join ', '
            $msg = "Сейчас открыты: $names.`n`nБраузер перезаписывает свои настройки при закрытии, поэтому его нужно закрыть. Вкладки восстановятся при следующем запуске (Ctrl+Shift+T).`n`nДа — закрыть и настроить`nНет — настроить только закрытые браузеры"
            $r = [Windows.MessageBox]::Show($Win, $msg, 'Zapret Studio — браузеры', 'YesNoCancel', 'Question')
            if ([string]$r -eq 'Cancel') { $script:BrwStateUi.Text = 'Отменено'; return }
            if ([string]$r -eq 'Yes') {
                $script:BrwStateUi.Text = 'Закрываю браузеры…'; Pump-Ui
                foreach ($x in $run) { Close-Brw $x.B }
            } else { $skipRun = $true }
        }
        $script:BrwStateUi.Text = $(if ($on) { 'Настраиваю…' } else { 'Возвращаю как было…' }); Pump-Ui
        $prevAll = Load-BrwPrev
        $okNames = @(); $skip = 0
        foreach ($x in $found) {
            $bw = $x.B
            try {
                if ($bw.T -eq 'fx') {
                    $k = Set-FxProfiles $x.Dir $on
                    if ($k -gt 0) { $okNames += $bw.N; Add-BrwChip ([string][char]0x2713 + ' ' + $bw.N + $(if ($k -gt 1) { " ($k проф.)" } else { '' })) '#22C55E' }
                    else { $skip++; Add-BrwChip ('• ' + $bw.N + ' — нет профилей') '#F59E0B' }
                    continue
                }
                if ($skipRun -and (Test-BrwRunning $bw $x.Dir)) { $skip++; Add-BrwChip ('• ' + $bw.N + ' — открыт, пропущен') '#F59E0B'; continue }
                $rs = Set-CrLocalState $x.Dir $on $prevAll[$bw.N]
                if ($rs.Ok) {
                    $okNames += $bw.N
                    if ($on) { if (-not $prevAll.ContainsKey($bw.N)) { $prevAll[$bw.N] = $rs.Prev } } else { $prevAll.Remove($bw.N) }
                    Add-BrwChip ([string][char]0x2713 + ' ' + $bw.N) '#22C55E'
                } else { $skip++; Add-BrwChip ('• ' + $bw.N + ' — ' + $rs.Why) '#F59E0B' }
            } catch { $skip++; Add-BrwChip ('• ' + $bw.N + ' — ошибка') '#EF4444' }
        }
        Save-BrwPrev $prevAll
        if ($okNames.Count -gt 0) {
            if ($on) {
                $script:BrwStateUi.Text = ('Готово: {0} из {1}. Безопасный DNS (Cloudflare + Google) и без QUIC. Запустите браузер заново' -f $okNames.Count, $found.Count)
                Log ('Браузеры настроены под Zapret Studio: ' + ($okNames -join ', ') + ' — безопасный DNS и без QUIC. Перезапустите браузер') 'ok'
            } else {
                $script:BrwStateUi.Text = ('Вернул как было: {0} из {1}' -f $okNames.Count, $found.Count)
                Log ('Настройки браузеров возвращены: ' + ($okNames -join ', ')) 'ok'
            }
        } else { $script:BrwStateUi.Text = 'Ничего не изменено — см. подсказки ниже'; Log 'Настройка браузеров: ничего не изменено' 'warn' }
    } catch {
        $script:BrwStateUi.Text = 'Не получилось: ' + $_.Exception.Message
        Log ('Настройка браузеров: ' + $_.Exception.Message) 'err'
    } finally {
        $script:BtnBrwUi.IsEnabled = $true; $script:BtnBrwUndoUi.IsEnabled = $true
    }
}
try {
    $script:BtnBrwUi = $Win.FindName('BtnBrw'); $script:BtnBrwUndoUi = $Win.FindName('BtnBrwUndo')
    $script:BrwStateUi = $Win.FindName('BrwState'); $script:BrwListUi = $Win.FindName('BrwList')
    if ($script:BtnBrwUi) {
        $script:BtnBrwUi.Add_Click({ Invoke-BrwSetup $true })
        $script:BtnBrwUndoUi.Add_Click({ Invoke-BrwSetup $false })
        if (Test-Path -LiteralPath $script:BrwPrevFile) { $script:BrwStateUi.Text = 'Браузеры уже настроены. Можно повторить или вернуть как было' }
    }
} catch { }
# =====================================================================
#  Сборка 17 (2.0): WARP — резервный туннель Cloudflare
#  Управляем ТОЛЬКО установленным клиентом через warp-cli:
#  ничего не устанавливаем, регистрацию и настройки WARP не трогаем.
# =====================================================================
$script:WarpPanelEl = $Win.FindName('WarpPanel')
$script:WarpDotEl = $Win.FindName('WarpDot')
$script:WarpStateDotEl = $Win.FindName('WarpStateDot')
$script:WarpStateT = $Win.FindName('WarpStateText')
$script:WarpSubT = $Win.FindName('WarpStateSub')
$script:WarpStagesT = $Win.FindName('WarpStages')
$script:WarpModeHost = $Win.FindName('WarpModeHost')
$script:WarpProtoHost = $Win.FindName('WarpProtoHost')
$script:WarpModeHintT = $Win.FindName('WarpModeHint')
$script:WarpProtoHintT = $Win.FindName('WarpProtoHint')
$script:BtnWarpOnEl = $Win.FindName('BtnWarpOn')
$script:BtnWarpOffEl = $Win.FindName('BtnWarpOff')
$script:WarpHistory = New-Object System.Collections.ArrayList
$script:WarpLastStage = ''

function Get-WarpCli {
    $c = New-Object System.Collections.ArrayList
    if ($env:ProgramFiles) { [void]$c.Add((Join-Path $env:ProgramFiles 'Cloudflare\Cloudflare WARP\warp-cli.exe')) }
    $x86 = ${env:ProgramFiles(x86)}
    if ($x86) { [void]$c.Add((Join-Path $x86 'Cloudflare\Cloudflare WARP\warp-cli.exe')) }
    if ($env:LOCALAPPDATA) { [void]$c.Add((Join-Path $env:LOCALAPPDATA 'Cloudflare\Cloudflare WARP\warp-cli.exe')) }
    foreach ($p in $c) { if ($p -and (Test-Path -LiteralPath $p)) { return $p } }
    try { $g = Get-Command 'warp-cli.exe' -ErrorAction SilentlyContinue; if ($g) { return $g.Source } } catch { }
    return $null
}
$script:WarpExe = Get-WarpCli
# встроенный WARP: если в папке лежит свой клиент — работаем через него, клиент Cloudflare не нужен
$script:WarpDir = Join-Path $script:AppDir 'warp'
$script:UsqueExe = Join-Path $script:WarpDir 'usque.exe'
$script:WarpEmbedded = Test-Path -LiteralPath $script:UsqueExe

function Get-WarpStatusText([string]$raw) {
    if (-not $raw) { return @{ Key = 'unknown'; Text = 'Состояние неизвестно' } }
    if ($raw -match 'Status update:\s*Connected') {
        if ($raw -match 'Network:\s*healthy') { return @{ Key = 'on'; Text = 'Подключён · сеть в порядке' } }
        return @{ Key = 'on'; Text = 'Подключён' }
    }
    if ($raw -match 'Status update:\s*Connecting|Status update:\s*Reconnecting') { return @{ Key = 'busy'; Text = 'Установка соединения…' } }
    if ($raw -match 'Status update:\s*Disconnecting') { return @{ Key = 'busy'; Text = 'Отключение…' } }
    if ($raw -match 'Status update:\s*Disconnected') { return @{ Key = 'off'; Text = 'Не подключён' } }
    return @{ Key = 'unknown'; Text = 'Состояние неизвестно' }
}

# ---- фоновый работник: единственный, кто дёргает warp-cli. UI не блокируется.
function Start-WarpWorker {
    if ($script:WarpPs -and $script:WarpSt -and -not $script:WarpSt.Stop) { return }
    if ($script:WarpPs) { try { $script:WarpPs.Dispose() } catch { } ; $script:WarpPs = $null; $script:WarpSt = $null }
    if (-not $script:WarpExe -and -not $script:WarpEmbedded) { return }
    $st = [hashtable]::Synchronized(@{
        Status = ''; Stage = 'Готов'; Busy = $false; Result = ''; Stop = $false
        WantConnect = $false; WantDisconnect = $false; Mode = [string]$Cfg.WarpMode; Proto = [string]$Cfg.WarpProto
        Error = ''; StopAfterStatus = $false; Cancel = $false
        Embedded = [bool]$script:WarpEmbedded; Usque = [string]$script:UsqueExe; WarpDir = [string]$script:WarpDir
    })
    $script:WarpSt = $st
    $sb = {
        param($cli, $st)
        function Run([string[]]$a) {
            if ($st.Embedded) {
                $verb = [string]$a[0]
                if ($verb -eq 'status') {
                    $p = Get-Process -Name 'usque' -ErrorAction SilentlyContinue
                    if ($p) { return "Status update: Connected`nNetwork: healthy" }
                    return 'Status update: Disconnected'
                }
                if ($verb -eq 'connect') {
                    $dir = [string]$st.WarpDir
                    $cfg = Join-Path $dir 'config.json'
                    if (-not (Test-Path -LiteralPath $cfg)) {
                        $st.Stage = 'Регистрирую устройство…'
                        $r = New-Object System.Diagnostics.ProcessStartInfo
                        $r.FileName = [string]$st.Usque
                        $r.Arguments = 'register -a'
                        $r.WorkingDirectory = $dir
                        $r.UseShellExecute = $false; $r.CreateNoWindow = $true
                        $r.RedirectStandardOutput = $true; $r.RedirectStandardError = $true
                        $rp = [Diagnostics.Process]::Start($r)
                        $null = $rp.StandardOutput.ReadToEnd(); $rp.WaitForExit()
                        if (-not (Test-Path -LiteralPath $cfg)) { throw 'не удалось зарегистрировать устройство' }
                    }
                    Get-Process -Name 'usque' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
                    $st.Stage = 'Поднимаю туннель…'
                    $outLog = Join-Path $dir 'usque.out.log'
                    $errLog = Join-Path $dir 'usque.err.log'
                    try { Remove-Item -LiteralPath $errLog -Force -ErrorAction SilentlyContinue } catch { }
                    $argl = 'nativetun -n ZapretWARP --always-reconnect'
                    $upB = Join-Path $dir 'up.bat'
                    $dnB = Join-Path $dir 'down.bat'
                    if (Test-Path -LiteralPath $upB) { $argl = $argl + ' --on-connect "' + $upB + '"' }
                    if (Test-Path -LiteralPath $dnB) { $argl = $argl + ' --on-disconnect "' + $dnB + '"' }
                    $proc = Start-Process -FilePath ([string]$st.Usque) -ArgumentList $argl -WorkingDirectory $dir -WindowStyle Hidden -PassThru -RedirectStandardOutput $outLog -RedirectStandardError $errLog
                    Start-Sleep -Seconds 5
                    if ($proc -and $proc.HasExited) {
                        $er = ''
                        try { $er = ([string](Get-Content -LiteralPath $errLog -Raw -ErrorAction SilentlyContinue)).Trim() } catch { }
                        if (-not $er) { try { $er = ([string](Get-Content -LiteralPath $outLog -Raw -ErrorAction SilentlyContinue)).Trim() } catch { } }
                        if (-not $er) { $er = 'клиент завершился сразу после запуска (код ' + $proc.ExitCode + ')' }
                        $st.Error = $er
                        $st.Stage = ('usque: ' + ($er -replace "`r?`n", ' '))
                    }
                    return ''
                }
                if ($verb -eq 'disconnect') {
                    Get-Process -Name 'usque' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
                    return ''
                }
                return ''
            }
            $psi = New-Object System.Diagnostics.ProcessStartInfo
            $psi.FileName = $cli
            $psi.Arguments = (($a | ForEach-Object { if ($_ -match '\s') { '"' + $_ + '"' } else { $_ } }) -join ' ')
            $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true
            $p = [Diagnostics.Process]::Start($psi)
            $err = $p.StandardError.ReadToEndAsync()
            $out = $p.StandardOutput.ReadToEnd()
            $p.WaitForExit()
            ([string]$out + ' ' + [string]$err.Result).Trim()
        }
        while (-not $st.Stop) {
            try {
                if ($st.WantDisconnect -and -not $st.Busy) {
                    $st.WantDisconnect = $false; $st.Busy = $true; $st.Result = ''
                    $st.Stage = 'Отключаю туннель…'
                    $null = Run @('disconnect')
                    $st.Stage = 'Отключено'; $st.Busy = $false; $st.Result = 'off'
                }
                if ($st.WantConnect -and -not $st.Busy) {
                    $st.WantConnect = $false; $st.Busy = $true; $st.Result = ''
                    $ok = $false
                    for ($try = 1; $try -le 3 -and -not $ok -and -not $st.Stop -and -not $st.Cancel; $try++) {
                        $st.Stage = ('Попытка {0} из 3 · применяю режим' -f $try)
                        $null = Run @('mode', [string]$st.Mode)
                        if ([string]$st.Proto -ne 'auto') { $st.Stage = ('Попытка {0} из 3 · выбираю протокол' -f $try); $pr = [string]$st.Proto; if ($pr -eq 'masque') { $pr = 'MASQUE' } elseif ($pr -eq 'wireguard') { $pr = 'WireGuard' }; $null = Run @('tunnel', 'protocol', 'set', $pr) }
                        $st.Stage = ('Попытка {0} из 3 · отправляю команду' -f $try)
                        $conn = Run @('connect')
                        if ($st.Embedded -and $st.Error) { break }
                        $st.Stage = ('Попытка {0} из 3 · установка соединения…' -f $try)
                        $deadline = (Get-Date).AddSeconds(25); $n = 0
                        while ((Get-Date) -lt $deadline -and -not $st.Stop -and -not $st.Cancel) {
                            Start-Sleep -Milliseconds 650
                            $s = Run @('status'); $n++
                            if ($s -match 'Status update:\s*Connected') {
                                if ($s -match 'Network:\s*healthy') { $ok = $true; break }
                                $st.Stage = ('Попытка {0} из 3 · проверка сети…' -f $try)
                            }
                            elseif ($s -match 'Status update:\s*Connecting|Status update:\s*Reconnecting') { $st.Stage = ('Попытка {0} из 3 · установка соединения…' -f $try) }
                            elseif ($s -match 'Status update:\s*Disconnected' -and $n -ge 6) {
                                $st.Stage = ('Попытка {0} из 3 · соединение сброшено, повторяю' -f $try)
                                $null = Run @('connect')
                            }
                            elseif ($s -match 'registration|Registration|not registered|Unable to connect') { $st.Error = $s; break }
                        }
                        if (-not $ok -and $st.Error) { break }
                    }
                    if ($st.Cancel) {
                        # пользователь отменил подключение: снимаем то, что успело подняться
                        $st.Cancel = $false
                        $st.Stage = 'Отменено'
                        try { $null = Run @('disconnect') } catch { }
                        $st.Result = 'off'; $st.Busy = $false
                        $st.Status = 'Status update: Disconnected'
                    }
                    elseif ($ok) {                        $st.Stage = 'Подключено'; $st.Result = 'ok'
                        # окно клиента убираем: туннель держит служба, а в трее лишняя иконка не нужна
                        try { Get-Process -Name 'Cloudflare WARP' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch { }
                    }
                    elseif ($st.Error) { $st.Stage = ('Ошибка: ' + [string]$st.Error); $st.Result = 'fail' }
                    else { $st.Stage = 'НЕ УДАЛОСЬ ПОДКЛЮЧИТЬСЯ!'; $st.Result = 'fail' }
                    $st.Busy = $false
                }
                $st.Status = (Run @('status'))
                if ($st.StopAfterStatus) { $st.Stop = $true }
            } catch { $st.Error = $_.Exception.Message }
            if ($st.Stop -and -not $st.Busy) { break }
            Start-Sleep -Milliseconds 850
        }
    }
    try {
        $script:WarpPs = [PowerShell]::Create()
        [void]$script:WarpPs.AddScript($sb).AddArgument($script:WarpExe).AddArgument($st)
        $script:WarpWorker = $script:WarpPs.BeginInvoke()
    } catch { $script:WarpPs = $null; $script:WarpSt = $null }
}
function Stop-WarpWorker {
    if (-not $script:WarpSt) { return }
    $script:WarpSt.Stop = $true
    try { if ($script:WarpPs -and $script:WarpSt.Busy -eq $false) { $script:WarpPs.Dispose() } } catch { }
    $script:WarpPs = $null; $script:WarpWorker = $null; $script:WarpSt = $null
}

function Warp-PushStage([string]$t) {
    if (-not $t -or $t -eq $script:WarpLastStage) { return }
    $script:WarpLastStage = $t
    [void]$script:WarpHistory.Add($t)
    while ($script:WarpHistory.Count -gt 5) { $script:WarpHistory.RemoveAt(0) }
    if ($script:WarpStagesT) { $script:WarpStagesT.Text = (@($script:WarpHistory) -join "`n") }
}

function Warp-Paint {
    if (-not $script:WarpPanelEl) { return }
    if (-not $script:WarpExe -and -not $script:WarpEmbedded) {
        # клиента нет: говорим прямо, что делать и где взять
        try {
            if ($script:WarpStateDotEl) { $script:WarpStateDotEl.Fill = New-Brush (ToColor '#EF4444') }
            if ($script:WarpStateT) { $script:WarpStateT.Text = 'WARP не установлен' }
            if ($script:WarpDotEl) { $script:WarpDotEl.Fill = New-Brush (ToColor '#EF4444') }
            if ($script:WarpSubT) {
                $sub = $script:WarpSubT
                $sub.Inlines.Clear()
                $sub.Inlines.Add((New-Object Windows.Documents.Run 'Для работы этой функции его нужно установить — вот здесь: '))
                $hl = New-Object Windows.Documents.Hyperlink
                $hl.Inlines.Add((New-Object Windows.Documents.Run 'скачать WARP'))
                $hl.Cursor = 'Hand'
                try { $hl.Foreground = New-Brush (ToColor ([string]$Cfg.Accent)) } catch { }
                $hl.Add_Click({ try { Start-Process 'https://1.1.1.1/' } catch { } })
                $sub.Inlines.Add($hl)
                $sub.Inlines.Add((New-Object Windows.Documents.Run '. А также один раз запустите его — и всё заработает само.'))
            }
            if ($script:BtnWarpOnEl) { $script:BtnWarpOnEl.IsEnabled = $false; $script:BtnWarpOnEl.Opacity = 0.4 }
            if ($script:BtnWarpOffEl) { $script:BtnWarpOffEl.IsEnabled = $false; $script:BtnWarpOffEl.Opacity = 0.4 }
            if ($script:WarpStagesT) { $script:WarpStagesT.Text = '' }
        } catch { }
        return
    }
    $st = $script:WarpSt
    # службу проверяем не чаще раза в 3 секунды: если её остановили, клиент молча висит «настраивается»
    if ($script:WarpExe -and -not $script:WarpEmbedded) {
        $nowT = Get-Date
        if (-not $script:WarpSvcAt -or ($nowT - $script:WarpSvcAt).TotalSeconds -ge 3) {
            $script:WarpSvcAt = $nowT
            try {
                $svc = Get-Service -Name 'CloudflareWARP' -ErrorAction SilentlyContinue
                $script:WarpSvcOff = [bool]($svc -and $svc.Status -ne 'Running')
            } catch { $script:WarpSvcOff = $false }
        }
        if ($script:WarpSvcOff) {
            try {
                if ($script:WarpStateDotEl) { $script:WarpStateDotEl.Fill = New-Brush (ToColor '#EF4444') }
                if ($script:WarpStateT) { $script:WarpStateT.Text = 'Служба WARP остановлена' }
                if ($script:WarpSubT) { $script:WarpSubT.Text = 'Без службы Cloudflare One Client клиент не подключается. Запустите службу (services.msc → Cloudflare One Client) или перезагрузите компьютер.' }
                if ($script:WarpDotEl) { $script:WarpDotEl.Fill = New-Brush (ToColor '#EF4444') }
                if ($script:BtnWarpOnEl) { $script:BtnWarpOnEl.IsEnabled = $false; $script:BtnWarpOnEl.Opacity = 0.4 }
            } catch { }
            return
        }
    }
    $raw = ''; $busy = $false; $res = ''
    if ($st) { $raw = [string]$st.Status; $busy = [bool]$st.Busy; $res = [string]$st.Result }
    $s = Get-WarpStatusText $raw
    $hex = '#64748B'
    if ($s.Key -eq 'on') { $hex = '#22C55E' }
    elseif ($s.Key -eq 'busy' -or $busy) { $hex = '#F59E0B' }
    if ($res -eq 'fail') { $hex = '#EF4444' }
    $txt = $s.Text
    if ($busy -and $st) { $txt = [string]$st.Stage }
    elseif ($res -eq 'fail') { $txt = 'НЕ УДАЛОСЬ ПОДКЛЮЧИТЬСЯ!' }
    try {
        if ($script:WarpStateDotEl) { $script:WarpStateDotEl.Fill = New-Brush (ToColor $hex) }
        if ($script:WarpStateT) { $script:WarpStateT.Text = $txt }
        if ($script:WarpDotEl) { $script:WarpDotEl.Fill = New-Brush (ToColor $hex) }
    } catch { }
    $runOk = [bool]$script:Running -and -not [bool]$script:Testing
    $canOn = $runOk -or $script:WarpEmbedded -or ($s.Key -eq 'on')
    if ($script:BtnWarpOnEl) { $script:BtnWarpOnEl.IsEnabled = $canOn -and -not $busy }
    if ($script:BtnWarpOffEl) {
        $script:BtnWarpOffEl.IsEnabled = ($s.Key -eq 'on') -or $busy
        try { $script:BtnWarpOffEl.Content = $(if ($busy) { 'Отменить' } else { 'Отключить' }) } catch { }
    }
    if ($script:WarpSubT) {
        if ($busy) {
            $script:WarpSubT.Text = 'Подключение идёт — можно отменить кнопкой «Отменить»'
            $script:WarpSubT.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'WarnBrush')
        } elseif ($s.Key -eq 'on') {
            $script:WarpSubT.Text = $(if ($script:WarpEmbedded) { 'Трафик идёт через встроенный туннель Cloudflare.' } else { 'Трафик идёт через Cloudflare.' })
            $script:WarpSubT.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
        } elseif (-not $runOk -and -not $script:WarpEmbedded) {
            $script:WarpSubT.Text = 'Сначала включите обход — WARP подключается только вместе с ним'
            $script:WarpSubT.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'WarnBrush')
        } elseif ($script:WarpEmbedded) {
            $script:WarpSubT.Text = 'Встроенный туннель Cloudflare — клиент ставить не нужно'
            $script:WarpSubT.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
        } elseif ($res -eq 'fail') {
            $script:WarpSubT.Text = 'Три попытки не дали результата. Нажмите «Включить» ещё раз или проверьте клиент WARP.'
            $script:WarpSubT.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'DangerBrush')
        } else {
            $script:WarpSubT.Text = 'Обход запущен — можно подключать'
            $script:WarpSubT.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
        }
    }
    if ($st -and $st.Stage) { Warp-PushStage ([string]$st.Stage) }
    if ($res -eq 'ok' -and $script:WarpNotified -ne 'ok') {
        $script:WarpNotified = 'ok'
        Log 'WARP подключён: трафик идёт через Cloudflare' 'ok'
    }
}

$script:WarpTimer = New-Object Windows.Threading.DispatcherTimer
$script:WarpTimer.Interval = [TimeSpan]::FromMilliseconds(450)
$script:WarpTimer.Add_Tick({
    if (-not $script:WarpPanelEl -or $script:WarpPanelEl.Visibility -ne 'Visible') { $script:WarpTimer.Stop(); return }
    Warp-Paint
})

function Warp-Hints {
    if ($script:WarpModeHintT) {
        $m = [string]$Cfg.WarpMode
        if ($m -eq 'doh') { $script:WarpModeHintT.Text = 'Только DoH: туннель не поднимается, шифруется лишь DNS. Трафик идёт напрямую — для обхода бесполезно, но и скорость не режет.' }
        elseif ($m -eq 'warp+doh') { $script:WarpModeHintT.Text = 'WARP + DoH: полный туннель и DNS через Cloudflare. Самый надёжный вариант, но DNS-ответы тоже идут через Cloudflare.' }
        else { $script:WarpModeHintT.Text = 'WARP: полный туннель, DNS от провайдера. Обычный режим клиента Cloudflare.' }
    }
    if ($script:WarpProtoHintT) {
        $p = [string]$Cfg.WarpProto
        if ($p -eq 'wireguard') { $script:WarpProtoHintT.Text = 'WireGuard: быстрее и легче, но это классический UDP-хендшейк — DPI его видит и иногда режет.' }
        elseif ($p -eq 'masque') { $script:WarpProtoHintT.Text = 'MASQUE: туннель выглядит как обычный HTTP/3. Медленнее, зато проходит там, где WireGuard душат.' }
        else { $script:WarpProtoHintT.Text = 'Авто: клиент Cloudflare сам выбирает протокол. Ничего не меняем — самый безопасный вариант.' }
    }
}

function Show-Warp {
    if ($script:OnbActive -or -not $script:WarpPanelEl) { return }
    foreach ($nm in @('PrioPanel', 'ResultPanel', 'RenamePanel', 'AboutPanel', 'WhatPanel')) { $el = $Win.FindName($nm); if ($el) { $el.Visibility = 'Collapsed' } }
    $script:WarpPanelEl.Visibility = 'Visible'; $Overlay.Visibility = 'Visible'
    if (-not $Cfg.Perf) {
        $script:WarpPanelEl.Opacity = 0
        $a = New-Object Windows.Media.Animation.DoubleAnimation(0, 1, [TimeSpan]::FromMilliseconds(200))
        $script:WarpPanelEl.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
    }
    $script:WarpHistory.Clear(); $script:WarpLastStage = ''
    if ($script:WarpStagesT) { $script:WarpStagesT.Text = '' }
    if ($script:WarpSt) { $script:WarpSt.Result = ''; $script:WarpSt.Error = '' }
    Start-WarpWorker
    if ($script:WarpSt) { $script:WarpSt.StopAfterStatus = $false }
    Warp-Hints
    Warp-Paint
    $script:WarpTimer.Start()
}

if ($script:WarpModeHost) {
    Build-Chips $script:WarpModeHost @(@('warp', 'WARP'), @('warp+doh', 'WARP + DoH'), @('doh', 'Только DoH')) 'warpmode' ([string]$Cfg.WarpMode) { param($s, $ev) $Cfg.WarpMode = [string]$s.Tag; Request-Save; Warp-Hints }
}
if ($script:WarpProtoHost) {
    Build-Chips $script:WarpProtoHost @(@('auto', 'Авто'), @('masque', 'MASQUE'), @('wireguard', 'WireGuard')) 'warpproto' ([string]$Cfg.WarpProto) { param($s, $ev) $Cfg.WarpProto = [string]$s.Tag; Request-Save; Warp-Hints }
}
if ($script:BtnWarpOnEl) {
    $script:BtnWarpOnEl.Add_Click({
        if (-not $script:WarpEmbedded -and (-not $script:Running -or $script:Testing)) {
            $wk = ''
            if ($script:WarpSt) { $wk = (Get-WarpStatusText ([string]$script:WarpSt.Status)).Key }
            if ($wk -ne 'on') { Log 'WARP: сначала включите обход' 'warn'; return }
        }
        Start-WarpWorker
        if (-not $script:WarpSt) { Log 'WARP: не удалось запустить туннель' 'err'; return }
        $script:WarpSt.Mode = [string]$Cfg.WarpMode
        $script:WarpSt.Proto = [string]$Cfg.WarpProto
        $script:WarpSt.Error = ''
        $script:WarpSt.Result = ''
        $script:WarpHistory.Clear(); $script:WarpLastStage = ''
        $script:WarpSt.WantConnect = $true
        Log ('WARP: подключаюсь, режим ' + [string]$Cfg.WarpMode + ', протокол ' + [string]$Cfg.WarpProto)
        Warp-Paint
    })
}
if ($script:BtnWarpOffEl) {
    $script:BtnWarpOffEl.Add_Click({
        if (-not $script:WarpSt) { return }
        if ($script:WarpSt.Busy) {
            $script:WarpSt.Cancel = $true
            Log 'WARP: подключение отменено'
            Warp-Paint
            return
        }
        $script:WarpSt.WantConnect = $false
        $script:WarpSt.WantDisconnect = $true
        Log 'WARP: отключаю туннель'
        Warp-Paint
    })
}
$warpCloseB = $Win.FindName('BtnWarpClose')
if ($warpCloseB) { $warpCloseB.Add_Click({ Hide-Overlay }) }
if ($BtnWarp) { $BtnWarp.Add_Click({ try { Show-Warp } catch { Log ('WARP: ' + $_.Exception.Message) 'err' } }) }
if (-not $script:WarpExe -and -not $script:WarpEmbedded) {
    try { Log 'WARP: клиент Cloudflare не найден — кнопка будет неактивна' 'warn' } catch { }
}
if ($script:WarpEmbedded) { try { Log 'WARP: используется встроенный туннель (usque)' 'ok' } catch { } }
# стартовое состояние точки на кнопке: один запрос status, без постоянного опроса
function Warp-Peek {
    Start-WarpWorker
    if (-not $script:WarpSt) { return }
    $script:WarpSt.StopAfterStatus = $true
    $t = New-Object Windows.Threading.DispatcherTimer
    $t.Interval = [TimeSpan]::FromMilliseconds(1500)
    $t.Add_Tick({ param($s, $e) $s.Stop(); try { Warp-Paint } catch { } })
    $t.Start()
}
try { Warp-Peek } catch { }

