$script:WhatPanelEl = $Win.FindName('WhatPanel')
$script:WhatListEl = $Win.FindName('WhatList')
$script:ChkWhatNeverEl = $Win.FindName('ChkWhatNever')
$script:BtnWhatOkEl = $Win.FindName('BtnWhatOk')

function Add-WhatItem([int]$glyph, [string]$title, [string]$body, [string]$tint) {
    try {
        $g = New-Object Windows.Controls.Grid
        $g.Margin = New-Object Windows.Thickness 0, 0, 0, 10
        $c0 = New-Object Windows.Controls.ColumnDefinition; $c0.Width = [Windows.GridLength]::new(40)
        $c1 = New-Object Windows.Controls.ColumnDefinition; $c1.Width = [Windows.GridLength]::new(1, [Windows.GridUnitType]::Star)
        $g.ColumnDefinitions.Add($c0); $g.ColumnDefinitions.Add($c1)
        $bd = New-Object Windows.Controls.Border
        $bd.Width = 32; $bd.Height = 32; $bd.CornerRadius = New-Object Windows.CornerRadius 10
        $bd.VerticalAlignment = [Windows.VerticalAlignment]::Top
        $cc = ToColor $tint
        $bd.Background = New-Brush ([Windows.Media.Color]::FromArgb(38, $cc.R, $cc.G, $cc.B))
        $bd.BorderBrush = New-Brush ([Windows.Media.Color]::FromArgb(90, $cc.R, $cc.G, $cc.B))
        $bd.BorderThickness = New-Object Windows.Thickness 1
        $tb = New-Object Windows.Controls.TextBlock
        $tb.Text = [char]::ConvertFromUtf32($glyph)
        $tb.FontFamily = New-Object Windows.Media.FontFamily 'Segoe MDL2 Assets'
        $tb.FontSize = 16; $tb.HorizontalAlignment = 'Center'; $tb.VerticalAlignment = 'Center'
        $tb.Foreground = New-Brush $cc
        $bd.Child = $tb
        [void]$g.Children.Add($bd)
        $sp = New-Object Windows.Controls.StackPanel
        [Windows.Controls.Grid]::SetColumn($sp, 1)
        $t1 = New-Object Windows.Controls.TextBlock
        $t1.Text = $title; $t1.FontWeight = 'SemiBold'; $t1.TextWrapping = 'Wrap'
        $t1.SetResourceReference([Windows.Controls.TextBlock]::FontSizeProperty, 'Fs12')
        $t2 = New-Object Windows.Controls.TextBlock
        $t2.Text = $body; $t2.TextWrapping = 'Wrap'; $t2.Margin = New-Object Windows.Thickness 0, 3, 0, 0
        $t2.SetResourceReference([Windows.Controls.TextBlock]::FontSizeProperty, 'Fs11')
        $t2.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
        [void]$sp.Children.Add($t1); [void]$sp.Children.Add($t2)
        [void]$g.Children.Add($sp)
        [void]$script:WhatListEl.Children.Add($g)
    } catch { }
}

function Show-WhatNew {
    if ($script:OnbActive -or -not $script:WhatPanelEl) { return }
    if ($script:WhatListEl -and $script:WhatListEl.Children.Count -eq 0) {
        Add-WhatItem 0xE945 'Подбор вместо ручного перебора' 'В оригинале zapret это два десятка .bat-файлов, которые надо открывать по одному. Здесь одна кнопка: программа проверит все и поставит лучшую первой.' '#F59E0B'
        Add-WhatItem 0xE7BA 'Слежение и автопочинка' 'Связь упала, сменилась сеть, компьютер проснулся — обход перезапустится сам и перейдёт на другую стратегию. В оригинале это делается руками.' '#22C55E'
        Add-WhatItem 0xE8AB 'Понятные названия' 'Классика, Резерв, Умный TLS, Лайт — вместо general (FAKE TLS AUTO ALT2). Номер ALT сохранён, чтобы советы из интернета оставались понятными.' '#7C5CFF'
        Add-WhatItem 0xE774 'WARP одной кнопкой' 'Если обход не справляется, рядом всегда резервный туннель Cloudflare с выбором режима и протокола.' '#3B82F6'
        Add-WhatItem 0xE713 'Настройки без догадок' 'Если настройка недоступна, под ней написано простыми словами, что именно её выключает и куда нажать. Плюс поиск по всем настройкам.' '#10B981'
        Add-WhatItem 0xE790 'Своё оформление' 'Акцентный цвет, фоны, 12 заставок, масштаб шрифта и режим производительности — всё настраивается и запоминается.' '#E879F9'
    }
    try { $script:WarpPanelEl.Visibility = 'Collapsed' } catch { }
    $script:WhatPanelEl.Visibility = 'Visible'; $Overlay.Visibility = 'Visible'
    if (-not $Cfg.Perf) {
        $script:WhatPanelEl.Opacity = 0
        $a = New-Object Windows.Media.Animation.DoubleAnimation(0, 1, [TimeSpan]::FromMilliseconds(260))
        $script:WhatPanelEl.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
    }
    try { Log 'Показано окно с преимуществами 2.0' } catch { }
}

function Close-WhatNew {
    try { if ($script:ChkWhatNeverEl -and $script:ChkWhatNeverEl.IsChecked) { $Cfg.WhatSeen = 17; Request-Save } } catch { }
    try { $script:WhatPanelEl.Visibility = 'Collapsed' } catch { }
    try { $Overlay.Visibility = 'Collapsed' } catch { }
}

if ($script:BtnWhatOkEl) { $script:BtnWhatOkEl.Add_Click({ Close-WhatNew }) }

# ===== Готовые наборы настроек =====
function Set-Tog([string]$psName, [bool]$psVal) {
    $psC = $Win.FindName($psName)
    if (-not $psC -or -not $psC.IsEnabled) { return }
    if ([bool]$psC.IsChecked -eq $psVal) { return }
    $psC.IsChecked = $psVal
    $psC.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Primitives.ButtonBase]::ClickEvent, $psC)))
}
$script:Presets = [ordered]@{
    clean = @{ Ic = 0x1F6E1; T = 'Чистый запрет'; S = 'Только обход и надёжная проверка связи. Эксперименты выключены'; C = '#22C55E'
        Off = @('ChkTurbo', 'ChkGame', 'ChkInstant', 'ChkThrottle', 'ChkEarly', 'ChkNoQuic', 'ChkDnsWarm', 'ChkFlushDns', 'ChkFavOnly'); On = @('ChkKeep', 'ChkMon', 'ChkAutoFix'); Prio = @('yt', 'dc'); Main = @() }
    yt = @{ Ic = 0x25B6; T = 'Максимум YouTube'; S = 'Анти-душилка, без QUIC, ранний сигнал, тёплый DNS. Главный — YouTube'; C = '#EF4444'
        Off = @('ChkInstant', 'ChkFavOnly'); On = @('ChkKeep', 'ChkMon', 'ChkAutoFix', 'ChkThrottle', 'ChkEarly', 'ChkNoQuic', 'ChkDnsWarm'); Prio = @('yt', 'dc'); Main = @('yt') }
    dc = @{ Ic = 0x1F3A7; T = 'Максимум Discord'; S = 'Мгновенное переподключение и ранний сигнал. Главный — Discord'; C = '#5865F2'
        Off = @('ChkThrottle', 'ChkNoQuic', 'ChkFavOnly'); On = @('ChkKeep', 'ChkMon', 'ChkAutoFix', 'ChkInstant', 'ChkEarly', 'ChkDnsWarm'); Prio = @('dc', 'yt'); Main = @('dc') }
    all = @{ Ic = 0x1F525; T = 'Всё и сразу'; S = 'Все эксперименты разом. Рискованно: возможны лишние переключения'; C = '#F59E0B'
        Off = @('ChkFavOnly'); On = @('ChkKeep', 'ChkMon', 'ChkAutoFix', 'ChkTurbo', 'ChkGame', 'ChkInstant', 'ChkThrottle', 'ChkEarly', 'ChkNoQuic', 'ChkDnsWarm', 'ChkFlushDns'); Prio = @('yt', 'dc', 'tg'); Main = @('yt', 'dc') }
}
function Apply-Preset([string]$psKey) {
    $psP = $script:Presets[$psKey]; if (-not $psP) { return }
    if ($psKey -eq 'all') {
        $psR = [Windows.MessageBox]::Show('«Всё и сразу» включит все экспериментальные функции одновременно, в том числе правило брандмауэра «Без QUIC» и геймрежим.`n`nЭто рискованно: возможны лишние переключения стратегий и повышенная нагрузка. Вернуться можно набором «Чистый запрет».`n`nПрименить?', 'Zapret Studio — рискованный набор', 'YesNo', 'Warning')
        if ($psR -ne 'Yes') { return }
    }
    foreach ($psN in @($psP.Off)) { try { Set-Tog $psN $false } catch { } }
    foreach ($psN in @($psP.On)) { try { Set-Tog $psN $true } catch { } }
    $Cfg.PrioServices = @($psP.Prio); $Cfg.PrioMain = @($psP.Main)
    $Cfg.Preset = $psKey
    try { Sync-Conflicts } catch { }
    Request-Save
    Paint-Presets
    Log ('Набор настроек применён: «{0}»' -f $psP.T) 'ok'
}
function Paint-Presets {
    foreach ($psK in @($script:PresetCards.Keys)) {
        $psB = $script:PresetCards[$psK]; $psP = $script:Presets[$psK]
        if ([string]$Cfg.Preset -eq $psK) { $psB.BorderBrush = New-Brush (ToColor $psP.C); $psB.BorderThickness = 2 }
        else { $psB.BorderBrush = $Win.Resources['StrokeBrush']; $psB.BorderThickness = 1 }
    }
    if ($script:PresetStateT) {
        if ($Cfg.Preset -and $script:Presets[[string]$Cfg.Preset]) { $script:PresetStateT.Text = ('Сейчас: «{0}». Любой переключатель можно поменять вручную' -f $script:Presets[[string]$Cfg.Preset].T) }
        else { $script:PresetStateT.Text = 'Выберите набор — нужные переключатели выставятся сами' }
    }
}
try {
    $script:PresetHost = $Win.FindName('PresetHost'); $script:PresetStateT = $Win.FindName('PresetState')
    $script:PresetCards = [ordered]@{}
    if ($script:PresetHost) {
        foreach ($psK in @($script:Presets.Keys)) {
            $psP = $script:Presets[$psK]
            $psX = '<Border Width="200" Margin="0,0,10,10" Padding="12,10" CornerRadius="12" Cursor="Hand" Background="{DynamicResource CardBrush}" BorderThickness="1"><StackPanel>' +
                '<StackPanel Orientation="Horizontal"><Border Width="28" Height="28" CornerRadius="9" Background="#26' + $psP.C.Substring(1) + '"><TextBlock Text="' + [char]::ConvertFromUtf32($psP.Ic) + '" FontFamily="Segoe UI Emoji" FontSize="14" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' +
                '<TextBlock Text="' + (Hub-Esc $psP.T) + '" FontSize="13" FontWeight="Bold" Foreground="' + $psP.C + '" VerticalAlignment="Center" Margin="8,0,0,0"/></StackPanel>' +
                '<TextBlock Text="' + (Hub-Esc $psP.S) + '" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,6,0,0"/></StackPanel></Border>'
            $psB = Hub-Parse $psX
            $psB.Tag = $psK
            $psB.Add_MouseLeftButtonUp({ param($sender, $ea) Apply-Preset ([string]$sender.Tag) })
            $psB.Add_MouseEnter({ param($sender, $ea) $sender.Opacity = 0.85 })
            $psB.Add_MouseLeave({ param($sender, $ea) $sender.Opacity = 1 })
            [void]$script:PresetHost.Children.Add($psB)
            $script:PresetCards[$psK] = $psB
        }
        Paint-Presets
    }
} catch { }


